(window.TNQ=window.TNQ||[]).push({"terms":{"근린주구":{"d":"초등학교 하나가 필요한 인구를 한 단위로 하는 주거 생활권입니다.","r":[]},"개실 시스템":{"d":"사무실을 여러 방으로 나누는 방식입니다.","r":[]},"죠닝":{"d":"높은 건물의 엘리베이터를 몇 개 서비스 그룹으로 나누는 방법입니다.","r":[]},"중앙홀":{"d":"중앙에 큰 홀을 두고 둘레에 전시실을 두는 미술관 형식입니다.","r":[]},"자유개가식":{"d":"이용자가 서가에서 직접 책을 꺼내 고르는 도서 열람 방식입니다.","r":[]},"플라이 갤러리":{"d":"무대 벽 위쪽에 설치한 좁은 통로입니다.","r":[]},"시티 호텔":{"d":"도시 안에 있는 호텔로 커머셜, 터미널, 아파트먼트, 레지덴셜 호텔을 포함합니다.","r":[]},"간호단위":{"d":"병동부에서 간호사 한 팀이 돌보는 병상 묶음입니다.","r":[]},"균형철근비":{"d":"압축콘크리트 한계변형과 인장철근 항복이 동시에 일어나는 철근비입니다.","r":[]},"과소철근보":{"d":"균형보다 철근을 적게 넣어 취성파괴를 피하게 한 보입니다.","r":["균형철근비"]},"단면2차반경":{"d":"단면2차모멘트를 단면적으로 나눈 값의 제곱근으로 좌굴 저항을 나타냅니다.","r":[]},"세장비":{"d":"유효길이를 단면2차반경으로 나눈 값입니다.","r":["단면2차반경"]},"수용률":{"d":"총 설비용량 대비 최대수요전력의 비율입니다.","r":[]},"수격작용":{"d":"배관 속 흐름이 급히 변하면서 충격과 소음이 생기는 현상입니다.","r":[]},"자기사이폰":{"d":"배수가 가득 찬 채 흐르며 트랩 봉수를 끌고 가는 현상입니다.","r":["유도사이폰"]},"유도사이폰":{"d":"윗층 배수로 아래층 트랩 쪽 공기가 감압되어 봉수가 빨려 나가는 현상입니다.","r":["자기사이폰"]},"각개통기":{"d":"기구 트랩마다 통기관을 따로 두는 통기 방식입니다.","r":[]},"노점온도":{"d":"습공기를 식힐 때 수증기가 이슬로 맺히기 시작하는 온도입니다.","r":[]},"엔탈피":{"d":"건공기와 수증기가 함께 가진 열량입니다.","r":[]},"EST":{"d":"작업을 가장 빨리 시작할 수 있는 시간입니다.","r":[]},"EFT":{"d":"작업을 가장 빨리 끝낼 수 있는 시간입니다.","r":["EST"]},"압밀":{"d":"포화된 흙이 눌리며 간극수가 빠지고 부피가 줄어드는 현상입니다.","r":[]},"예민비":{"d":"흙이 교란되기 전후 강도의 비를 나타내는 값입니다.","r":[]},"다포":{"d":"공포를 기둥 위와 기둥 사이에 모두 얹은 한국 목조 건축 양식입니다.","r":[]},"주심포":{"d":"공포를 기둥 위에만 얹은 한국 목조 건축 양식입니다.","r":["다포"]},"대류난방":{"d":"방열기가 데운 공기가 순환하며 실내를 데우는 난방 방식입니다.","r":[]},"증기난방":{"d":"보일러에서 만든 증기가 방열기에서 응축하며 내놓는 열로 난방하는 방식입니다.","r":["온수난방"]},"온수난방":{"d":"보일러에서 데운 온수를 방열기로 순환시켜 난방하는 방식입니다.","r":["증기난방","팽창탱크"]},"하트포드 접속":{"d":"환수관을 균형관으로 보일러에 연결해 보일러 수위가 위험 수위 아래로 내려가는 것을 막는 배관법입니다.","r":["증기난방"]},"역환수 방식":{"d":"방열기마다 배관 길이를 같게 하여 온수 순환을 고르게 하는 복관식 배관법입니다.","r":["온수난방"]},"팽창탱크":{"d":"온수 가열에 따른 물의 체적팽창과 압력을 흡수하는 탱크입니다.","r":["온수난방"]},"수관보일러":{"d":"물이 든 여러 관을 연소가스로 가열해 증기를 만드는 보일러입니다.","r":["연관식"]},"연관식":{"d":"연소가스가 관 속을 지나며 관 밖의 물을 데우는 보일러입니다.","r":["수관보일러"]},"노통연관":{"d":"노통과 연관을 함께 갖춘 보일러로 보유수량이 많은 형식입니다.","r":["연관식"]},"기수드럼":{"d":"수관보일러 위쪽에서 물과 증기를 분리해 모으는 드럼입니다.","r":["수관보일러"]},"흡수식":{"d":"흡수제가 냉매 증기를 흡수하고 발생기에서 다시 분리하는 방식의 냉동기입니다.","r":[]},"서징":{"d":"부하가 낮을 때 압축기에서 냉매 흐름이 주기적으로 맥동하는 불안정 현상입니다.","r":[]},"팬코일 유니트":{"d":"팬과 코일을 갖추고 냉온수를 받아 각 실에서 공기를 냉각·가열하는 장치입니다.","r":["전수방식"]},"콜드 드래프트":{"d":"차가운 창 부근에서 냉각된 공기가 내려와 찬 기류를 느끼는 현상입니다.","r":[]},"전공기방식":{"d":"열을 공기로만 나르는 공기조화 방식입니다.","r":["전수방식","단일덕트"]},"전수방식":{"d":"열을 물로만 나르는 공기조화 방식입니다.","r":["전공기방식","팬코일 유니트"]},"단일덕트":{"d":"냉풍이나 온풍을 한 계통의 덕트로 보내는 공기조화 방식입니다.","r":["이중덕트"]},"이중덕트":{"d":"냉풍과 온풍 두 덕트를 두고 말단에서 섞어 보내는 공기조화 방식입니다.","r":["단일덕트","혼합손실"]},"혼합손실":{"d":"이중덕트에서 냉풍과 온풍을 섞는 동안 생기는 에너지 낭비입니다.","r":["이중덕트"]},"간헐운전":{"d":"난방을 껐다 켰다 반복하는 운전 방식입니다.","r":[]},"전자 브레이크":{"d":"전동기가 멈추면 스프링 힘으로 브레이크 드럼을 눌러 카를 세우는 장치입니다.","r":[]}},"notes":{"0.0035이고, 최대철근비 0.0220과 함께 나옵니다":"fy가 이 값이면 최소철근비는 0.0035이고 최대철근비 0.0220과 짝으로 나옵니다.","0.75(1.4D＋1.7L＋1.7W), 0.9D＋1.3W이다":"풍하중이 있는 하중조합은 0.75(1.4D＋1.7L＋1.7W)와 0.9D＋1.3W입니다.","0.7kg/cm²는 7mAq이므로, 마찰손실이 2mAq이면 9m이고 5mAq이면 12m입니다":"0.7kg/cm²는 7mAq에 해당하므로 마찰손실 2mAq를 더하면 9m, 5mAq를 더하면 12m입니다.","0.9m나 1.2m는 총합과 관계없이 기준에 미달합니다":"각 출구가 0.9m나 1.2m이면 총너비 합계가 충분해도 기준에 미달합니다.","10.5개라서 11개입니다. 소수는 올려서 정수로 맞춥니다":"교실에서는 계산이 10.5개로 나와도 소수는 올려 11개로 맞춥니다.","100cm나 130cm가 아닙니다":"표준관입시험의 낙하높이를 100cm나 130cm로 보면 틀립니다.","12,000L/d, 80℃ 급탕, 10℃ 급수, 비열 4.2kJ/kg·K를 적용하면 40.8kW입니다":"조건을 적용하면 하루 급탕량 12,000L에 해당하는 시간당 부하가 40.8kW입니다.","150,000m2나 300,000m2라도 대상이 아닙니다":"공장은 150,000m2나 300,000m2처럼 커도 이 판별의 대상에 들지 않습니다.","1500mm×1500mm와 기둥 300mm×300mm의 접촉면 최소 철근량은 450mm2입니다":"1500mm×1500mm 독립기초에 300mm×300mm 기둥이 닿는 면은 최소 450mm2의 철근량이 필요합니다.","15cm와 1/30입니다. 2방향 배근 시 두께는 15cm 이상입니다":"플랫슬래브는 두께 15cm와 1/30 기준이 나오며 2방향 배근 시 두께는 15cm 이상입니다.","16층 이상이면서 연면적 100,000m2 이상인 건축물이 대상입니다":"안전영향평가는 층수와 연면적 두 조건이 함께 맞아야 대상이 됩니다.","16층 이상 판매시설이나 바닥면적 합계 5,000m2 이상 종교시설이 해당한다":"판매시설은 16층 이상이거나 종교시설은 바닥면적 합계 5,000m2 이상일 때 다중이용건축물이 됩니다.","17·3.3·2.3을 중심으로 잡습니다":"경사로 기준은 17, 3.3, 2.3이라는 세 수치를 중심으로 구성됩니다.","1m에서 2m가 되면 조도는 1/4입니다":"1m에서 2m로 멀어지면 조도가 1/4밖에 남지 않습니다.","1m에서 4m가 되면 1/16입니다. 800lx도 50lx가 됩니다":"1m에서 4m로 멀어지면 조도가 1/16이 되어 800lx도 50lx가 됩니다.","1간호단위는 보통 30~40병상이고, 간호사 대기소는 각 간호단위 또는 각층·동별로 설치합니다":"간호단위는 보통 병상 30~40개를 묶은 단위이며 간호사 대기소를 간호단위나 층·동별로 둡니다.","1대당 6m² 이상, 피난층 출입구에서 도로 또는 공지까지 30m 이하이며, 벽과 반자의 실내 접촉 마감은 불연재료입니다":"비상용승강기 승강장은 한 대당 6m² 이상이고 피난층 출입구에서 도로까지 30m 이하여야 합니다.","1방향 슬래브 두께는 100mm 이상입니다":"1방향 슬래브의 두께는 어떤 경우에도 100mm보다 얇으면 안 됩니다.","1일 급탕량은 하루 에너지를 구한 뒤 하루의 시간으로 나눕니다":"하루 급탕량은 하루 에너지를 구한 후 하루 시간으로 나누어 시간당 값으로 만듭니다.","1일 붙임 높이 1.5m 정도":"타일 외벽 떠붙임은 하루에 붙이는 높이를 1.5m 정도로 합니다.","1차부터 4차까지만 나오지 않습니다":"부정정 차수는 1차부터 4차까지만 나오지 않고 더 높은 차수도 나옵니다.","2.4 kg/cm²를 물의 상승 높이 24m로 보고, 8m의 높이압 약 80kPa에 70kPa와 20kPa를 더해 약 170kPa를 구합니다":"높이를 압력으로 바꾼 약 80kPa에 70kPa, 20kPa를 합하면 필요한 압력이 약 170kPa입니다.","2005년 60% 이하·2012년 55% 이하로 연도별로 다릅니다":"물시멘트비 상한은 2005년에는 60%, 2012년에는 55%로 해마다 다릅니다.","2005년에는 41m라는 표현을 썼으나 이후 기준선은 31m 초과입니다":"2005년에는 기준 높이를 41m로 적었으나 이후 기준선은 31m 초과로 바뀌었습니다.","200lx는 50lx가 됩니다":"200lx는 거리가 달라지면 50lx가 됩니다.","200m2 미만과 3층 미만, 둘 다 맞아야 합니다. 150m2·2층은 신고 대상입니다":"대수선은 면적과 층수 두 조건을 모두 채워야 하며 150m2·2층은 둘 다 채워 신고 대상입니다.","200m²는 이 기준의 대상이 아닙니다":"오피스텔은 200m²라는 면적이 직통계단 두 곳 설치의 기준이 되지 않습니다.","200㎡당 1대로 계산합니다. 1,400㎡는 7대입니다. 1,900㎡는 10대입니다":"이 시설은 200㎡당 한 대로 계산하므로 1,400㎡는 7대, 1,900㎡는 나머지를 올려 10대입니다.","200대라면 30대씩 6대로는 부족하므로 7대가 필요합니다":"200대 주차장은 승강기 한 대가 30대씩 맡으면 6대로 모자라 7대가 필요합니다.","2015년, 2019년, 2021년에는 정의에 해당하는 계획이 모두 지구단위계획이었습니다":"2015년, 2019년, 2021년 시험의 정의 문제 답은 모두 지구단위계획이었다는 정리입니다.","2017년의 갑종·을종 조합과 2022년의 30분·60분 조합은 기준에 맞지 않습니다":"2017년과 2022년의 방화문 분류를 이렇게 조합해서는 기준에 맞지 않습니다.","2019년과 2021년 E점 문제의 절대값은 90kN·m이며, 절대값을 구할 때는 마지막에 부호를 버립니다":"절대값을 묻는 E점 문제는 90kN·m가 답이고 계산 끝에 부호를 지우면 됩니다.","2022년 기준으로는 용도지구가 아닙니다":"2022년 기준으로는 미관지구가 용도지구에 포함되지 않습니다.","20m³/h를 먼저 초당 유량으로 바꾸고 유속 2m/s로 나누면 단면적이 나오며, 원형 단면으로 환산한 지름은 약 60mm입니다":"20m³/h를 초당 유량으로 고치고 유속 2m/s로 나누면 단면적이 나와 원 지름이 약 60mm입니다.","20층 관광숙박시설도 다중이용건축물이다":"관광숙박시설은 20층이어도 다중이용건축물에 들어갑니다.","20층 호텔과 연면적 90,000m2 공동주택은 아닙니다":"층수와 연면적이 앞에서 본 대상 기준보다 작아 허가권자 판별에서 빠집니다.","20퍼센트 변경도 이 범위 안에 들어갑니다":"지구단위계획의 획지면적 20퍼센트 변경도 변경 허용 범위에 속합니다.","25층 사무소는 대상입니다. 연면적 100,000m2 병원과 200,000m2 호텔은 대상입니다":"25층 사무소와 연구 병원 100,000m2, 호텔 200,000m2는 허가권자 판별에서 대상에 듭니다.","2m를 넘으면 건축법 준용 공작물이다":"옹벽은 높이 2m를 넘으면 건축법을 준용하는 공작물이 됩니다.","2로 나눠 나머지가 나오면 실제 승강기를 1대 더 둡니다":"환산대수를 반으로 나눈 나머지가 있으면 실제 승강기 대수를 하나 올려 둡니다.","2방향 슬래브의 휨모멘트와 비틀림모멘트는 항복선을 따라 균등하게 분포한다고 봅니다":"2방향 슬래브의 휨모멘트와 비틀림모멘트는 항복선 위에서 고르게 퍼진다고 가정합니다.","2선의 접속을 바꾸는 것은 회전 방향을 반대로 하는 방법이다":"2선의 접속을 바꾸면 속도가 아니라 회전 방향이 반대로 바뀝니다.","2차선 너비 6.0m 이상은 기준이 아닙니다":"곡선형 경사로에서 두 차선 너비 6.0m 이상은 기준으로 정해져 있지 않습니다.","3,000mm는 107.1mm입니다. 4m는 143mm, 4.2m는 150mm가 됩니다":"경간이 3,000mm이면 107.1mm, 4m이면 143mm, 4.2m이면 150mm 두께가 필요합니다.","3,000㎡·3,500㎡·4,500㎡는 모두 2대입니다":"비상용승강기 대수 판정에서 3,000㎡, 3,500㎡, 4,500㎡는 모두 같은 2대로 나옵니다.","3,000㎡라면 대상이 아닙니다":"종합병원이 3,000㎡라면 면적 기준에 못 미쳐 다중이용건축물이 아닙니다.","3,000㎡를 기준으로 잡습니다":"면적 3,000㎡가 환산대수 계산에서 기준이 되는 경계값입니다.","30㎡나 33㎡는 기준이 아닙니다":"거실 바닥면적 30㎡나 33㎡는 비상탈출구 설치 기준이 아닙니다.","30개 설치를 제시한 문항은 가답안이 48m³였으나 문제 오류로 확정답안에서 모두 정답 처리되었습니다":"문제에 오류가 있어 30개 설치를 제시한 문항은 가답안 48m³와 무관하게 확정답안에서 전원 정답이 되었습니다.","3·5·6·8mm 순서이며, 10mm와 13mm는 5mm 구간입니다":"모살용접 최소 사이즈는 3, 5, 6, 8mm 순서이며 10mm와 13mm는 5mm 구간입니다.","3cm는 0.375cm, 2cm는 0.25cm가 됩니다":"춤이 3cm일 때 0.375cm, 2cm일 때 0.25cm가 되는 값을 계산합니다.","3m 이내마다 너비 1.2m 이상 계단참":"계단 높이가 3m를 넘으면 3m 이내마다 너비 1.2m 이상 계단참을 둡니다.","3층으로 구분합니다. 주거 단위 하나가 3층으로 구성됩니다":"트리플렉스는 주거 단위 하나가 3층으로 이루어진 형식입니다.","3층 이상이면서 해당 용도 거실 바닥면적 합계 200m² 이상입니다":"판매시설은 면적 외에 3층 이상이라는 층 조건이 함께 붙는 점이 다릅니다.","45° 이상이 기준이며 30° 이상이 아닙니다":"청소구는 방향을 바꾸는 각도가 45° 이상일 때 두며 30° 이상이 기준이 아닙니다.","490은 최저 항복강도가 아니고 A·B·C 끝글자는 충격흡수에너지 보증에 따름":"SM 490A에서 490은 최저 항복강도 값이 아니고 끝글자 A, B, C는 충격흡수에너지 보증에 따라 붙습니다.","4m를 넘으면 신고 대상이다":"광고판은 높이 4m를 넘으면 공작물 신고 대상입니다.","4면은 간선도로로 구획합니다. 통과교통은 주구 안을 관통시키지 않고 외곽으로 쉽게 우회시킵니다":"근린주구는 4면을 간선도로로 구획하고 통과교통은 외곽으로 우회시킵니다.","5,000㎡ 기준으로 문화 및 집회시설, 종교시설, 운수시설, 업무시설, 숙박시설은 확보 대상입니다":"공개공지를 확보해야 하는 건축물의 용도는 이 다섯 가지입니다.","5,000㎡든 6,000㎡든 면적 기준 대상이 아닙니다":"다중이용건축물 면적 기준의 용도 목록에 업무시설은 없어 면적이 커도 대상이 아닙니다.","5,000㎡여도 대상이 아닙니다":"체육관은 5,000㎡여도 면적 기준에 해당하는 용도가 아니어서 대상이 아닙니다.","5,000㎡ 이상입니다. 딱 5,000㎡도 들어갑니다":"다중이용건축물의 면적 기준은 5,000㎡ 이상이며 5,000㎡ 정확히도 이에 듭니다.","5.0m 기둥은 양단 힌지일 때 5.0m":"양단 힌지인 5.0m 기둥의 유효좌굴길이는 실제 길이와 같은 5.0m입니다.","50, 90, 110, 130이 아니라 80입니다":"기준 방수량은 50, 90, 110, 130 중 어느 것도 아니고 80입니다.","500m2 이상일 때도 제출 대상이다":"근린생활시설 중 목욕장 등은 500m2 이상일 때도 에너지절약계획서 제출 대상입니다.","50세대 이상 공동주택이 제출 대상입니다":"에너지절약계획서는 공동주택이 50세대 이상이면 내는 서류입니다.","50층 이상이거나 높이 200m 이상이다":"초고층 건축물은 50층 이상이거나 높이가 200m 이상인 건축물입니다.","5층 이상 종교집회장·장례식장·상점은 피난용 설치 대상":"5층 이상의 종교집회장, 장례식장, 상점은 피난용 옥상광장 설치 대상입니다.","6m를 넘으면 신고 대상이다":"기념탑과 굴뚝은 높이 6m를 넘으면 신고 대상입니다.","6층 이상이어도 피난층의 거실은 배연설비 판단에서 제외합니다":"6층 이상 건축물이라도 피난층의 거실은 배연설비 설치 판단에서 뺍니다.","70% 기준에서는 주차장 외의 용도를 구별합니다":"70% 기준에서는 주차장 외에 어떤 용도를 함께 둘 수 있는지를 구별합니다.","70℃ 급탕, 10℃ 급수이므로 온도차는 60℃입니다":"급탕 70℃에서 급수 10℃를 빼 온도차가 60℃입니다.","80kW, 90kW, 100kW를 먼저 더하면 270kW입니다":"세 용량 80kW, 90kW, 100kW를 합치면 270kW가 됩니다.","8·10·15인승은 1대분으로 셉니다. 16·24인승은 2대분입니다":"8·10·15인승은 한 대분으로 치고 16·24인승은 두 대분으로 칩니다.","8m를 넘으면 신고 대상이다":"고가수조는 높이 8m를 넘으면 신고 대상입니다.","As=1500mm², fy=300MPa, fck=24MPa, b=300mm이면 a=73.53mm입니다":"주어진 철근 단면적, 항복강도, 콘크리트 강도, 폭을 평형식에 넣으면 a가 73.53mm입니다.","A점이나 B점의 모멘트는 힘×거리의 합으로 구합니다":"한 점의 모멘트는 그 점에서 각 힘까지 거리를 힘에 곱한 값을 모두 더하면 나옵니다.","C점, D점, E점처럼 그 점의 좌우 기울기를 각각 구하고, 기울기의 변화량으로 힘의 절댓값을 찾습니다":"집중력이 걸린 C점, D점, E점은 좌우 기울기를 따로 구해 그 변화량으로 힘의 절댓값을 찾습니다.","C점 0, D점 16kN·m입니다":"CD 부재 문제의 값은 C점이 0이고 D점이 16kN·m로 나옵니다.","C점·E점이나 AC구간의 단면력을 계산합니다":"그다음 C점, E점, AC구간 같은 곳의 단면력을 계산합니다.","C점의 휨모멘트와 E점·AC부재의 전단력은 모두 이 한 순서로 풉니다":"C점의 휨모멘트와 E점·AC부재의 전단력은 같은 방식으로 한꺼번에 풀립니다.","EI가 클수록 작아지므로 I를 크게 하면 처짐이 줄어듭니다":"EI가 클수록 처짐이 작아지므로 I를 키우면 보의 처짐이 줄어듭니다.","EST와 EFT는 작업의 흐름에 따라 전진 계산합니다":"EST와 EFT는 작업이 이어지는 순서를 따라 앞에서 뒤로 계산합니다.","E와 길이 단위를 한 체계로 맞춘 뒤 공식에 넣습니다":"E와 길이의 단위를 하나로 통일한 다음 공식에 넣어야 합니다.","F10T-M20에서는 47.1×(1-55÷165)=31.4kN입니다":"인장력이 함께 걸려 F10T-M20의 허용전단력은 31.4kN으로 줄어듭니다.","F10T-M24, 설계볼트장력 200kN이면 0.13×24×220=686,400N·mm입니다":"설계볼트장력 200kN이면 220으로 키운 표준볼트장력에 0.13과 24를 곱해 686,400N·mm입니다.","I=a⁴/12가 되어 좌굴하중에서 a⁴에 비례한다는 결론으로 바로 이어집니다":"a×a 정사각형의 I는 a⁴/12이므로 좌굴하중이 한 변의 네제곱에 비례하게 됩니다.","Ig/yt=bh²/6이므로 Mcr=fr·bh²/6으로 바로 계산합니다":"Ig/yt가 bh²/6이므로 균열모멘트는 Mcr=fr·bh²/6으로 곧장 구합니다.","Ig=bh³/12이고, 중립축에서 인장연단까지 거리는 yt=h/2입니다":"직사각형 단면의 Ig는 bh³/12이고 중립축에서 인장연단까지 yt는 h/2입니다.","Ix와 Iy를 더해 3,200,000cm4입니다":"두 직교축 값을 합산하면 극관성 값이 3,200,000cm4가 됩니다.","I은 0.11g, II는 0.07g이다":"지진구역 I의 지진구역계수는 0.11g, II는 0.07g입니다.","MPa와 mm를 쓰면 결과는 N이므로 kN으로 바꿉니다":"MPa와 mm로 계산하면 단위가 N이므로 kN으로 환산합니다.","Mo=25×10⁴N·m이면 단부 16.25×10⁴":"Mo가 25×10⁴N·m이면 받침 단부에는 16.25×10⁴가 배분됩니다.","Mo=900kN·m이면 부 585":"Mo=900kN·m이면 부모멘트는 585입니다.","Mo=900kN·m이면 정 315":"Mo=900kN·m이면 정모멘트는 315입니다.","Mo는 부 65%, 정 35%로 끊습니다":"Mo는 부모멘트 65%, 정모멘트 35%로 나눕니다.","Q=Av로 구합니다. 유속 2.5m/s, 유량 1m³/min이면 구경은 92mm입니다":"토출구 구경은 Q=Av에서 구하며 2.5m/s의 유속과 1m³/min의 유량이면 92mm입니다.","Q는 그 점에서 단면을 잘랐을 때 바깥쪽 부분의 중립축에 대한 단면1차모멘트, I는 전체 단면의 단면2차모멘트, t는 그 점의 폭입니다":"Q는 그 점 바깥쪽 조각이 중립축에 대해 갖는 단면1차모멘트, I는 전체 단면2차모멘트, t는 그 점의 폭입니다.","U형 또는 A형으로 나옵니다. 교실 수와 학급 수가 일치하며, 초등학교 저학년에 가장 권장됩니다":"종합교실형은 평면이 U형이나 A형이고 교실 수와 학급 수가 같으며 초등학교 저학년에 가장 권합니다.","V=0인 단면까지 누적한 값이 최대모멘트 후보입니다":"전단력이 0이 되는 단면까지 합해 온 값이 최대모멘트 후보가 됩니다.","V=10kN이면 Aw=(300-2×9)×6.5를 써서 약 5.46MPa입니다":"이 H형강은 웨브 면적을 (H-2tf)tw로 잡고 전단력 10kN을 나눈 값이 약 5.46MPa입니다.","VAV 방식·외기냉방 방식·고효율 열원기기가 절약 수단이다":"VAV 방식, 외기냉방 방식, 고효율 열원기기가 공조 에너지 절약 수단입니다.","a=4, m=7, b=8이면 (4+28+8)÷6=6.7주입니다":"낙관 4주, 개연 7주, 비관 8주를 대입한 (4+28+8)÷6의 결과가 6.7주입니다.","b=250mm, h=500mm, fck=24MPa, λ=1이면 fr=0.63√24이고 Mcr은 약 32.2kN·m입니다":"이 조건에서 균열모멘트는 약 32.2kN·m로 fr은 0.63에 √24를 곱한 값입니다.","b=350mm, h=700mm, fr=3MPa이면 Mcr=3×350×700²/6=85.75kN·m입니다":"fr이 3MPa로 주어지면 폭 350mm와 높이 700mm로 균열모멘트가 85.75kN·m입니다.","d=540mm이고 a가 약 65mm이면 540-65/2=507.5mm입니다":"d가 540mm이고 a가 65mm 안팎이면 응력중심간 거리가 507.5mm입니다.","fck=24MPa, a=100mm, fy=300MPa, d=800mm이면 0.0085입니다":"주어진 값을 넣으면 철근비가 0.0085로 계산됩니다.","fck=24MPa, b=400mm, a=100mm이면 816kN이고, fck=27MPa, b=300mm, a=120mm이면 826.2kN입니다":"첫 조건은 816kN, 두 번째 조건은 826.2kN의 압축력이 나옵니다.","fck와 fr을 MPa, 단면 치수를 mm로 넣으면":"fck와 fr은 MPa, 치수는 mm로 넣어 계산합니다.","fr=0.63λ√fck로 바꿉니다":"fck가 주어지면 휨인장강도는 fr=0.63λ√fck로 바꿔 씁니다.","fy=3000kg/cm²에서 30cm², fy=4000kg/cm²에서 약 23cm²이며, mm 단위의 같은 유형은 3000mm²입니다":"fy가 3000이면 30cm², 4000이면 약 23cm²가 필요하고 mm 단위의 같은 유형은 3000mm²가 답입니다.","kN·m, tf·m, t·m, kgfm처럼 단위가 달라지므로 주어진 단위로 값을 구합니다":"kN·m, tf·m, t·m, kgfm처럼 단위가 달라질 수 있으니 문제에서 준 단위로 값을 구합니다.","kN·m로 바꾸려면 마지막에 10⁶으로 나눕니다":"계산 끝에 10⁶으로 나누면 N·mm가 kN·m가 됩니다.","kcal/m²h℃가 아닙니다":"열전도율의 단위가 kcal/m²h℃라는 말은 틀립니다.","s=8mm, L=400mm이면 384mm이고, L=500mm이면 484mm입니다":"s=8mm에서 L=400mm의 유효길이는 384mm, L=500mm의 유효길이는 484mm입니다.","s=8mm, L=400mm인 양면은 5.6×384×2=4300.8mm²이므로 약 4300mm²(43cm²)입니다":"양면 용접은 한 면의 5.6×384에 2를 곱한 4300.8mm², 곧 약 43cm²입니다.","t<6mm이면 t, t≥6mm이면 t-2mm입니다":"모살용접 최대 사이즈는 모재 두께 t가 6mm보다 작으면 t, 6mm 이상이면 t-2mm입니다.","x축과 y축 대신 그림에 표시된 주축을 비교합니다":"기울어진 단면은 x축과 y축 대신 그림에 표시된 주축끼리 비교합니다.","ø=0.75 조건에서 254kN입니다":"설계인장강도는 ø=0.75를 적용했을 때 254kN입니다.","λ=100이면 유효길이가 실제 길이와 같으므로 양단 힌지입니다":"유효길이가 실제 길이와 같으면 양단 힌지이고 λ=100이 이 경우에 해당합니다.","ρb=As/(bd)로 정리하며, b와 d가 제시돼도 균형철근비 자체는 재료강도에 따라 정해집니다":"ρb는 As/(bd)로 정리되며 b와 d가 주어져도 균형철근비는 재료강도가 좌우합니다.","τ최대=3V/(2A)로, 평균의 1.5배입니다":"식 3V/(2A)로 구하는 직사각형의 최대값은 평균보다 1.5배 큽니다.","τ최대=4V/(3A)입니다. 면적 A=πr²를 구한 뒤 평균의 4/3배를 적용합니다":"원형의 최대값은 4V/(3A)이므로 πr²로 A를 구하고 평균에 4/3을 곱합니다.","‘각 기구의 트랩마다 통기관을 설치해 통기수평지관에 연결’은 루프통기가 아니라 각개통기입니다":"기구마다 트랩에 통기관을 달아 통기수평지관으로 모으면 루프통기가 아니라 각개통기입니다.","‘대상에 속하는 것’이 나오면 이 다섯 용도를 찾습니다":"보기에서 대상에 속하는 것을 고르라 하면 문화·종교·운수·업무·숙박 다섯 용도를 기준으로 삼습니다.","‘미국은 클로즈드 시스템, 우리나라는 오픈 시스템’이라는 설명은 맞지 않습니다":"미국은 클로즈드 시스템, 우리나라는 오픈 시스템이라는 구분은 사실과 다릅니다.","‘하수종말처리시설 제외’라는 문구가 붙으면 광역시설이 아닙니다":"하수종말처리시설 제외라는 문구가 붙은 하수도는 광역시설에 들지 않습니다.","가까운 거리에서 많은 관객을 수용하며":"애리나형은 가까운 거리에서 많은 관객을 수용할 수 있습니다.","가로축에 층별 요인이나 특성, 세로축에 불량건수나 불량손실금액 등을 놓아 불량점유율을 나타냅니다":"파레토도는 가로축에 층별 요인, 세로축에 불량건수나 손실금액을 놓고 불량의 점유율을 보여 줍니다.","가볍고 시공이 쉬우며, 겹침 두께가 작아 물매를 완만하게 할 수 있습니다":"금속판 지붕은 가벼워 시공이 수월하고 이음 겹침이 얇아 지붕 경사를 낮게 낼 수 있습니다.","가스계량기와 전기계량기는 60cm 이상 띄우고":"가스계량기와 전기계량기 사이는 60cm 이상 떨어뜨려 놓아야 합니다.","가압송수장치의 송수량도 이 압력과 유량을 기준으로 기준개수의 모든 헤드 방수량을 충족해야 합니다":"가압송수장치도 이 압력과 유량을 기준으로 기준개수 모든 헤드의 방수량을 채우는 송수량이어야 합니다.","가우디의 사그리다 파밀리아, 핵토르 기마르의 파리 지하철역 입구, 빅터 오르타의 타셀 주택이 속합니다":"아르누보 대표작으로는 가우디의 사그리다 파밀리아, 기마르의 파리 지하철역 입구, 오르타의 타셀 주택을 듭니다.","가장 기본은 주택 규모와 건폐율입니다":"주거밀도에서 가장 기본이 되는 것은 주택 규모와 건폐율입니다.","가장 높은 수도꼭지까지의 높이":"직결에 필요한 본관 압력에는 가장 높은 수도꼭지까지의 높이가 들어갑니다.","가장 많이 반복된 자리는 광장, 도로, 자동차정류장의 세분입니다":"반복해 나오는 자리는 광장, 도로, 자동차정류장을 다시 나눈 세부 종류입니다.","각 방향 최소치수는 그 방향 기둥중심거리의 1/30 이상입니다":"플랫슬래브 기둥의 각 방향 치수는 그 방향 기둥중심거리의 1/30 이상이어야 합니다.","각 부분의 높이는 그 부분에서 도로 반대쪽 경계선까지의 수평거리의 3배 이하입니다":"건축물 높이는 그 부분에서 도로 반대쪽 경계선까지 거리의 3배를 넘을 수 없습니다.","각 세대가 전용 정원을 가지며, 자연형은 상향식과 하향식 모두 스플릿 레벨이 가능합니다":"테라스하우스는 세대마다 전용 정원이 있고 자연형은 상향식과 하향식에서 모두 스플릿 레벨이 가능합니다.","각 실의 수배관 때문에 누수 우려가 생깁니다":"각 실까지 물 배관이 들어가므로 이음부에서 물이 샐 가능성이 생기는 약점입니다.","각 실이나 존의 온도를 개별제어할 수 있고, 일사량 변화가 심한 페리미터 존에도 적합합니다":"방이나 존마다 따로 온도를 맞출 수 있어 햇빛 영향이 큰 외주부에도 알맞습니다.","각 출구의 유효너비도 1.5m 이상이어야 합니다":"출구 하나하나의 폭 최소는 1.5m이며 총합 기준과는 별도 조건입니다.","각 층 같은 위치에 두고 공급 범위의 중앙에 둔다":"전기샤프트는 각 층 같은 위치에 두며 공급 범위의 중앙에 둡니다.","각 층 바닥면적이 작을 때 많이 씁니다":"편심코어는 층 바닥면적이 작은 건물에서 흔히 씁니다.","간단한 수법을 효율적으로 쓰고, 문제해결을 위한 기술적 뒷받침도 함께 둡니다":"수법은 단순한 것을 효율 있게 쓰고 문제를 푸는 기술적 뒷받침을 함께 갖춥니다.","간접배수로 하고 최하단에 배수밸브를 둔다":"넘침관은 간접배수로 하고 저수조 맨 아래에 배수밸브를 둡니다.","간포를 받치기 위해 창방 외에 평방이 더해지고, 팔작지붕이 많습니다":"다포식은 간포를 받치려고 창방 위에 평방을 더 얹고 팔작지붕을 얹는 경우가 많습니다.","간호단위의 병상수가 지나치게 많으면":"간호단위의 병상수가 지나치게 많으면 어떻게 되는지를 따지는 항목입니다.","간호사 동선이 길어지고 전체 환자 상태를 파악하기 어려워집니다":"병상이 지나치게 많으면 간호사가 걷는 거리가 늘고 환자 전체 상태를 살피기 어렵습니다.","감압밸브 설치와 큰 관경은 발생 원인이 아닙니다":"감압밸브를 달거나 관경을 크게 하는 것은 수격작용의 원인이 아닙니다.","강도감소계수는 0.70이 아니다":"전단력과 비틀림에 대한 강도감소계수가 0.70이라는 말은 틀립니다.","강도시험을 하지 않고 조강 포틀랜드 시멘트를 쓴 기둥이며 평균기온이 20℃ 이상이면 해체는 2일 이상입니다":"조강 포틀랜드 시멘트로 친 기둥은 강도시험을 하지 않을 때 평균기온이 20℃ 이상이면 2일 이상 지나야 거푸집을 뗍니다.","강연·콘서트·독주에 적합하다":"프로시니엄형 극장은 강연, 콘서트, 독주에 적합합니다.","강한 음영이 생기지만 경제적이다":"직접조명은 강한 그림자가 생기지만 경제적입니다.","같은 B점이라도 겔버보의 힌지인지 고정단인지에 따라 모멘트가 완전히 달라집니다":"B점이 겔버보의 힌지냐 고정단이냐에 따라 같은 점의 모멘트 값이 크게 갈립니다.","같은 건물 안에서 면적 증가 없이 위치만 바꾸는 경우와 바닥면적 합계가 100m2 미만인 경우는 신고 대상이 아니었습니다":"같은 건물 안에서 위치만 바꾸거나 100m2 미만의 소규모는 과거 신고 대상에서 빠졌습니다.","같은 군의 엘리베이터는 서비스 층을 같게 합니다":"한 군에 속한 엘리베이터는 정지하는 서비스 층이 서로 같아야 합니다.","같은 그림에서 2005년과 2020년 모두 값은 1300이며, 하중 하나만이 아니라 전체 하중의 모멘트를 합하여 구합니다":"같은 그림의 문제에서 값은 1300이며 하중 하나가 아니라 모든 하중의 모멘트를 합해 구합니다.","같은 도 안이면 관할 시장 또는 군수가 공동 수립하고, 둘 이상의 시·도에 걸치면 관할 시·도지사가 공동 수립합니다":"같은 도 안의 광역계획권은 시장·군수가, 여러 시·도에 걸치면 시·도지사가 함께 수립합니다.","같은 슬럼프에서 물시멘트비가 클수록 적고, 자갈이 클수록 적으며, 기온이 높을수록 적습니다":"슬럼프가 같을 때 물시멘트비가 크고 자갈이 크며 기온이 높을수록 필요한 시멘트가 줄어듭니다.","같은 조건에서 0.0213이고, ρb=0.039이면 0.028314이므로 75%를 그대로 곱하지 않습니다":"개정 규정은 75%를 단순히 곱하지 않아 같은 조건에서 0.0213, ρb=0.039에서는 0.028314가 됩니다.","같은 통로의 벽을 난연재료로 하는 것은 부적합합니다":"같은 통로의 벽을 난연재료로 하면 내장재료 기준에 맞지 않습니다.","개별관람실 바깥쪽의 양쪽과 뒤쪽에 각각 복도를 두는 계획도 기준에 맞습니다":"관람실 양옆과 뒤쪽으로 복도를 두르는 배치는 규정에 어긋나지 않습니다.","개별난방이어도 연도는 개별연도가 아니라 공동연도입니다":"난방이 세대별 개별이어도 연도만큼은 하나로 모은 공동연도로 짓습니다.","개인적인 환경조절이 용이하지 않습니다":"개방식은 개인적인 환경조절이 쉽지 않습니다.","개재 자체의 반경만 쓰지 않고, 개재 중심축과 조립재 중심축 사이 거리의 효과를 더합니다":"조립압축재 반경은 개재 하나의 반경에 개재 중심축과 조립재 중심축 간격의 영향을 더해 구합니다.","객석에서 보이지 않게 설치해 대사를 불러 주는 곳입니다":"프롬프터 박스는 관객 눈에 띄지 않게 마련해 배우에게 대사를 일러 주는 자리입니다.","거리별 조도는 E₂=E₁×(r₁/r₂)²로 계산하세요":"거리별 조도는 E₂=E₁×(r₁/r₂)²로 거리 비의 제곱에 반비례해 구합니다.","거실 바닥면적 50m² 이상이면 직통계단 외에 비상탈출구와 환기통을 설치합니다":"지하층은 거실이 50m² 이상이 되면 직통계단 하나로 끝나지 않고 탈출구와 환기통도 붙습니다.","거실 바닥면적 합계 200m² 이상":"지하층은 거실 바닥면적 합계 200m² 이상이면 직통계단을 두 곳 이상 설치하는 대상입니다.","거실 바닥면적 합계가 1000㎡ 이상이면 설치합니다":"환기설비는 지하층 거실 바닥면적 합계가 1000㎡ 이상일 때 설치합니다.","거실에서 지상으로 통하는 주된 복도와 주된 계단은 준불연재료가 적합합니다":"아파트에서 거실로부터 지상으로 통하는 주된 복도와 계단은 준불연재료로 해도 적합합니다.","거실의 바닥면적이 50㎡ 이상인 층은 직통계단 외에 피난층 또는 지상으로 통하는 비상탈출구 및 환기통을 설치합니다":"지하층은 거실 바닥면적 50㎡ 이상이면 직통계단 말고도 비상탈출구와 환기통을 따로 설치합니다.","거실·침실·식당·부엌을 모두 분리하면 면적 절약에 불리합니다":"작은 주호에서 거실, 침실, 식당, 부엌을 모두 분리하면 면적 절약에 불리합니다.","거푸집 안에 자갈을 먼저 채우고 공극에 유동성 좋은 모르타르를 주입하는 공법입니다":"프리팩트 콘크리트는 거푸집 안에 자갈을 먼저 쌓고 틈새로 묽은 모르타르를 밀어 넣는 공법입니다.","거푸집판 간격을 유지하면서 콘크리트 측압을 최종 지지하고, 거푸집이 벌어지지 않게 하는 긴장재입니다":"폼타이는 거푸집판 사이를 일정하게 붙들고 콘크리트의 옆 압력을 끝까지 지탱해 거푸집이 벌어지지 않게 합니다.","건공기와 수증기에 포함된 열량입니다":"엔탈피는 건공기와 수증기가 함께 가진 열량입니다.","건구온도 대신 습구온도를 쓰는 지표가 아니다":"수정유효온도를 건구온도 대신 습구온도를 넣어 만든 지표로 보면 틀립니다.","건물의 종류와 용도에 따라 부하 요소가 달라집니다":"건물의 종류와 쓰임새가 달라지면 부하를 이루는 요소도 달라집니다.","건설사업자원 통합 전산망이다":"건설 CALS는 건설사업 자원을 통합하는 전산망입니다.","건조하고 깨끗한 바탕에 솔·롤러·뿜칠기 등으로 규정량을 균일하게 바릅니다":"프라이머는 마르고 깨끗한 바탕에 솔, 롤러, 뿜칠기로 정해진 양을 고르게 바릅니다.","건축계획서·배치도·실내마감도":"건축허가 설계도서에는 건축계획서, 배치도, 실내마감도가 있습니다.","건축면적과 지역·지구 및 도시계획사항도 표시한다":"건축계획서에는 건축면적과 지역·지구 및 도시계획사항도 표시합니다.","건축면적·연면적·층수·높이를 늘리는 것이고":"증축은 건축면적, 연면적, 층수, 높이를 늘리는 것입니다.","건축물 내부에서 계단실로 통하는 출입구의 유효너비는 0.9m 이상이고, 그 출입구에는 피난 방향으로 열 수 있는 갑종방화문을 설치합니다":"계단실 출입구는 유효너비 0.9m 이상이며 피난 방향으로 열리는 갑종방화문을 달아야 합니다.","건축물의 2층이 다중주택이고 그 용도 면적이 400㎡ 이상인 경우, 2층이 숙박시설이고 그 용도 면적이 1,000㎡인 경우는 대상입니다":"2층이 다중주택이고 그 용도 면적이 400㎡ 이상이거나 2층 숙박시설이 1,000㎡이면 대상입니다.","건축물의 다른 부분과 내화구조로 구획합니다. 규정은 승강로의 구조를 정할 뿐 승강로의 바닥면적 기준은 두지 않습니다":"승강로는 다른 부분과 내화구조로 구획하되 승강로 바닥면적 기준은 정해져 있지 않습니다.","건축물의 용도·건폐율·용적률·높이·배치·형태·색채입니다":"지구단위계획은 건축물의 용도, 건폐율, 용적률, 높이, 배치, 형태, 색채도 정합니다.","건축물의 용도별 면적·규모·주차장 규모를 포함한다":"건축계획서에는 건축물의 용도별 면적, 규모, 주차장 규모가 들어갑니다.","건축법상 분류된 시설군이 아니다":"공업시설군은 건축법에서 나눈 시설군이 아닙니다.","건축선의 수직면을 넘을 수 없습니다. 다만 지표하의 부분은 제외합니다":"건축물과 담장은 건축선의 수직면을 넘을 수 없고 땅속 부분만 예외로 봅니다.","건축주가 공사 완료 후 사용승인 신청 · 감리완료보고서 첨부":"사용승인은 공사가 끝난 뒤 건축주가 감리완료보고서를 붙여 신청합니다.","건축하는 건축물도 면제 대상이다":"읍·면의 자연녹지지역에 건축하는 건축물도 대지 조경 면제 대상입니다.","건축 형식은 주변 조건에 따라 자유롭게 이루어집니다":"리조트 호텔은 건물 형식을 주변 조건에 맞춰 자유롭게 정할 수 있습니다.","건폐율·용적률·건축물 높이를 완화합니다. 완화 항목은 이 세 가지입니다":"지구단위계획에서 완화하는 항목은 건폐율, 용적률, 건축물 높이 세 가지입니다.","검토와 조치의 자리를 바꾸지 않습니다":"검토와 조치의 순서를 서로 바꾸어서는 안 됩니다.","검토한 뒤 조치하는 순서입니다":"품질관리 사이클에서 검토한 뒤 조치하는 순서를 지킵니다.","겔버보라고 모든 지점의 모멘트가 0인 것은 아닙니다":"겔버보의 모든 지점에서 모멘트가 0이 되는 것은 아닙니다.","결론을 학문적으로 표현해야 한다는 말은 유의사항이 아닙니다":"결론을 학문적으로 표현하라는 것은 통계수법을 쓸 때의 유의사항에 속하지 않습니다.","경관지구·방재지구·취락지구·보호지구가 용도지구입니다":"현행 용도지구는 경관지구, 방재지구, 취락지구, 보호지구입니다.","경량화하고 구조 강성을 높인다":"연약지반의 부동침하를 막으려면 건물을 가볍게 하고 구조 강성을 높입니다.","경미한 황갈색 녹이 생겼다는 이유만으로 사용 불가라고 단정하지 않습니다":"철근에 가벼운 황갈색 녹이 났다는 이유만으로 쓸 수 없다고 판단하지는 않습니다.","경사가 심할수록 밀도가 높고 평지보다 많은 인구를 수용할 수 있으며, 시각적 인공테라스형은 위층으로 갈수록 내부면적이 작아집니다":"경사가 급할수록 평지보다 밀도를 높일 수 있고 인공테라스형은 위층으로 갈수록 내부 면적이 줄어듭니다.","계단 또는 엘리베이터 홀에서 각 주거 단위로 바로 들어갑니다":"홀형은 계단이나 엘리베이터 홀에서 바로 각 세대 문으로 이어집니다.","계단실을 포함하고 각 공간은 층마다 공통 위치에 둡니다":"코어에 계단실이 들어가며 코어 안 각 공간은 모든 층에서 같은 자리에 놓습니다.","계단실의 구획과 연결을 먼저 봅니다":"내부 피난계단은 계단실을 어떻게 구획하고 어디로 연결하는지부터 봅니다.","계단실의 실내에 접하는 부분 마감은 불연재료입니다. 준불연재료는 안 됩니다":"계단실 안쪽 마감은 불연재료여야 하고 그보다 낮은 준불연재료는 허용되지 않습니다.","계산 결과는 300,000kcal/h(300Mcal/h)이며 비열 4.2kJ/kg·K를 쓰면 350kW입니다":"결과는 300,000kcal/h(300Mcal/h)이고 kW 단위로는 350kW입니다.","계산 결과는 대상 건축물의 교통수요량에 맞아야 합니다":"구한 대수는 대상 건축물이 필요로 하는 교통수요량과 맞아야 합니다.","계산을 시작할 때 시계방향과 반시계방향 중 하나를 양(+)으로 정하고 끝까지 유지합니다":"계산을 시작할 때 시계방향이든 반시계방향이든 하나를 양(+)으로 정해 끝까지 같게 씁니다.","계산 전에 맞지 않는 선도를 지울 수 있습니다":"선의 모양을 알면 계산하기 전에 맞지 않는 선도를 지울 수 있습니다.","계산할 면적은 6층 이상 거실면적의 합계입니다":"승용승강기 대수는 6층 이상 거실면적의 합계를 기준으로 계산합니다.","계통별 용량제어와 부하변동에 따른 실내 방열량 제어도 곤란합니다":"증기난방은 계통별 용량 조절과 부하가 변할 때의 방열량 조절이 모두 어렵다는 내용입니다.","고가수조가 필요 없지만 정전 시 급수가 곤란하고, 고가수조방식보다 급수압 변동이 큽니다":"압력수조방식은 고가수조가 없어도 되지만 정전되면 급수가 곤란하고 고가수조방식보다 급수압이 많이 변합니다.","고가탱크 설치가 어렵거나 같은 높이의 다른 장비·최상층에서 적정 압력을 얻기 어려울 때 채택할 수 있지만, 공급압력 변화가 심하고 수질오염이 우려된다는 조건은 채택 이유와 거리가 멉니다":"압력수조방식은 고가탱크 설치가 어렵거나 최상층에서 적정 압력을 얻기 어려울 때 채택하며 압력 변화나 수질오염 우려는 채택 이유와 거리가 멉니다.","고객 동선을 창구 위치로 정하고":"은행은 고객 동선을 먼저 보고 창구 위치를 정합니다.","고압수은램프보다 연색성이 좋고":"할로겐전구는 고압수은램프보다 연색성이 좋습니다.","고압증기를 다량으로 필요로 하는 공업용에는 부적당합니다":"공업용은 고압증기를 많이 써야 하는데 고온수난방으로는 이를 대신하기 어렵다는 한계입니다.","고정단 모멘트를 구할 수 있습니다":"그 식에서 고정단 모멘트가 나옵니다.","고정 칸막이가 없으므로 개인 공간으로 나누어 독립성과 프라이버시를 확보하기는 쉽지 않습니다":"고정 칸막이가 없어서 개인 공간을 나눠 독립성과 프라이버시를 지키기가 쉽지 않습니다.","고층에서 구조적으로 불리하지 않음":"고층 사무소에서 코어는 구조적으로 불리하지 않습니다.","골프장은 홀, 골프연습장은 타석입니다":"골프장은 홀 수로, 골프연습장은 타석 수로 부설주차장 대수를 계산합니다.","공간 확장을 이유로 두지 않습니다":"엘리베이터를 건물 한쪽 끝에 두는 것은 공간 확장을 이유로 하지 않습니다.","공개공지 및 조경계획과 토지형질변경계획은 건축계획서 항목이 아니다":"건축계획서에 적는 항목에는 공개공지, 조경계획, 토지형질변경계획이 들어가지 않습니다.","공급수와 환수의 온도차를 크게 할 수 있어 열수송량이 큽니다":"공급수와 환수의 온도차가 클수록 같은 양의 물이 실어 나르는 열이 많아집니다.","공기단축을 위한 긴급공사도 가능하다":"언더피닝은 공기를 줄이려는 긴급공사에도 쓸 수 있습니다.","공동구·봉안시설·주차장은 공공시설입니다":"공동구, 봉안시설, 주차장은 행정청이 설치한 공공시설에 듭니다.","공동주택과 제2종 근린생활시설의 고시원 또는 다중생활시설을 함께 설치할 수 없습니다":"공동주택은 제2종 근린생활시설인 고시원이나 다중생활시설과 한 건축물에 함께 둘 수 없습니다.","공동주택·노유자시설·고등학교를 지을 수 있고 판매시설은 안 된다":"이 지역은 공동주택, 노유자시설, 고등학교는 지을 수 있어도 판매시설은 지을 수 없습니다.","공사비 절약, 순환펌프 설치, 중력순환은 역환수 방식의 목적이 아닙니다":"역환수는 순환 균형을 위한 배관법이라 공사비 절감이나 펌프 설치, 중력순환과는 목적이 다릅니다.","공연장 개별관람석은 바닥면적 100m2마다 출구 유효너비의 합계 0.6m가 필요합니다":"공연장 개별관람석은 100m2당 0.6m씩 출구 폭을 합산해 갖춰야 합니다.","공용부분을 한곳에 모아 사무소 유효면적을 늘리는 역할도 합니다":"코어에 공용부분을 몰아 두면 사무소의 유효면적이 늘어납니다.","공장 500㎡는 대상이 아닙니다":"공장은 500㎡라도 이 내화구조 대상 용도에 들지 않는다는 뜻입니다.","공장건축의 기본설계와 병행합니다":"플랜트 레이아웃은 공장건축의 기본설계와 병행합니다.","공장 생산·가공 뒤 현장에서 조립해 공기가 짧습니다":"조립식은 공장에서 만들고 가공한 뒤 현장에서 조립해 공기가 짧습니다.","공장생산과 대량생산이 가능하고 기계화 시공으로 단기완성이 가능합니다":"조립식은 공장생산과 대량생산이 가능하고 기계화 시공으로 짧은 기간에 끝낼 수 있습니다.","공조기·보일러·냉동기 용량을 줄이고 현열만 교환하는 것이 아니다":"전열교환기는 공조기, 보일러, 냉동기 용량을 줄여 주며 현열만 교환하는 것은 아닙니다.","공조장치의 용량을 정하려고 계산합니다":"최대부하는 공조장치 용량을 정하는 데 씁니다.","공중용과 개인용으로 나누어 산정할 수 있습니다":"부하단위는 공중용과 개인용으로 구분해 산정할 수도 있습니다.","공통가설비 또는 가설공사비로 잡습니다":"공사용수비와 공사용수설비는 공통가설비 또는 가설공사비로 잡습니다.","공항 호텔·부두 호텔·철도역 호텔이 터미널 호텔입니다":"터미널 호텔은 공항, 부두, 철도역 같은 교통 거점에 붙어 있는 호텔입니다.","과거에는 미관지구를 용도지구로 다뤘지만":"과거에는 미관지구를 용도지구의 하나로 다뤘다는 설명입니다.","관람석별 출구는 최소 2개소 이상 설치합니다":"관람석별 출구는 계산 결과와 관계없이 최소 2개소 이상 설치해야 합니다.","관람실 또는 집회실에서 바깥쪽으로 나가는 문은 안여닫이로 하면 안 됩니다":"관람실이나 집회실에서 바깥으로 나가는 문을 안쪽으로 열리는 안여닫이로 만들면 안 됩니다.","관람자가 전시실을 자유롭게 선택할 수 있고, 필요한 실만 독립적으로 폐쇄해도 됩니다":"관람자가 전시실을 자유롭게 고를 수 있고 필요한 실만 독립적으로 닫을 수 있습니다.","관람자 위 천장을 불투명하게 한다":"정측광 방식은 관람자 위쪽 천장을 불투명하게 합니다.","관람장과 옥외수영장은 정원으로 계산합니다":"관람장과 옥외수영장은 부설주차장 대수를 정원을 기준으로 계산합니다.","관로 내 유체의 유동이 급격히 변해 압력변화를 일으키는 수격작용":"수격작용은 관로 안 유체의 유동이 급격히 변해 압력변화를 일으키는 현상입니다.","관 안의 물을 가열하여 온수와 증기를 발생시킵니다":"연소열이 관 벽을 거쳐 관 안의 물을 데워서 온수나 증기가 만들어집니다.","관통구멍 지름은 35mm이다":"이형철근이 지나갈 관통구멍은 철근보다 넉넉하게 지름 35mm로 냅니다.","광역계획권의 공간 구조와 기능 분담, 녹지관리체계와 환경보전, 경관계획이 들어갑니다":"광역도시계획은 계획권의 공간 구조와 기능 분담, 녹지·환경, 경관을 다룹니다.","광역계획권의 장기발전방향과 투기과열지구 지정은 포함되지 않습니다":"광역계획권의 장기발전방향과 투기과열지구 지정은 도시·군관리계획 내용이 아닙니다.","광역계획권이나 광역시설은 광역도시계획의 내용입니다":"광역계획권이나 광역시설이 나오면 광역도시계획 쪽 내용으로 연결합니다.","광원에서 나온 광속을 모든 방향으로 골고루 확산시킵니다":"전반확산 조명은 광원이 낸 광속을 모든 방향으로 골고루 퍼뜨립니다.","광원이 물체 색의 보임을 정하는 성질이며 Ra가 100에 가까울수록 좋다":"연색성은 같은 물체가 광원 아래에서 얼마나 제 색으로 보이는지를 나타내며 Ra가 100에 가까울수록 좋습니다.","광원이 크고 시선에 가까울수록":"눈부심은 광원이 크고 시선에 가까울수록 심해집니다.","광장·공원·녹지·유원지·공공공지이며, 유수지는 제외합니다":"공간시설은 광장, 공원, 녹지, 유원지, 공공공지이고 유수지는 여기서 제외합니다.","교실 순수율은 높지만 시간표와 담당교사 수 맞추기가 용이한 방식은 아닙니다":"교과교실형은 교실 순수율은 높아도 시간표를 짜고 교사 수를 맞추기는 쉽지 않습니다.","교육연구시설이 가능합니다. 단독주택·종교시설·운동시설·수련시설도 됩니다. 숙박시설도 불가입니다":"준주거지역에는 교육연구시설, 단독주택, 종교시설, 운동시설, 수련시설이 가능하고 숙박시설은 불가입니다.","교육연구시설이라도 연구소는 설치 대상입니다":"교육연구시설 중 연구소는 배연설비 설치 대상에 든다는 예외입니다.","교차점에서 각 도로경계선을 따라 3m씩 후퇴한 두 점을 연결한 선이 건축선입니다":"교차점에서 각 도로경계선을 따라 3m 물러난 두 점을 이은 선이 모퉁이의 건축선입니다.","교체·수리와 관의 신축을 위한 것이므로 봉수파괴 방지와 구분합니다":"슬리브는 교체와 수리, 관의 신축을 위한 부속이라 봉수파괴 방지 수단과 구분합니다.","교통시설, 방재시설, 유통·공급시설, 공간시설, 환경기초시설, 공공·문화체육시설, 보건위생시설은 기반시설입니다":"기반시설은 교통, 방재, 유통·공급, 공간, 환경기초, 공공·문화체육, 보건위생시설로 나뉩니다.","교통시설과 연결해 구별합니다":"터미널 호텔은 교통시설과 연결해 구별합니다.","구성원 간 이해충돌이 없고 현장관리가 쉬운 방식이 아님":"공동도급은 구성원 사이 이해충돌이 없고 현장관리가 쉬운 방식이라고 할 수 없습니다.","구성은 냉·온수, 펌프, 수배관, 각 실 유닛입니다":"팬코일 유닛 방식은 냉온수를 만드는 열원, 펌프, 수배관, 각 방의 유닛으로 이루어집니다.","구조적으로 가장 바람직한 형식은 아닙니다":"코어를 따로 둔 독립코어형이 구조적으로 가장 바람직한 형식은 아닙니다.","구조체를 따뜻하게 하는 방식입니다":"복사난방은 바닥이나 벽 같은 구조체를 먼저 데우는 방식입니다.","구하려는 점이나 구간에서 보를 자르고, 왼쪽 또는 오른쪽 한쪽만 자유물체도로 봅니다":"보에서 구하고 싶은 위치를 자른 뒤 왼쪽과 오른쪽 중 하나만 골라 자유물체도로 그립니다.","국가계획과 관련해 필요하면 국토교통부장관이 수립하지만, 지정 후 2년간 승인 신청이 없다는 이유로 국토교통부장관이 수립하는 것은 아닙니다":"국토교통부장관이 수립하는 경우는 국가계획 관련 필요가 있을 때이며 승인 신청이 2년간 없다는 이유는 아닙니다.","군수가 수립할 때 도지사 승인을 생략할 수 없습니다":"군수가 광역도시계획을 수립할 때 도지사 승인 절차를 생략할 수 없습니다.","굳은 지반까지 박고 말뚝저항의 중심은 말뚝 끝에 있습니다":"지지말뚝은 단단한 지반까지 박아 말뚝 끝에서 저항이 생깁니다.","굵은골재 최소치수는 15mm 이상, 모르타르 믹서는 5분 이내 비빔, 수평에 가까운 상부 거푸집에는 통기공을 잡습니다":"프리팩트 콘크리트는 굵은골재 15mm 이상을 쓰고 모르타르 믹서로 5분 안에 비비며 수평에 가까운 거푸집 위쪽에 통기공을 냅니다.","균질한 단면이라는 조건이 나오면 같은 단면 성질을 사용해 최대 휨모멘트와 단면계수를 연결합니다":"재질이 고르다는 조건이 붙으면 단면 성질 하나로 최대 휨모멘트와 단면계수를 연결해 풉니다.","그 구간에는 등분포하중이 작용합니다":"전단력도가 기울어진 직선인 구간에는 등분포하중이 걸려 있습니다.","그 구간에는 하중이 작용하지 않고, 한 점에서 전단력이 뛰면 그 점의 집중하중을 확인합니다":"전단력도가 수평이면 하중이 없고 한 점에서 값이 뛰면 거기에 집중하중이 있습니다.","그다음 조임토크는 ‘토크계수×볼트지름×표준볼트장력’으로 계산합니다":"조임토크는 토크계수, 볼트지름, 표준볼트장력을 곱해 계산합니다.","그다음 채워진 조각은 더하고 빈 부분은 뺍니다":"속이 찬 조각은 값을 더하고 비어 있는 부분은 값을 뺍니다.","그다음 피난층의 거실인지로 나눕니다":"배연설비는 용도 다음으로 그 거실이 피난층에 있는지를 따져 가려냅니다.","그 단면의 최대 휨응력은 σmax = Mmax/Z로 계산하며, Z는 단면계수입니다":"최대 휨응력은 Mmax를 단면계수 Z로 나눈 σmax = Mmax/Z입니다.","그래서 일시적인 난방에는 바람직하지 않습니다":"구조체부터 데우므로 잠깐 쓰는 난방에는 알맞지 않습니다.","그래서 전시 벽면 쪽을 밝게 한다":"이렇게 하면 전시 벽면 쪽이 밝아집니다.","그래서 중앙기계실 면적이 작아도 되고, 기존 건물 설치와 유닛 증설이 쉽습니다":"덕트와 대형 공조기가 줄어 기계실이 작고 기존 건물에 설치하거나 유닛을 더하기 쉽습니다.","그려진 위치(위·아래)보다 형상으로 먼저 판별합니다":"휨모멘트도는 그려진 위치(위·아래)보다 모양을 먼저 보고 가립니다.","그룹별로 배치하고 군 관리 운전을 적용합니다":"엘리베이터는 군으로 묶어 배치하고 군 관리 운전을 적용합니다.","그림에서 제품 흐름을 따라 공정이 이어지면 제품중심입니다":"그림에서 제품이 흐르는 방향으로 공정이 줄지어 있으면 제품중심 레이아웃입니다.","그림 전체의 차수를 먼저 구합니다":"부정정 차수는 그림 전체의 차수를 먼저 구합니다.","그 방향이 더 가늘게 거동하므로 그 방향의 좌굴을 먼저 봅니다":"반경이 작은 축 쪽이 더 가늘게 움직이므로 그쪽 방향 좌굴을 먼저 따집니다.","그 부분의 각 층 바닥면적 합계가 400㎡인 경우도 설치하지 않을 수 있습니다":"해당 부분의 층마다 바닥면적을 합쳐 400㎡이면 설치 의무에서 빠질 수 있습니다.","그 장소에서 배제되지 않습니다":"애자 사용 공사와 케이블 공사도 그 장소에서 배제되지 않습니다.","그 장소에서 사용할 수 있습니다":"합성수지관 공사는 그 은폐장소에서 쓸 수 있습니다.","그 전단력과 평형을 이루는 P를 찾습니다":"그 전단력과 평형을 이루는 힘이 P입니다.","그 조각의 수직력 평형으로 전단력 V를, 절단점에 대한 모멘트 평형으로 휨모멘트 M을 구합니다":"그 조각에서 수직력 평형은 전단력 V를, 절단점 모멘트 평형은 휨모멘트 M을 줍니다.","극수가 다른 고정자 권선을 두어 극수를 바꾼다":"극수 변환은 극수가 다른 고정자 권선을 두어 극수를 바꾸는 방법입니다.","근린지역에서 일용품과 서비스를 공급하면":"일용품과 서비스를 근린지역에 공급하는 것이 목적인 상업지역은 근린상업지역입니다.","금속관은 은폐장소와 노출장소에 모두 쓸 수 있고, 옥측과 옥외까지 사용 범위가 넓습니다":"은폐장소든 노출장소든 옥측이나 옥외든 금속관을 쓸 수 있어 사용 범위가 넓습니다.","급기온도를 일정하게 두고 실내부하에 따라 송풍량을 바꿉니다":"급기온도는 그대로 두고 방의 부하에 따라 보내는 공기량만 늘리거나 줄이는 방식입니다.","급속 건조를 피하고 한 번 또는 두 번의 바름 두께를 가급적 얇게 하며 쇠흙손질을 충분히 하는 쪽입니다":"미장 균열은 급속 건조를 피하고 바름 두께를 얇게 하며 쇠흙손질을 충분히 해 막습니다.","급수압력이 일정하고 대규모 급수 수요에 대응하기 쉽습니다":"고가수조방식은 압력이 일정하고 대규모 급수 수요에도 쉽게 맞춥니다.","급수전은 1개소 이상, 조명은 예비전원 방식입니다":"피난안전구역에는 급수전을 한 곳 이상 두고 조명은 예비전원으로 켜지게 합니다.","급탕부하는 물의 양에 비열과 온도차를 곱합니다":"급탕부하는 물의 양, 비열, 온도차를 곱해 얻습니다.","기계실처럼 거실이 아닌 층은 빼십시오":"기계실처럼 거실이 아닌 층은 계산할 면적에서 뺍니다.","기구급수 부하단위, 국부저항 상당길이, 허용 마찰손실수두입니다":"관경을 정하는 데는 기구급수 부하단위, 국부저항 상당길이, 허용 마찰손실수두가 직접 관계합니다.","기구급수 부하단위는 표준 토수량뿐 아니라 사용빈도와 사용시간까지 고려해 급수장치의 부하를 단위화한 것입니다":"기구급수 부하단위는 표준 토수량에 사용빈도와 사용시간을 더해 급수장치 부하를 단위로 환산한 값입니다.","기구 수를 전부 동시에 쓰는 것으로 보지 않고, 제시된 동시사용률을 적용해 주배관을 판단합니다":"기구를 전부 동시에 쓴다고 가정하지 않고 주어진 동시사용률을 곱해 주배관 관경을 판단합니다.","기기 배치와 유지보수에 충분한 공간을 두고 장래 배선 여유를 고려한다":"전기샤프트는 기기를 놓고 점검할 공간을 넉넉히 잡고 앞으로 늘 배선 몫도 남겨 둡니다.","기능이 동일하거나 유사한 공정과 기계를 모아 배치한다는 설명은 고정식이 아닙니다":"비슷한 기능의 공정과 기계를 한곳에 모으는 배치는 고정식이 아니라 공정중심입니다.","기둥보다 보의 파괴를 먼저 유도합니다":"내진 설계는 기둥보다 보가 먼저 파괴되도록 유도합니다.","기둥 상부 철근이 여러 겹으로 겹치고 두꺼운 바닥판 때문에 자중이 증대되는 것은 플랫슬래브의 특징이 아닙니다":"기둥 상부에서 철근이 겹겹이 몰리거나 바닥판이 두꺼워 자중이 느는 것은 플랫슬래브의 특징으로 보지 않습니다.","기둥·샛기둥의 내외면에 메탈라스 또는 철망을 치고 모르타르로 마감해 부재가 외부에 보이지 않는 구조는 심벽목구조가 아닙니다":"기둥과 샛기둥 안팎에 메탈라스를 대고 모르타르로 마감해 부재가 보이지 않는 구조를 심벽목구조로 부르는 것은 틀립니다.","기둥 위와 기둥 사이에 모두 있으면 다포입니다":"공포를 기둥 위에도 올리고 기둥 사이에도 올린 건물을 다포식이라 부릅니다.","기둥·지붕틀·바닥이고 옥외계단은 아니다":"주요구조부는 기둥, 지붕틀, 바닥 등이며 옥외계단은 주요구조부가 아닙니다.","기름저장소는 보일러실 외의 다른 곳에 설치합니다":"기름저장소는 보일러실과 분리해 다른 곳에 두어야 합니다.","기반시설의 배치와 규모, 교통처리계획":"지구단위계획에는 기반시설의 배치와 규모, 교통처리계획이 들어갑니다.","기본 1대에 초과 2,000㎡마다 1대를 더합니다":"숙박·업무시설은 기본 1대에 초과 2,000㎡마다 한 대씩 더합니다.","기본 1대에 초과 3,000㎡마다 1대를 더합니다":"공동주택은 기본 1대에 초과 3,000㎡마다 한 대씩 더하는 방식입니다.","기본 2대에 초과 2,000㎡마다 1대를 더합니다":"의료·판매시설은 기본 2대에 기준 초과분 2,000㎡마다 한 대씩 더합니다.","기본정착길이에 보정계수를 곱해 구한다":"인장 정착길이는 기본정착길이에 보정계수를 곱해 구합니다.","기본 허용전단력을 그대로 쓰지 않습니다":"인장력이 함께 작용하면 기본 허용전단력을 그대로 쓰지 않습니다.","기숙사·의료시설·숙박시설 바닥면적 합계 2,000m2":"바닥면적 합계 2,000m2인 기숙사, 의료시설, 숙박시설은 설비기술사와 협력하는 대상입니다.","기온·기류·주벽면온도 조합과 체감의 관계를 나타낸다":"작용온도는 기온, 기류, 주벽면온도를 합친 조건과 체감의 관계를 나타냅니다.","기존 건물의 기초 혹은 지정을 보강하는 공법이다":"언더피닝은 기존 건물의 기초나 지정을 보강하는 공법입니다.","기존 건축물의 연면적을 포함해 200제곱미터를 초과하는 신축·증축입니다":"기반시설설치비용은 기존 건축물 연면적을 합쳐 200제곱미터를 넘는 신축·증축에 부과합니다.","기준에 포함되고, 3,000㎡와 4,000㎡는 부족합니다":"경계가 되는 면적은 기준에 포함되고 3,000㎡와 4,000㎡는 그보다 작아 모자랍니다.","기준층 바닥면적이 큰 고층·초고층 사무소에 적합하고, 구조코어로서 가장 바람직합니다":"기준층이 넓은 고층·초고층 사무소에 중심코어가 맞고 구조코어로도 가장 바람직합니다.","기후조건에 따라 기계적 환경조절이 필요합니다":"집중형은 기후에 따라 기계 설비로 실내 환경을 조절해야 합니다.","길이 5.05m, 너비 1.85m, 높이 1.55m 이하":"중형 기계식주차장에 넣을 수 있는 자동차는 길이 5.05m, 너비 1.85m, 높이 1.55m 이하입니다.","길이가 2배인 A보와 짧은 B보의 처짐을 같게 하려면 w₂=16w₁이 됩니다":"길이가 2배인 A보와 짧은 B보의 처짐이 같으려면 하중이 w₂=16w₁의 관계여야 합니다.","길이는 최소 300mm 이상이다":"압축 이형철근 겹침이음 길이는 300mm 이상이어야 합니다.","길이만 가능하고 깊이는 불가능한 것이 아닙니다":"개방식이 길이만 바꿀 수 있고 깊이는 못 바꾼다는 말은 틀립니다.","나누어떨어지지 않으면 부족하지 않도록 올림하고":"나눗셈에서 나머지가 생기면 모자라지 않도록 출구 수를 올려 잡습니다.","나머지가 있으면 최소 대수를 올리세요. 서로 다른 부대시설은 각각 계산한 뒤 더합니다":"나머지가 있으면 최소 대수를 올려 잡고 서로 다른 부대시설은 따로 계산해 더합니다.","나머지는 올리고 복합시설은 따로 계산해 더하세요. 면적을 기준면적으로 나눕니다":"면적을 기준면적으로 나누어 나머지는 올림하고 복합시설은 따로 계산해 합칩니다.","나머지 주요 시설은 시설면적으로 묶으세요":"정원이나 홀·타석이 아닌 나머지 주요 시설은 시설면적을 기준으로 묶어 계산합니다.","나비의 합계는 벽길이의 1/2 이하, 위아래 문꼴의 수직거리는 60cm 이상이며, 나비 1.8m가 넘는 문꼴 위에는 철근콘크리트 인방보를 둡니다":"문꼴은 폭 합계를 벽길이의 절반 이하로, 위아래 문꼴 간격을 60cm 이상으로 하고 1.8m 넘는 문꼴 위에는 철근콘크리트 인방보를 얹습니다.","나오면 분자에 넣으세요. 소요 수량은 평균조도×면적×감광보상률÷(1개 광속×조명률)입니다":"감광보상률이 문제에 나오면 분자에 곱해 소요 수량 식을 완성합니다.","낙관적 시간 a, 개연적 시간 m, 비관적 시간 b":"PERT 예상시간은 낙관적 시간 a, 개연적 시간 m, 비관적 시간 b로 계산합니다.","난방구획마다 내화구조의 벽·바닥과 갑종방화문으로 된 출입문으로 방화구획합니다":"오피스텔 난방구획은 내화 벽·바닥과 갑종방화문으로 나누어 불이 번지지 않게 막습니다.","난방부하 변동에 따른 온도조절이 비교적 쉽고 쾌감도도 높습니다":"온수는 부하가 변할 때 공급 온도를 바꿔 조절하기 쉬워서 실내 쾌감도도 높다는 내용입니다.","난방으로 유리 표면온도를 높인다":"난방을 하여 유리 표면온도를 높이는 것도 결로를 막는 방법입니다.","난방을 정지해도 효과가 어느 정도 지속된다":"온수난방은 난방을 멈춰도 온기가 어느 정도 이어집니다.","난방의 틈새바람 부하는 보통 현열만 산정하고, 상당 외기온도도 난방부하 계산 항목이 아닙니다":"난방의 틈새바람 부하는 습기를 따지지 않고 현열만 계산하는 것이 보통이며 상당 외기온도는 항목이 아닙니다.","남는 면적도 한 구간으로 올려 세십시오":"초과분을 나눌 때 남는 면적이 있어도 한 구간으로 보아 한 대를 더합니다.","낮으므로 천장과 벽면은 밝고 빛이 잘 확산되어야 하며 실내면 반사율도 커야 합니다":"간접조명은 조명률이 낮아 천장과 벽면이 밝고 빛이 잘 퍼져야 하며 실내면 반사율도 커야 합니다.","낮을수록 공기량이 감소하는 것은 아닙니다":"콘크리트 온도가 낮다고 공기량이 줄어드는 것은 아닙니다.","내 기구의 배수가 만수·연속류로 흘러 봉수를 끌고 가면 자기사이폰입니다":"기구 안 배수가 가득 찬 채 연속해 흘러 봉수를 끌고 나가면 자기사이폰입니다.","내부마감이 불연재료이고 연결 계단은 특별피난계단 구조이며, 높이 최소 2.7m는 기준이 아닙니다":"피난안전구역은 불연재료 마감과 특별피난계단 구조가 필요하고 2.7m 높이는 규정값이 아닙니다.","내부스팬의 정적모멘트 Mo를 받침부 부모멘트와 중앙부 정모멘트로 나눕니다":"내부스팬의 정적모멘트 Mo를 둘로 나눠 받침부와 중앙부에 각각 부모멘트, 정모멘트로 줍니다.","내부에 보가 없습니다. 층높이를 낮추고 실내 이용률을 높일 수 있습니다":"플랫슬래브는 보가 없어서 층높이를 낮추고 실내를 더 넓게 쓸 수 있습니다.","내부와 접하는 창문 등은 망이 들어 있는 유리의 붙박이창으로 하고 각각 1m² 이하로 합니다":"계단실 안쪽 창은 망입유리 붙박이창으로 하고 하나당 1m² 이하로 제한합니다.","내부 피난계단 자체의 유효너비 0.9m 이상은 기준이 아닙니다":"내부 피난계단 자체의 유효너비 0.9m 이상은 기준으로 정해져 있지 않습니다.","내부힌지에서 구조물을 나누고, 한쪽 조각부터 평형을 맞춥니다":"겔버보는 내부힌지에서 구조물을 둘로 나누어 한쪽 조각부터 평형을 맞춰 풉니다.","내용을 보려면 관원에게 요구하고 대출 기록을 남긴 뒤 열람합니다":"반개가식에서 내용을 읽으려면 관원에게 청해 대출 기록을 남겨야 합니다.","내진건축구조용 냉간성형 각형강관이 아니다":"SN을 내진건축구조용 냉간성형 각형강관이라 하면 틀립니다.","내화, 내구성과 철근의 부착력 확보를 위해 정합니다":"피복두께는 내화성과 내구성, 철근 부착력을 지키려고 규정합니다.","내화구조로 피난층 또는 지상까지 직접 연결하고, 계단실과 부속실의 실내 접촉 부분은 불연재료로 마감합니다":"특별피난계단은 내화구조로 지상까지 직접 연결하고 계단실과 부속실의 안쪽 마감은 불연재료입니다.","내화구조로 하고 피난층 또는 지상까지 직접 연결합니다":"계단은 내화구조로 하고 피난층이나 지상까지 끊기지 않게 직접 이어야 합니다.","내화구조이며 홀로 설 수 있어야 합니다":"방화벽은 내화구조여야 하고 다른 구조에 기대지 않고 홀로 서야 합니다.","냉각탑은 냉동기의 냉각수를 재활용하기 위한 장치이다":"냉각탑은 냉동기에서 데워진 냉각수를 식혀서 다시 쓰게 해 줍니다.","냉각한다고 절대습도가 높아지는 것은 아닙니다":"공기를 식힌다고 절대습도가 올라가지는 않습니다.","냉동기 용량과 피크 전력을 줄이나":"빙축열은 냉동기 용량과 피크 전력을 줄입니다.","냉매를 응축시킨 냉각수를 다시 냉각해 재사용한다":"냉각탑은 냉매를 응축시킨 냉각수를 다시 식혀 재사용하게 하는 장치입니다.","냉수코일을 통과한 공기는 건구온도가 낮아지고 상대습도는 높아집니다":"냉수코일을 지난 공기는 건구온도가 내려가고 상대습도는 올라갑니다.","냉풍과 온풍을 섞지 않아 혼합손실이 없습니다":"한 덕트로 냉풍이나 온풍 하나만 보내므로 서로 섞여 에너지가 낭비되는 혼합손실이 없습니다.","냉풍과 온풍의 두 계통을 두고 혼합상자에서 섞습니다":"이중덕트는 냉풍관과 온풍관을 따로 두고 혼합상자에서 필요한 만큼 섞어 보냅니다.","너비 2.3m 이상, 길이 5.0m 이상이다":"직각주차 일반형 단위구획은 너비 2.3m 이상, 길이 5.0m 이상입니다.","너비 3.3m, 길이 5.0m 이상이다":"장애인 전용 주차구획은 너비 3.3m, 길이 5.0m 이상입니다.","너비 6m인 두 도로가 90°로 교차하는 모퉁이는 교차점을 그대로 건축선으로 쓰지 않습니다":"너비 6m 도로 둘이 90°로 만나는 모퉁이는 교차점이 아니라 후퇴한 선을 건축선으로 삼습니다.","너비 8.1m 이상, 길이 9.5m 이상":"중형 기계식주차장 전면공지는 너비 8.1m 이상, 길이 9.5m 이상입니다.","너비는 3.5m 이상이고, 건축물식 조명 기준도 있습니다":"노외주차장 출입구 너비는 3.5m 이상이며 건축물식에는 조명 기준도 따로 있습니다.","넓어 급수용량 제어가 쉽지만 예열시간은 길고 분할 반입은 어렵습니다":"보유수면이 넓은 노통연관보일러는 급수량 변동에 여유가 있지만 데우는 데 오래 걸리고 쪼개 들이기 어렵습니다.","넓은 면적을 균등하게 도장할 수 있다":"뿜칠은 넓은 면적을 균등하게 도장하기에 적합합니다.","넓은 면적이 광원 역할을 하므로 직사 눈부심이 없고, 조도가 균일하며 음영이 유연합니다":"간접조명은 넓은 면이 광원 구실을 해 직사 눈부심이 없고 조도가 고르며 그림자가 부드럽습니다.","네 면에 지붕면이 있고, 앞뒤는 사다리꼴이며 양측은 삼각형입니다":"우진각지붕은 앞뒤가 사다리꼴이고 양옆이 삼각형인 지붕면 네 개로 이루어집니다.","네 조합 중 밑면전단력이 가장 작은 것은 ‘중량이 작고 주기가 긴 구조물’입니다":"조합을 비교하면 구조물이 가볍고 주기가 길 때 밑면전단력이 가장 작아집니다.","노상주차장을 설치하지 않는다":"좁은 도로에서는 차 때문에 통행이 막히므로 노상주차장을 설치하지 않습니다.","노출용 개량아스팔트 시트를 최상층에 쓰고 전면 밀착하는 공법 기호입니다":"M-MiF는 노출용 개량아스팔트 시트를 맨 위층에 쓰고 전면을 밀착하는 공법을 나타내는 기호입니다.","노통연관도 수관처럼 부하변동 적응이 좋습니다":"노통연관보일러를 수관보일러와 견주어 부하변동에 똑같이 잘 맞는다고 말하는 문장입니다.","높은 곳에 탱크를 설치하지 않아도 되며, 단수 때는 저수조의 물로 일정량 급수할 수 있습니다":"압력수조방식은 높은 곳에 탱크가 없어도 되고 단수 때는 저수조의 물로 일정량 급수합니다.","높이 30퍼센트, 가구면적 20퍼센트, 건축선 2m는 이 기준이 아닙니다":"높이 30퍼센트, 가구면적 20퍼센트, 건축선 2m 변경은 이 변경 기준에 속하지 않습니다.","높이 31m를 넘는 각 층을 거실 외의 용도로 쓰면 설치하지 않을 수 있습니다":"높이 31m를 넘는 각 층을 거실 외의 용도로 쓰면 비상용승강기를 두지 않아도 됩니다.","높이 31m를 초과하는 건축물":"비상용승강기는 높이 31m를 초과하는 건축물이 설치 대상입니다.","높이 3m마다 너비 1.2m 이상 계단참을 둔다":"연면적이 큰 건물은 계단이 높으면 일정 높이마다 폭 넓은 계단참을 중간에 둡니다.","높이 4m마다 한 층으로 산정한다":"층 구분이 분명하지 않은 건축물은 높이 4m마다 한 층으로 산정합니다.","높이가 세제곱이므로 같은 면적이라도 축에서 멀리 퍼진 단면의 I가 큽니다":"높이가 세제곱으로 들어가 면적이 같을 때 축에서 멀리 퍼진 단면일수록 I가 커집니다.","높이 차를 구간 길이로 나누어 기울기를 읽습니다":"직선 구간은 높이 차를 구간 길이로 나눠 기울기를 읽습니다.","다량의 외기송풍은 쉽지 않고 겨울철 외기냉방에도 유리하지 않습니다":"외기를 많이 불어 넣기 어렵고 겨울에 찬 외기로 식히는 외기냉방도 효과가 크지 않습니다.","다만 가장 높은 기구까지 보내려면 수도 본관의 압력이 충분해야 합니다":"가장 높은 기구까지 물을 올리려면 수도 본관 압력이 충분히 높아야 합니다.","다만 유닛을 창문 밑에 설치하면 콜드 드래프트를 줄일 수 있습니다":"콜드 드래프트는 찬 창문 부근 공기가 내려와 느끼는 냉기류이며 유닛을 창 밑에 두면 약해집니다.","다만 이용자 혼란 우려가 없지는 않습니다":"죠닝에는 이용자가 혼란스러워할 우려도 있습니다.","다만 철근 콘크리트 건물에서 기존 금속관 배선으로부터 증설할 때 이용됩니다":"금속 몰드는 철근 콘크리트 건물에서 기존 금속관 배선에서 증설할 때 이용합니다.","다포를 주로 하고 주심포의 세부수법을 섞은 형식입니다":"주심포의 세부 수법을 일부 가져와 다포 위주로 지은 형식이 절충식입니다.","단너비는 좁은 쪽 끝에서 30cm 위치에서 잼":"돌음계단 단너비는 좁은 쪽 끝에서 30cm 되는 위치를 재서 정합니다.","단독주택·노유자시설·제1종 근린생활시설·고등학교는 가능합니다":"제1종 일반주거지역에는 단독주택, 노유자시설, 제1종 근린생활시설, 고등학교를 지을 수 있습니다.","단독주택·숙박 객실·학교 교실":"단독주택, 숙박 객실, 학교 교실은 거실 채광을 확보해야 하는 대상입니다.","단독주택 중심의 양호한 주거환경을 보호하면 제1종전용주거지역입니다":"제1종전용주거지역은 단독주택 중심으로 좋은 주거환경을 보호하려고 정한 지역입니다.","단면2차반경과 단면극2차모멘트는 서로 다른 양입니다":"단면2차반경과 단면극2차모멘트를 같은 양으로 섞어 쓰면 안 됩니다.","단면적비가 큰 트랩도 효과가 있습니다":"단면적비가 큰 트랩도 자기사이폰을 막는 효과가 있습니다.","단수 시에도 저장된 일정량을 공급할 수 있지만, 저수시간이 길어지면 수질이 나빠지기 쉽습니다":"고가수조방식은 단수되어도 저장해 둔 물을 일정량 공급하지만 오래 저장하면 수질이 나빠지기 쉽습니다.","단수 없이 청소하도록 2개 이상으로 분할하거나 내부칸막이를 둔다":"저수조 물탱크는 단수 없이 청소할 수 있도록 2개 이상으로 나누거나 내부에 칸막이를 둡니다.","단순보에서는 지점의 휨모멘트를 출발값으로 잡고 전단력도 면적을 차례로 누적합니다":"단순보는 지점 모멘트를 출발점으로 두고 전단력도 넓이를 차례로 합해 내려갑니다.","단순하고 공간을 절약하며 전시 벽면을 최대화할 수 있어 소규모 전시와 적은 대지에 유리합니다":"연속순로는 구성이 단순하고 공간을 아끼며 전시 벽면을 최대로 확보해 소규모 전시에 유리합니다.","단위시멘트량 최소 300kg/m3, 동결융해 시 AE콘크리트를 잡습니다":"프리캐스트 콘크리트는 단위시멘트량 최소 300kg/m3이고 동결융해 환경이면 AE콘크리트를 잡습니다.","단일덕트와 이중덕트는 모두 공기로 열을 운반하는 전공기방식입니다":"단일덕트와 이중덕트는 공기가 열을 나르므로 전공기방식으로 분류합니다.","단일덕트 정풍량방식보다 설비비가 적게 들지 않습니다":"변풍량 장치가 더해져 정풍량 단일덕트보다 설비비가 덜 들지는 않습니다.","단일 래티스 기울기 60° 이상":"래티스 조립압축재에서 단일 래티스는 기울기가 60° 이상이어야 합니다.","단일용도의 대규모 전용사무실에 적합합니다":"양측코어형은 한 가지 용도의 큰 전용사무실에 알맞습니다.","단지 내 교통량을 줄이려면 진입구 주변에 배치합니다":"고밀도지역은 단지 내 교통량을 줄이려고 진입구 주변에 둡니다.","단지 내부 교통은 처리하되 통과교통에는 쓰이지 않게 계획합니다":"근린주구 내부 가로망은 단지 교통은 처리하되 통과교통에는 쓰이지 않게 계획합니다.","단효용보다 에너지 절약적입니다":"이중효용은 단효용보다 같은 냉방에 쓰는 에너지가 적습니다.","대규모 단지에 주로 쓰는 형식이 아님":"쿨데삭형은 대규모 단지에 주로 쓰는 형식이 아닙니다.","대규모 사무실에서 아웃트렛 등의 취출에도 편리하고, 내부에는 절연전선을 사용합니다":"플로어 덕트는 대규모 사무실에서 아웃트렛 등을 뽑기에 편리하고 안에는 절연전선을 씁니다.","대규모 설비에 적합하고 비교적 안정된 급탕이 가능합니다":"간접가열식은 큰 설비에 맞고 급탕이 비교적 안정됩니다.","대기 중 내식성이 보통강보다 2~6배 크다":"내후성강은 대기 중 내식성이 보통강보다 2~6배 큽니다.","대량생산에 유리하고 생산성이 높습니다":"제품중심 레이아웃은 대량생산에 유리하고 생산성이 높습니다.","대류난방보다 설비비가 비싸며":"코일을 바닥 등에 묻는 공사가 필요해서 대류난방보다 설비비가 많이 듭니다.","대부분 연등천장이며, 맞배지붕이 많고 별도 천장 없이 서까래가 드러납니다":"주심포 건물은 천장을 따로 만들지 않고 서까래를 드러내는 연등천장에 맞배지붕이 흔합니다.","대신 공용복도 쪽 프라이버시는 침해되기 쉽습니다":"편복도형은 공용복도 쪽 프라이버시가 침해되기 쉽습니다.","대용량 배전에 적합하며 간선용과 공장용으로 쓸 수 있습니다":"버스 덕트는 큰 용량의 배전에 알맞아 간선용과 공장용으로 씁니다.","대용량에서 압축효율이 좋고 비례제어가 가능하며, 중·대형 규모의 중앙식 공조 냉방에 사용됩니다":"터보식은 용량이 클수록 효율이 좋고 연속적 용량 조절이 가능해 중대형 중앙식 냉방에 맞습니다.","대지가 너비 12m 미만 도로에 접하면":"대지가 접한 도로 너비가 12m 미만인 경우의 높이 제한 조건입니다.","대지가 둘 이상의 도로에 접할 때 가장 좁은 도로를 기준으로 높이를 제한하는 것이 아닙니다":"도로가 둘 이상일 때 좁은 도로만 골라 높이를 제한하는 방식은 아닙니다.","대지와 도로와의 관계, 건축물의 안전 및 방재는 포함되지 않습니다":"대지와 도로의 관계, 건축물의 안전 및 방재는 지구단위계획 내용이 아닙니다.","대지 이용도는 좋지만 프라이버시는 양호하지 않습니다":"중복도형은 땅 이용은 좋지만 프라이버시를 지키기 어렵습니다.","대지 이용률만 높고 채광·통풍은 불리합니다. 복도 부분은 자연환기와 채광이 극히 나쁩니다":"집중형은 대지 이용률은 높지만 채광·통풍이 불리하고 복도는 자연환기와 채광이 극히 나쁩니다.","대지 이용률이 높지만 채광·통풍과 프라이버시가 불리하며, 도심 독신자용에 쓰입니다":"중복도형은 땅을 알뜰히 쓰지만 채광, 통풍, 프라이버시가 나빠 도심 독신자용으로 쓰입니다.","대지조성사업지구·관광특구·택지개발예정지구":"지구단위계획구역은 대지조성사업지구, 관광특구, 택지개발예정지구 등에 지정합니다.","대지 주변부 보행자전용로와 연결":"단지 보행자전용로는 대지 주변부의 보행자전용로와 이어지게 합니다.","대출 절차가 복잡해 관원의 작업량이 많습니다":"폐가식은 빌리는 절차가 번거로워 관원이 맡는 일이 많아집니다.","대표군은 강릉 객사문, 봉정사 극락전, 부석사 무량수전, 수덕사 대웅전, 무위사 극락전입니다":"대표적인 주심포 건물로는 강릉 객사문부터 무위사 극락전까지 다섯 곳을 꼽습니다.","대형 가구 등 소리를 반향시키는 기재는 사용하기 어렵습니다":"소리를 되울리는 대형 가구 같은 기재는 열린 사무 공간에서 쓰기 어렵습니다.","대형장비가 필요하고 초기 투자비가 높지만, 대형화되어 이음부위가 줄어듭니다":"갱폼은 대형장비와 큰 초기 투자비가 필요하지만 덩어리가 커서 이음부위는 줄어듭니다.","덕트가 하나이므로 이중덕트보다 덕트 스페이스를 적게 차지합니다":"단일덕트는 덕트가 한 줄이라 둘이 필요한 이중덕트보다 덕트 공간이 작게 듭니다.","덕트 방식보다 유닛 위치 변경도 용이합니다":"물배관과 유닛만 옮기면 되어 덕트 방식보다 유닛 위치를 바꾸기 편합니다.","덕트 샤프트나 덕트 스페이스는 필요 없거나 작아도 됩니다":"공기가 아니라 물로 열을 보내므로 큰 덕트 통로가 필요 없거나 작아도 됩니다.","덕트 스페이스가 필요 없고 각 실 제어가 쉽다":"전수방식은 공기가 아니라 물이 열을 나르므로 덕트 스페이스가 필요 없고 방마다 제어하기 쉽습니다.","도로 너비가 부족한 경우가 아니면 기본 건축선은 이 경계선입니다":"도로 너비가 모자란 경우가 아니라면 건축선은 대지와 도로의 경계선 그대로입니다.","도로면에서 높이 4.5m 이하인 출입구·창문과 이와 유사한 구조물도 열고 닫을 때 그 수직면을 넘게 만들 수 없습니다":"도로면에서 높이 4.5m 이하의 출입구나 창문도 열고 닫을 때 건축선 수직면을 넘으면 안 됩니다.","도로와 접한 부분에서 건축할 수 있는 기본선은 대지와 도로의 경계선입니다":"건축선의 기본은 대지와 도로가 맞닿는 경계선이며 그 선이 건축 가능한 한계입니다.","도로 중심선에서 소요너비의 2분의 1에 상당하는 수평거리로 후퇴한 선을 잡습니다":"좁은 도로에서는 도로 중심선에서 소요너비의 2분의 1만큼 수평으로 물러난 선이 건축선입니다.","도막 두께를 위해 겹치지 않게 칠하는 것은 아니다":"뿜칠은 도막 두께를 위해 겹치지 않게 칠하는 방법이 아닙니다.","도매시장·소매시장·상점은 판매시설입니다":"도매시장, 소매시장, 상점은 용도 분류상 판매시설에 듭니다.","도서열람의 체크시설이 필요합니다":"안전개가식은 대출 전에 책을 점검하는 체크시설을 따로 둬야 합니다.","도서 유지 관리가 좋고 책의 망실이 적습니다":"폐가식은 책을 잘 관리할 수 있고 잃어버리는 책이 적은 점이 좋습니다.","도시개발사업이나 정비사업, 기반시설의 설치·정비 또는 개량도 포함됩니다":"도시개발사업, 정비사업, 기반시설의 설치·정비·개량도 도시·군관리계획에 속합니다.","도시 내 및 지역 간 유통기능을 증진하면":"도시 안과 지역 사이의 유통기능을 높이는 상업지역은 유통상업지역입니다.","도시재건축사업구역·계획관리지역":"도시재건축사업구역과 계획관리지역은 지구단위계획구역 지정 목록에 들지 않습니다.","도시지역에서 복합적인 토지이용을 증진시켜 도시 정비를 촉진하고 지역 거점을 육성하는 구역입니다":"입지규제최소구역은 도시지역에서 복합적 토지이용을 늘려 정비를 촉진하고 거점을 키우는 구역입니다.","도시지역의 무질서한 시가화를 막기 위해":"시가화조정구역은 도시지역이 질서 없이 시가지로 퍼지는 것을 막으려고 지정합니다.","도심 x축에 대해 Ix=bh³/12, 도심 y축에 대해 Iy=hb³/12입니다":"가로 b, 높이 h인 장방형은 x축 방향 값이 bh³/12이고 y축 방향 값은 hb³/12입니다.","도심·부도심의 상업기능과 업무기능을 확충하면":"도심과 부도심의 상업기능과 업무기능을 넓히는 상업지역은 중심상업지역입니다.","도심을 지나는 서로 직교하는 두 축의 단면2차모멘트 합은 축 방향을 돌려도 같습니다":"도심을 지나 직각으로 만나는 두 축은 축 방향을 돌려도 두 단면2차모멘트의 합이 변하지 않습니다.","도심을 지나는 축에 대한 단면1차모멘트는 0이고, 단면2차모멘트의 단위는 cm⁴, m⁴입니다":"단면1차모멘트는 도심을 지나는 축에서 0이 되고 단면2차모멘트는 길이의 네제곱 단위(cm⁴, m⁴)로 나타냅니다.","도장 후 기름·산·수지·알칼리 등의 유해물이 배어 나오거나 녹아 나오면 재시공합니다":"도장한 뒤 기름, 산, 수지, 알칼리 같은 유해물이 배어 나오거나 녹아 나오면 다시 시공합니다.","독립 단층으로 주위 건물에서 1.5m 이상 떨어뜨리고, 건물 일부를 쓰면 내화구조 또는 방화구조로 구획하며, 바닥에는 침투성이 없는 재료를 깝니다":"가연성 도료 창고는 독립된 단층으로 지어 주위 건물에서 1.5m 이상 띄우고 바닥에 스며들지 않는 재료를 깝니다.","독립성과 쾌적감 확보에 유리한 쪽입니다":"독립성과 쾌적감을 지키기 쉬운 쪽은 방이 나뉜 개실 시스템입니다.","돌침은 건축물 최상부에서 25cm 이상 돌출하고 접지극은 인하도선마다 1개 이상 접속한다":"돌침은 맨 꼭대기보다 25cm 이상 높게 솟게 하고 접지극은 인하도선 하나당 1개 이상 연결합니다.","동물 및 식물관련시설이 아닙니다":"식물원은 이름과 달리 동물 및 식물관련시설로 분류되지 않는다는 구분입니다.","동일 건물에서는 지지말뚝과 마찰말뚝 또는 서로 다른 종류의 말뚝을 혼용하지 않습니다":"한 건물에는 지지말뚝과 마찰말뚝, 혹은 종류가 다른 말뚝을 섞어 박지 않습니다.","동일 군 관리의 대면거리는 3.5~4.5m입니다":"군 관리 엘리베이터가 마주 보는 거리는 3.5~4.5m로 합니다.","동일 방열량에서 온수난방은 증기난방보다 관지름이 작지 않습니다":"온수는 열 운반량이 적어 같은 열을 보내려면 증기보다 굵은 관이 필요합니다.","동일한 주기·중량·중요도계수 조건에서 가장 작은 지진하중은 철골 편심가새골조입니다":"주기, 중량, 중요도계수가 같을 때 가장 작은 지진하중이 걸리는 구조는 철골 편심가새골조입니다.","두 계통이므로 덕트 공간과 설비비가 커지고, 혼합손실 때문에 에너지 소비량이 많습니다":"덕트가 두 줄이라 공간과 설비비가 늘고 냉풍과 온풍을 섞는 과정에서 에너지가 더 쓰입니다.","두 관 중 작은 쪽의 1/2 이상입니다":"루프통기관과 회로통기관 관경은 두 관 중 작은 쪽의 1/2 이상입니다.","두께 150mm, fy=400MPa, 단면적 71mm²인 D10 철근의 최대간격은 230mm입니다":"이 조건의 D10 철근은 간격을 230mm 넘기지 않아야 합니다.","두 변량을 가로축과 세로축에 놓고 측정값을 타점해 상관관계를 봅니다":"산점도는 두 변량을 가로·세로축에 찍은 점으로 서로 얼마나 관련되는지 보는 그림입니다.","두 수직관 중 작은 쪽 이상입니다":"결합통기관 관경은 두 수직관 중 작은 쪽 이상입니다.","둘러싸인 바닥면적은 60m²를 넘을 수 있고, 문꼴 크기·불균형 배치는 시공상의 대표적 결함이 아닙니다":"내력벽으로 둘러싼 칸의 바닥면적이 60m²를 넘어도 되고 문꼴 크기나 불균형 배치가 대표적 시공 결함은 아닙니다.","듀플렉스형보다 공용면적이 크다거나 프라이버시가 낮고 통로면적이 불리하다고 볼 수는 없습니다":"트리플렉스형이 듀플렉스형보다 공용면적이 크거나 프라이버시가 낮다고 볼 수는 없습니다.","들뜸·주름·늘어남 없이 밀착하고, 우중에는 공사를 중지하며 선홈통과 낙수구 연결부를 특히 주의합니다":"펠트와 루핑은 들뜸, 주름, 늘어남 없이 밀착시키고 비 오는 날은 쉬며 선홈통과 낙수구 연결부를 특히 챙깁니다.","등가정적해석 내진설계의 고려사항입니다":"지역계수, 지반종류, 반응수정계수는 등가정적해석 내진설계에서 고려하는 사항입니다.","등변분포하중의 휨모멘트도는 3차 곡선입니다":"등변분포하중이 걸리면 휨모멘트도가 3차 곡선으로 그려집니다.","디젤해머·프리보링·유압해머 공법이 있다":"기성말뚝 공법에는 디젤해머, 프리보링, 유압해머 공법이 있습니다.","따로 설치해야 하는 경우도 있다":"노외주차장은 입구와 출구를 따로 설치해야 하는 경우도 있습니다.","때때로 물을 뿌리고 표면을 포장해 늘 같은 습윤상태를 유지합니다":"경량골재는 가끔 물을 뿌리고 겉을 덮어 습윤상태를 늘 같게 유지합니다.","라멘과 여러 부재가 만나는 절점에서는 어느 부재의 어느 끝 모멘트인지 구분합니다":"여러 부재가 만나는 라멘 절점에서는 어느 부재의 어느 쪽 끝 모멘트인지 먼저 가립니다.","라멘에서는 6차·8차·9차·10차·11차·12차까지 나옵니다":"라멘에서는 부정정 차수가 6차, 8차, 9차부터 12차까지도 나옵니다.","로우탱크·하이탱크·세정밸브 방식이다":"대변기 세정 급수방식에는 로우탱크, 하이탱크, 세정밸브 방식이 있습니다.","리버스서큘레이션·관입·보아홀 공법이다":"제자리말뚝 기계굴삭 공법에는 리버스서큘레이션, 관입, 보아홀 공법이 있습니다.","리프트 푸팅, 하트포드 접속법, 응축수탱크는 증기난방과 관계가 있지만 팽창관은 관계가 없습니다":"응축수탱크 등은 증기난방 계통의 구성이고 팽창관은 온수난방의 팽창탱크에 딸린 관이라는 구분입니다.","마지막에 용접 면수를 반영합니다":"마지막으로 용접한 면의 수를 곱해 반영합니다.","마지막에 처짐의 단위(cm·mm)를 확인합니다":"답을 내기 전에 처짐 단위가 cm인지 mm인지 맞춰 적습니다.","마찰손실은 빼지 않고 더합니다":"마찰손실은 필요 높이에서 빼는 것이 아니라 더하는 값입니다.","마찰접합에서는 볼트나 판재에 전단 또는 지압응력이 발생하지 않습니다":"마찰접합은 볼트와 판재에 전단응력이나 지압응력이 걸리지 않게 마찰만으로 힘을 넘깁니다.","막을 경계로 객석 쪽에 나온 무대입니다":"에이프런 스테이지는 막을 경계로 객석 쪽에 나온 무대입니다.","만류·연속류를 비만류·비연속류로 만들고, 기구배수관에 각개통기관을 접속하여 공기를 넣으면 막을 수 있습니다":"자기사이폰은 가득 찬 연속류를 끊어 흐르게 하고 기구배수관에 각개통기관을 달아 공기를 넣어 막습니다.","말뚝의 지지력을 가장 신뢰성 있게 확인하는 방법입니다":"재하시험은 말뚝 지지력을 가장 믿을 만하게 확인하는 방법입니다.","말뚝 지지력의 최종 확인시험이 아닙니다":"표준관입시험은 말뚝 지지력의 최종 확인시험으로 쓰지 않습니다.","매립코일이 고장 나면 수리가 어렵습니다":"코일이 구조체 속에 묻혀 있어 고장 난 곳을 찾고 고치려면 바닥 등을 헐어야 합니다.","매설을 원칙으로 하지 않고 반드시 은폐배관으로 하지도 않는다":"건축물 안 가스배관은 매설을 원칙으로 하지 않으며 반드시 은폐배관으로 하지도 않습니다.","먼저 8인승 환산대수를 구하고, 그다음 실제 인승으로 바꿉니다":"계산은 8인승 기준 환산대수를 먼저 구하고 그다음 실제 승강기 인승으로 바꾸는 순서입니다.","먼저 각 후보를 구한 뒤 절댓값을 같게 놓아 길이를 결정합니다":"후보들을 먼저 구한 다음 절댓값을 같게 놓고 길이를 정합니다.","먼저 물의 양을 질량으로 맞춘 뒤 시간 단위까지 확인합니다":"먼저 물의 양을 질량으로 맞추고 시간 단위까지 따져야 합니다.","먼저 부하가 현열만 만드는지, 현열과 잠열을 함께 만드는지 가릅니다":"먼저 열이 온도만 바꾸는지 습기도 함께 바꾸는지로 현열과 잠열을 나눕니다.","먼저 설계볼트장력에 10%를 할증하여 표준볼트장력을 구합니다":"본조임은 설계볼트장력에 10%를 더해 표준볼트장력을 먼저 구합니다.","먼저 유량을 m³/s로 바꾸고":"축동력은 먼저 유량을 m³/s로 바꾸고 시작합니다.","먼저 층수부터 보세요. 15층이면 층수 기준에서 탈락입니다":"다중이용건축물은 층수를 먼저 따지며 15층은 층수 기준에 들지 못합니다.","면적만 맞으면 되는 경우가 있고, 특정 층의 용도를 함께 보는 경우가 있습니다":"면적만 맞으면 되는 용도도 있고 특정 층의 용도와 면적을 같이 보는 용도도 있습니다.","면적이 500㎡로 같을 때 대상이 되는 용도가 갈립니다":"내화구조 기준은 면적이 500㎡로 같아도 용도에 따라 대상 여부가 갈립니다.","모두 설계기준강도의 90% 이상까지 존치하는 것은 아닙니다":"슬래브밑과 보밑 받침기둥을 모두 설계기준강도의 90% 이상까지 존치하는 것은 아닙니다.","모든 계산은 As·fy = 0.85·fck·b·a에서 시작합니다":"모든 철근 계산의 출발점은 인장력과 압축력을 같게 놓은 As·fy = 0.85·fck·b·a입니다.","모든 교실이 특정 교과를 위해 만들어지고 일반교실은 없습니다":"교과교실형은 교실 전부를 특정 교과 전용으로 꾸며 일반교실이 아예 없습니다.","모든 방향이 고르면 전반확산입니다":"배광이 모든 방향에서 고르면 전반확산 조명으로 봅니다.","모래는 다진 상태로 판정합니다":"N값이 기준값에 이르면 모래지반을 다져진 상태로 판정합니다.","모래지반은 내부마찰력이 감소한다":"모래지반은 함수비가 커지면 내부마찰력이 줄어듭니다.","모멘트도가 각 구간에서 직선이면 그 구간의 전단력은 모멘트도 기울기로 읽습니다":"구간마다 직선인 모멘트도는 기울기가 곧 그 구간의 전단력입니다.","모멘트도가 주어지면 반력부터 다시 풀기보다 기울기 변화를 먼저 봅니다":"모멘트도가 있으면 반력을 새로 풀기 전에 기울기가 어디서 바뀌는지부터 봅니다.","모멘트를 받는 정정보의 휨모멘트도에는 그 점에서 점프가 있습니다":"모멘트를 받는 정정보의 휨모멘트도에는 그 점에서 값이 뛰는 구간이 생깁니다.","목구조 기둥·보에 한식지붕틀이다":"한옥은 목구조 기둥·보에 한식지붕틀을 얹은 건축물입니다.","무공해·무독성이며 배관으로 공급한다":"LNG는 무공해·무독성이며 배관으로 공급합니다.","무대 가까이에 두면 편리한 배경제작실입니다":"그린룸은 무대 가까이에 둘수록 쓰기 좋은 배경제작실입니다.","무대 맨 뒤의 배경용 벽이며 하늘이나 구름 같은 자연 현상을 나타냅니다":"사이클로라마는 무대 맨 뒤를 두른 배경 벽으로 하늘과 구름 같은 자연 현상을 비춥니다.","무대 상부공간인 플라이 로프트는 프로시니엄 높이의 4배 이상입니다":"무대 위 빈 공간인 플라이 로프트는 프로시니엄 높이의 네 배를 넘겨 확보합니다.","무대 소품은 낮은 기구로 구성한다":"애리나형 무대의 소품은 낮은 기구로 구성합니다.","무대 양쪽이 좁고 깊이가 깊을 때 채택하는 방식이 아닙니다":"좌우 활주 왜건형식은 무대 양옆이 좁고 깊은 경우에 고르는 방식이 아닙니다.","무대와 객석의 경계를 액자처럼 보이게 하는 시설입니다":"프로시니엄 아치는 무대와 객석을 갈라 무대가 액자 속 그림처럼 보이게 하는 틀입니다.","무대 주위 벽의 6~9m 높이에 설치하는 좁은 통로이고, 그리드 아이언으로 올라가는 계단과 연결됩니다":"플라이 갤러리는 무대를 에워싼 벽의 6~9m 높이에 낸 좁은 통로로 그리드 아이언에 오르는 계단과 이어집니다.","무대 천장 밑에서 조명기구와 배경 등을 매다는 시설이며, 위에는 사람이 다닐 공간을 확보합니다":"그리드 아이언은 무대 천장 아래에 있으며 조명기구와 배경을 매다는 시설인데 위쪽에 작업자가 다닐 자리를 둡니다.","무위사 극락전·금산사 대적광전·지림사 대적광전이 해당하고, 수덕사 대웅전은 해당하지 않습니다":"무위사 극락전, 금산사 대적광전, 지림사 대적광전은 칠량가에 속하고 수덕사 대웅전은 속하지 않습니다.","무허가 건축·용도변경 단속 등도 맡습니다":"건축지도원은 무허가 건축이나 용도변경을 단속하는 일도 맡습니다.","문제에 x축이 주어지면 Ix로 rx를, y축이 주어지면 Iy로 ry를 구합니다":"축 이름에 맞춰 x축은 Ix에서 rx를, y축은 Iy에서 ry를 얻습니다.","문화 및 집회시설, 종교시설, 판매시설이 들어갑니다":"면적 기준 대상 용도는 문화 및 집회시설, 종교시설, 판매시설입니다.","문화 및 집회시설로 분류돼도 다중이용건축물 면적 판정에서는 뺍니다":"전시장은 이름은 집회시설군이어도 면적 합산 기준에서는 빠지는 용도입니다.","문화 및 집회시설 중 공연장이 건축할 수 없는 건축물에 속하지 않습니다":"준주거지역에서 공연장은 지을 수 없는 건축물에 들지 않아 건축할 수 있습니다.","문화 및 집회시설 중 관람장도 불가입니다":"문화 및 집회시설이라도 관람장만큼은 이 지역에서 허용되지 않습니다.","문화 및 집회시설 중 전시장과 동·식물원은 뺍니다":"문화 및 집회시설이어도 전시장과 동·식물원은 면적 기준 대상에서 뺍니다.","문화재 보호와 공원시설보호지구는 이에 속하지 않는다":"문화재 보호와 공원시설보호지구는 시설보호지구에 속하지 않습니다.","물과 오리피스를 분리해 동파를 막는 헤드입니다":"건식 헤드는 물과 오리피스를 떼어 놓아 동파를 막습니다.","물로 포화된 흙에 압력을 가해 간극수가 빠지며 체적이 줄어드는 현상이 압밀이다":"압밀은 물이 가득 찬 흙을 눌러 간극수가 빠지면서 부피가 줄어드는 침하 현상입니다.","물은 상수도에서 저수조로 들어가고":"고가수조방식에서 물은 상수도에서 저수조로 먼저 들어갑니다.","미관지구는 기준 시점에 따라 달라집니다":"미관지구가 용도지구인지는 어느 시점의 법을 기준으로 하느냐에 따라 달라집니다.","밀폐식 팽창탱크는 장치의 주된 공기배출구나 보일러 통기관이 아닙니다":"밀폐식 팽창탱크는 압력 흡수용이라 공기를 빼는 주 배출구나 보일러 통기관 역할은 하지 않습니다.","밑면전단력 산정인자가 아닙니다":"진도계수는 밑면전단력을 구하는 산정인자가 아닙니다.","바깥 단면에서 빈 부분을 빼서 I와 A를 각각 구한 뒤 r=√(I/A)에 넣습니다":"속이 빈 단면은 큰 단면에서 빈 부분을 덜어낸 I와 A로 반경을 계산합니다.","바깥쪽과 접하는 창문 등은 건축물의 다른 창문 등에서 2m 이상 띄웁니다":"계단실 바깥쪽 창은 건물의 다른 창과 2m 이상 간격을 두고 설치해야 합니다.","바뀌어도 조절할 수 있어 신속하고 경제적으로 대처하며, 시설비와 유지비 절감도 특징입니다":"작업 패턴이 바뀌어도 조절할 수 있어 신속하고 경제적으로 대처하며 시설비와 유지비가 줄어듭니다.","바니쉬칠은 바탕 만들기 공정이 아니라 칠하기 공정입니다":"바니쉬칠은 칠하기 단계의 작업이어서 바탕 만들기 공정이 되지 못합니다.","바닥, 벽체, 천장을 방열면으로 할 수 있습니다":"바닥, 벽체, 천장 어디든 복사난방의 방열면으로 쓸 수 있습니다.","바닥과 벽면을 유용하게 이용합니다":"방열기 때문에 못 쓰던 벽 쪽 공간을 비워 두고 활용할 수 있다는 장점입니다.","바닥 단차를 가능한 줄입니다":"병원 전체에서 바닥 단차를 가능한 줄입니다.","바닥면적 1,000m² 이상이면 방화구획된 각 부분마다 직통계단 1개소 이상을 피난계단 또는 특별피난계단으로 설치합니다":"큰 지하층은 방화구획 단위로 나누어 각 구획에 피난계단급 직통계단이 하나는 있어야 합니다.","바닥면적 1000㎡ 이상인 층의 직통계단은 방화구획으로 나뉜 각 부분마다 1개소 이상 설치합니다":"바닥면적 1000㎡ 이상 층은 방화구획된 각 부분마다 직통계단을 한 곳 이상 설치합니다.","바닥면적 3,000m2 종합병원과 5,000m2 업무시설은 해당하지 않는다":"바닥면적 3,000m2 종합병원과 5,000m2 업무시설은 다중이용건축물이 아닙니다.","바닥면적에 0.006을 곱하면 필요한 총너비가 바로 나옵니다":"필요한 출구 총너비는 바닥면적에 0.006을 곱하는 한 번의 계산으로 구합니다.","바닥면적의 합계 2,000㎡ 이상이 기준입니다. 다른 용도와 달리 2,000㎡로 따로 둡니다":"공장은 다른 용도와 달리 바닥면적 합계 2,000㎡ 이상을 기준으로 따로 둡니다.","바닥면적 합계 85m2 미만의 증축·개축·재축을 제외할 수 있습니다":"건축사 설계 의무에서 작은 증축·개축·재축은 85m2 미만이면 예외로 둘 수 있습니다.","바닥면적 합계 85m2 이내입니다":"증축·개축·재축은 바닥면적 합계가 85m2 이내일 때 신고로 갈음합니다.","바닥면적 합계가 4,000㎡여도 두 기준을 모두 못 넘습니다":"판매시설이 바닥면적 합계 4,000㎡면 층수 기준과 면적 기준 둘 다 넘지 못합니다.","바닥슬래브밑·지붕슬래브밑·보밑 판재는 원칙적으로 받침기둥을 해체한 뒤 떼어냅니다":"바닥슬래브 밑, 지붕슬래브 밑, 보 밑에 댄 판재는 받침기둥을 먼저 해체한 다음에 떼는 것이 원칙입니다.","바닥에서 0.8m 이상 1.5m 이하":"비상콘센트는 바닥에서 0.8m 이상 1.5m 이하 높이에 설치합니다.","바닥에서 85cm 높이 지점이 평균 70lux 이상입니다":"조명은 바닥에서 85cm 높이 지점의 평균이 70lux 이상이어야 합니다.","바닥에서 높이 1.5m 이하에 설치한다":"옥내소화전 방수구는 바닥에서 높이 1.5m 이하에 설치합니다.","바닥판 윗면(하단)에서 수평으로 이어친다":"기둥은 바닥판 윗면에서 수평으로 이어칩니다.","바로 뒤에 막이 놓이고, 그 막의 위치가 커튼 라인입니다":"커튼 라인은 프로시니엄 바로 뒤에 놓인 막의 위치입니다.","바탕을 따로 만들어야 합니다":"바깥방수는 바탕을 따로 만들어야 합니다.","바탕이 덜 말랐거나 공기 습도가 높으면 도장하지 않습니다":"바탕이 덜 말랐거나 습도가 높은 날에는 도장을 미룹니다.","반면 한랭지에서 운전을 멈추면 동결 우려가 있습니다":"추운 곳에서 난방을 오래 멈추면 관 속 물이 얼어 배관이 상할 위험이 있습니다.","반원도 같은 원리로 밑변축의 값에서 Aȳ²을 빼 도심축 값으로 옮기며, 이 경우 값은 142.2cm⁴입니다":"반원은 밑변축 값에서 Aȳ²을 덜어 도심축 값으로 옮기며 이때 142.2cm⁴가 나옵니다.","반응수정계수, 중요도계수, 고유주기, 주기 1초에서의 설계스펙트럼 가속도를 봅니다":"Cs는 지진에 얼마나 반응하는지를 나타내는 계수로 반응수정계수, 중요도계수, 고유주기, 주기 1초 스펙트럼 가속도로 정해집니다.","반죽은 시멘트와 혼합 후 2시간 이상 지나면 쓸 수 없음":"돌로마이트 플라스터 정벌바름 반죽은 시멘트와 섞고 2시간 이상 지나면 쓰지 못합니다.","반층 차이로 구분합니다. 주거 단위의 단면을 동일층에 두지 않고 반층씩 엇나가게 합니다":"스킵플로어는 단면을 반층씩 어긋나게 짜므로 반층 차이로 구분합니다.","발산광속의 90~100%가 위로 향하고, 천장과 윗벽에서 확산됩니다":"간접조명은 발산광속의 90~100%가 위로 향해 천장과 윗벽에서 퍼집니다.","발열이 적어 매스콘크리트에 알맞음":"중용열 포틀랜드시멘트는 발열이 적어 매스콘크리트에 알맞습니다.","발전시설이 들어가지 않습니다":"산업 등의 시설군에는 발전시설이 들어가지 않는다는 구분입니다.","방 길이는 바꿀 수 있지만 방 깊이는 바꾸기 어렵습니다":"개실 시스템은 방 길이는 조절해도 방 깊이를 바꾸기는 어렵습니다.","방사선부·분만부·물리치료부와 함께 포함됩니다":"부속진료부에는 방사선부, 분만부, 물리치료부가 함께 포함됩니다.","방수압력 1kg/cm²에서 80ℓ/min 이상입니다":"헤드 방수성능은 방수압력 1kg/cm²에서 80ℓ/min 이상이라는 기준입니다.","방열기가 없으므로 바닥 이용도가 높아집니다":"방열기가 차지하던 바닥 면적이 비어서 가구를 놓는 등 바닥을 더 쓸 수 있습니다.","방열기 표면온도가 높아 쾌적성은 온수난방보다 좋지 않습니다":"방열기 표면이 뜨거워 실내 느낌이 온수난방보다 나쁘다는 판단입니다.","방을 개방한 상태에서도 난방효과가 있습니다":"복사는 공기가 아닌 면에 열을 직접 전하므로 문을 열어 둬도 온기가 유지됩니다.","방의 길이와 깊이에 모두 변화를 줄 수 있습니다":"개방식 사무실은 방 길이와 깊이를 모두 바꿀 수 있습니다.","방화·방도용이고 파편이 튀지 않아 진동에 파손되기 쉬운 곳에 쓴다":"망입유리는 방화·방도용이며 파편이 튀지 않아 진동에 깨지기 쉬운 곳에 씁니다.","배관경과 방열기가 작아지고 시설비도 작아집니다":"운반 열량이 많아 관과 방열기를 작게 만들 수 있고 그만큼 시설비도 줄어듭니다.","배관경이나 방열기는 커지지 않습니다":"열 운반능력이 큰 만큼 배관과 방열기를 키울 필요가 없다는 결론입니다.","배관길이 자체를 더하는 것이 아닙니다":"높이만 더하고 배관길이는 더하지 않습니다.","배관의 상하구배와 높이 변화가 가능하며 지역난방에 이용합니다":"고온수난방은 배관을 위아래로 구부려도 되어 지역난방에도 쓰입니다.","배관의 지지·고정이 어렵고 내화성이 없다":"경질염화비닐관은 배관을 지지·고정하기 어렵고 내화성이 없습니다.","배수관 계통을 환기해 관내를 청결하게 유지하는 목적도 있습니다":"통기관은 배수관 계통을 환기해 관 안을 청결하게 지키는 일도 합니다.","배수관이 막힐 때 예비 배수관으로 쓰거나 오수·잡배수 혼합을 막기 위한 것은 아니다":"통기관은 배수관이 막힐 때 쓰는 예비 배수관이 아니며 오수와 잡배수의 혼합을 막으려는 것도 아닙니다.","배수수직관보다 작으면 안 됩니다":"신정통기관 관경은 배수수직관보다 작으면 안 됩니다.","배수수직관 상부를 최상부 배수수평관의 접속 위치보다 더 올려 대기 중에 개구하는 방식입니다":"신정통기는 배수수직관 윗부분을 최상부 수평관 접속점보다 더 올려 대기 중에 열어 둡니다.","배수수직관에서 분기·입상해 통기수직관에 접속하며, 배수수직관의 압력변화를 방지하거나 완화하는 도피통기관입니다":"결합통기관은 배수수직관에서 갈라 올려 통기수직관에 잇고 배수수직관 안 압력 변화를 막거나 줄이는 도피통기관입니다.","배수수직관의 최상부와 배수수평지관의 최하단부는 설치 장소가 아니며, 통기수직관과 우수수직관도 겸용하지 않습니다":"배수수직관 맨 위와 수평지관 맨 아래는 청소구 자리가 아니며 통기수직관·우수수직관과 겸용도 하지 않습니다.","배수수평주관·수평지관의 기점, 배수수직관의 최하부, 수평주관과 옥외배수관의 접속장소 가까운 곳에 둡니다":"청소구는 수평주관·수평지관의 시작점, 수직관의 맨 아래, 수평주관과 옥외배수관이 만나는 곳 가까이에 둡니다.","배수와 공기의 흐름, 사이폰·배압 방지, 관내 환기를 맡습니다":"통기관은 배수와 공기의 흐름을 돕고 사이폰과 배압을 막으며 관 속을 환기합니다.","배수와 통기 계통 사이의 공기 유통을 원활하게 한다는 설명은 루프통기관의 설명이 아닙니다":"배수와 통기 계통 사이 공기를 잘 통하게 한다는 설명은 루프통기관에 맞지 않습니다.","배연구가 열리면 자동 작동하고 예비전원을 두며, 배연구는 평상시에 열린 상태가 아닙니다":"배연기는 배연구가 열리면 저절로 돌아가고 예비전원을 두며 배연구는 평소 닫혀 있습니다.","배치도·공사설계도서·토지등기부등본을 낸다":"부설주차장 설치계획서에는 배치도, 공사설계도서, 토지등기부등본을 첨부합니다.","버킷·플로트·벨로즈 트랩이 있다":"난방용 증기트랩에는 버킷, 플로트, 벨로즈 트랩이 있습니다.","버팀대가 없어 굴착공간이 넓고 대형기계 반입이 쉬우나 시공 후 검사가 어려움":"어스앵커는 버팀대가 없어 굴착공간이 넓고 대형기계 반입이 쉽지만 시공 후 검사가 어렵습니다.","벽과 반자의 실내 마감은 불연재료로 하고, 채광창이나 예비전원 조명설비를 둡니다":"승강장 마감은 타지 않는 불연재료이며 밝기는 채광창이나 예비전원 조명으로 확보합니다.","벽 단부에 20cm 이상 물리고 기성 콘크리트보·철보 또는 제자리 철근콘크리트보로 만들 수 있으며, 철근을 양단 고정지지로 계산하지는 않습니다":"블록 인방보는 벽 끝에 20cm 이상 얹히게 하며 기성보나 제자리 철근콘크리트보 어느 쪽이든 되고 양단 고정지지로 계산하지는 않습니다.","벽돌조 벽 두께 19cm 이상, 철재 양면을 5cm 이상 철망 모르타르 또는 콘크리트로 덮은 바닥, 무근콘크리트조·콘크리트블록조·벽돌조·석조 계단은 적합합니다":"벽돌조 벽 두께 19cm 이상, 철재 양면을 5cm 이상 철망 모르타르 등으로 덮은 바닥 등이 내화 적합 부재입니다.","벽의 좁은 통로면 플라이 갤러리":"벽의 좁은 통로를 가리키는 말이 플라이 갤러리입니다.","벽체·유리·조명기구의 취득열은 현열만 계산합니다":"벽체, 유리, 조명기구에서 들어오는 열은 현열만 따집니다.","변경 전 용도로 다시 바꾸면서 개축을 수반한 경우가 신고 대상이었습니다":"변경 전 용도로 되돌리면서 개축도 한 경우가 과거에는 신고 대상이었습니다.","변형률 관계로 중립축을 잡고, 콘크리트 압축력과 철근 인장력을 같게 둡니다":"변형률 관계에서 중립축을 잡은 뒤 콘크리트 압축력과 철근 인장력을 같다고 놓습니다.","별도의 통기수직관은 설치하지 않습니다":"신정통기에서는 별도의 통기수직관을 설치하지 않습니다.","병동부의 기본 단위이지 외래진료부의 구성단위가 아닙니다":"간호단위는 병동부의 기본 구성 단위이고 외래진료부를 이루는 단위는 아닙니다.","병렬단자·월패드·전기시계설비는 해당 구성이 아니다":"병렬단자, 월패드, 전기시계설비는 TV공청설비 구성이 아닙니다.","병원 면적에서 가장 큰 부분이며, 약 40%가 적당한 비율입니다":"병동부는 병원 면적 가운데 가장 크며 전체의 약 40% 정도가 알맞습니다.","보안상 필요로 도시개발을 제한하기 위한 지정은 아님":"보안상 필요하여 도시개발을 제한하려는 지정은 시가화조정구역이 아닙니다.","보에서 휨모멘트의 절대값이 가장 큰 단면을 찾습니다":"휨모멘트 절대값이 가장 큰 단면이 최대 휨응력이 생기는 곳입니다.","보유수량이 많고 예열시간이 긴 보일러가 아닙니다":"관류보일러는 물을 적게 담고 빨리 데워지는 형식이라 보유수량이 많은 보일러와는 반대입니다.","보의 높이 h를 먼저 구한 뒤 전단응력을 계산합니다":"전단응력을 구하기 전에 보의 높이 h부터 정합니다.","보일러는 거실 외의 곳에 둡니다":"보일러는 거실 안이 아니라 거실 밖 공간에 설치해야 합니다.","보일러 설치 장소와 거실 사이의 경계벽은 출입구를 제외하고 내화구조로 구획합니다":"보일러실과 거실 사이의 경계벽은 출입구를 뺀 부분을 내화구조로 구획합니다.","보일러에서 만든 증기 또는 고온수를 열원으로 쓰고, 저탕조 안의 코일을 통해 물을 가열하면 간접가열식입니다":"보일러의 증기나 고온수를 열원으로 저탕조 안 코일을 통해 물을 데우면 간접가열식입니다.","보일러의 연도는 내화구조로서 공동연도로 설치합니다":"보일러 연도는 내화구조로 만들고 각각 따로가 아닌 공동연도로 설치합니다.","보일러의 최저 수위 이하에서 연소되는 것을 방지합니다":"하트포드 접속은 환수관을 보일러 수면 가까이 이어서 물이 빠져 수위가 너무 낮아지는 일을 막습니다.","보 전체를 자유물체도로 떼어 냅니다":"단순보 단면력은 보 전체를 자유물체도로 떼어 내는 데서 시작합니다.","보차분리가 되고 쾌적성·안전성 확보가 쉬움":"쿨데삭형은 보행자와 차량을 나눌 수 있어 쾌적하고 안전하게 만들기 쉽습니다.","보통 40MPa 이상·경량골재 27MPa 이상입니다":"고강도 콘크리트의 설계기준강도는 보통 40MPa 이상, 경량골재 27MPa 이상입니다.","보통 동서를 축으로 놓고 한쪽 복도에서 각 주호로 들어갑니다":"편복도형은 복도를 한쪽에 두고 동서 방향으로 길게 놓으며 복도에서 각 주호에 출입합니다.","보통콘크리트, fy=400MPa 철근, 처짐을 따로 계산하지 않는 조건입니다":"일방향 슬래브 최소두께 표는 보통콘크리트와 fy=400MPa 철근을 쓰고 처짐 계산을 생략하는 조건에 맞춘 값입니다.","보행거리를 짧게 하고, 외래자가 쉽게 알 수 있게 합니다":"엘리베이터는 보행거리를 짧게 하고 외래자가 쉽게 알 수 있는 위치에 둡니다.","보행거리와 보행자 도로 상황도 참작한다":"이용자의 보행거리와 보행자 도로 상황도 헤아립니다.","보호각·회전구체법·메시법으로 설치한다":"수뢰부는 보호각법, 회전구체법, 메시법으로 설치합니다.","복도를 외기에 열면 각 호의 채광과 통풍이 양호합니다. 거주성도 균일합니다":"복도가 바깥에 열려 있으면 각 호가 햇빛과 바람을 고르게 받아 거주성이 균일합니다.","복도에서 각 세대로 진입하는 형식입니다":"편복도형은 복도에서 각 세대로 들어가는 형식입니다.","복도에서 각 전시실로 직접 들어갑니다":"갤러리 및 코리더 형식은 복도에서 각 전시실로 직접 들어갑니다.","복도와 엘리베이터홀이 매층 필요한 형식이 아니므로 정지층과 통로면적은 줄고 유효면적은 늘어납니다":"메조넷은 복도와 엘리베이터홀이 매층 필요하지 않아 정지층과 통로면적이 줄고 유효면적이 늘어납니다.","복도 자체도 전시공간으로 사용할 수 있습니다":"복도도 그대로 전시공간으로 활용할 수 있습니다.","복합도형은 먼저 전체 도심을 잡고, 각 조각의 도심축 I에 Ad²을 더해 목표축으로 옮깁니다":"합성 도형은 전체 도심을 먼저 찾고 조각마다 도심축 I에 평행축 항 Ad²을 더해 기준축으로 옮깁니다.","본공사에 선행하는 것은 아닙니다":"안방수는 본공사보다 먼저 하는 방수는 아닙니다.","봉수깊이는 보통 50~100mm이다":"트랩의 봉수는 하수 가스를 막는 물이며 깊이를 50~100mm로 둡니다.","봉수 보급수 장치로 막습니다":"증발로 줄어든 봉수는 봉수 보급수 장치로 막습니다.","부속진료부와 외래부를 주로 저층부에 둡니다":"집중식 병원은 부속진료부와 외래부를 낮은 층에 몰아 둡니다.","부재 양 끝의 휨모멘트 차와 부재 길이로 직선의 기울기를 읽어 전단력을 잡고":"부재 양 끝 휨모멘트의 차를 부재 길이로 나눠 직선 기울기를 읽으면 전단력이 나옵니다.","부재 중요성·재료강도 가변성·철근 위치와 치수 오차가 영향을 준다":"강도감소계수는 부재의 중요성, 재료강도 가변성, 철근 위치와 치수 오차를 반영합니다.","부정정이면 다시 1차, 2차처럼 차수까지 붙입니다":"구조가 부정정이면 거기서 끝내지 않고 1차, 2차처럼 차수까지 붙여 답합니다.","부정정차수가 낮으면 일부 부재나 접합부의 파괴가 트러스 붕괴를 일으킬 수 있습니다":"부정정차수가 낮은 트러스는 일부 부재나 접합부가 부서지면 전체가 무너질 수 있습니다.","부착강도는 √fck에 비례한다":"부착강도는 콘크리트 강도의 제곱근 √fck에 비례합니다.","부품 접합부의 일체화와 절점 강접합은 쉽지 않습니다":"조립식은 부품 접합부를 일체화하고 절점을 강접합하기가 쉽지 않습니다.","부하단위수를 합한 뒤 헌터선도로 동시사용 유량을 구합니다":"부하단위수의 합을 헌터선도에 대 보면 동시에 쓰는 유량이 나옵니다.","부하 중심에 두고 수전이 쉬워야 하며":"변전실은 부하 중심에 두고 전기를 받아들이기 쉬운 곳이어야 합니다.","분쟁 상담, 건축물대장 작성·관리, 허가·신고·용도변경 상담을 처리합니다":"건축종합민원실은 분쟁 상담, 건축물대장 관리, 허가·신고·용도변경 상담을 맡습니다.","분필 조건 허가, 도시계획시설 고시, 산지전용허가 받은 부분이다":"필지 일부를 대지로 쓸 수 있는 경우는 분필 조건 허가, 도시계획시설 고시, 산지전용허가를 받은 부분입니다.","불안정도 답이 될 수 있으므로 정정과 부정정만 비교하지 않습니다":"답에 불안정이 들어갈 수도 있으므로 정정과 부정정 두 가지만 견주지 않습니다.","불연재료로 하고, 배연구가 외기에 접하지 않으면 배연기를 설치합니다":"배연구와 배연풍도는 불연재료로 만들고 배연구가 외기에 접하지 않으면 배연기를 설치합니다.","붉은 집은 아르누보 영역 밖입니다":"윌리엄 모리스의 붉은 집은 아르누보 영역 밖입니다.","브루넬레스키, 미켈란젤로, 알베르티이고 비트루비우스는 해당되지 않습니다":"르네상스 건축가는 브루넬레스키, 미켈란젤로, 알베르티이고 비트루비우스는 아닙니다.","블리딩률 기준은 7% 이하가 아니며, 수중콘크리트의 트레미관은 콘크리트 속에 2m 이상 묻습니다":"주입 모르타르의 블리딩률 기준이 7% 이하라는 말은 틀리고 수중콘크리트의 트레미관은 콘크리트 속에 2m 이상 묻힙니다.","비교적 균일한 강도를 가집니다":"일체식은 구조 전체가 비교적 균일한 강도를 가집니다.","비교적 소규모 사무실 임대에는 유리하지 않습니다":"개방식은 작은 사무실을 임대하는 데에는 알맞지 않습니다.","비교적 시공비가 높고 본공사 진행에 영향을 주며, 내방수보다 하자보수가 곤란합니다":"외방수는 시공비가 높고 본공사 진행에 영향을 주며 하자 보수가 내방수보다 어렵습니다.","비교적 지하수위가 얕은 모래지반의 배수에 유리합니다":"이 배수공법은 지하수위가 비교적 얕은 모래지반의 배수에 유리합니다.","비상방송설비와 자동화재탐지설비는 경보설비이다":"비상방송설비와 자동화재탐지설비는 소방시설 중 경보설비에 속합니다.","비상용승강기는 피난안전구역에서 승하차할 수 있어야 합니다":"비상용승강기는 피난안전구역에서도 타고 내릴 수 있게 설치해야 합니다.","비상용승강기를 설치하는 것이 원칙입니다":"높이 기준을 넘는 건축물은 원칙적으로 비상용승강기를 설치해야 합니다.","비용구배가 최소인 작업부터 단축":"공기단축(MCX)은 비용구배가 가장 작은 작업부터 단축합니다.","비용 비교에서는 비교적 저렴합니다":"안방수는 공사비 면에서 바깥방수보다 비교적 저렴합니다.","비용절감·기능 중심·발주자·사용자 중심이다":"VE는 비용절감, 기능 중심, 발주자·사용자 중심으로 생각하는 기법입니다.","비체적과 습구온도는 감소합니다":"냉각하면 비체적이 줄고 습구온도도 낮아집니다.","빌라 로톤다, 일 레덴토레 성당, 성 죠르죠 맛죠레 성당입니다":"팔라디오 작품에는 빌라 로톤다, 일 레덴토레 성당, 성 죠르죠 맛죠레 성당이 있습니다.","빠르게 하면 간접공사비는 감소하지만, 늦을수록 직접공사비가 증가하는 것은 아닙니다":"공사속도를 빠르게 하면 간접공사비가 줄지만 늦을수록 직접공사비가 늘어난다고 단정하지는 않습니다.","뼈대를 목재로 만들고 벽을 벽돌이나 돌로 막습니다":"목골구조는 뼈대를 목재로 세우고 벽은 벽돌이나 돌로 채웁니다.","사각형보다 삼각형이 안정합니다":"가구식은 사각형 틀보다 삼각형 틀이 안정합니다.","사다리 발판의 너비는 20cm 이상입니다":"사다리를 밟는 발판은 가로폭을 20cm 이상으로 확보합니다.","사람이 가장 몰리는 출근시간을 잡습니다":"엘리베이터 대수는 사람이 가장 몰리는 출근시간을 기준으로 잡습니다.","사무소 기둥간격의 결정 요소가 아닙니다":"엘리베이터 설치 대수는 사무소 기둥간격을 정하는 요소가 아닙니다.","사무소의 성격, 평면형, 구조, 설비방식 등에 따라 정합니다":"사무소의 성격과 평면형, 구조, 설비방식을 따져 코어 위치를 정합니다.","사선제한과 층수제한은 포함되지 않습니다":"사선제한과 층수제한은 지구단위계획 내용에 들지 않습니다.","사실을 나타내는 올바른 데이터로 시작합니다":"통계수법은 사실을 있는 그대로 나타내는 올바른 데이터를 출발점으로 삼습니다.","사용강재 절약과 국부적 응력집중은 특징이 아닙니다":"사용강재를 아낀다거나 국부적 응력집중이 생긴다는 말은 마찰접합의 특징이 아닙니다.","사용전압이 400V가 넘고 전개된 장소에서는 사용할 수 없습니다":"금속 몰드는 사용전압이 400V를 넘고 전개된 장소에서는 쓸 수 없습니다.","사용할 수 있으며, 열용량이 커서 간헐운전에 부적합하지도 않습니다":"간헐운전은 껐다 켰다 하는 운전 방식이며 증기난방도 이 방식에 쓸 수 있다는 내용입니다.","사이즈 s로 목두께를 구하고":"먼저 사이즈 s로 유효목두께를 구합니다.","사이즈가 8mm이면 유효목두께는 0.7×8=5.6mm입니다":"사이즈가 8mm일 때 유효목두께는 5.6mm로 0.7을 곱해 얻습니다.","사이즈 자체를 면적 계산에 넣지 않습니다":"사이즈 s 자체를 면적 계산에 넣지 않고 유효목두께를 씁니다.","사이폰 작용과 배압으로 트랩 봉수가 파괴되는 것을 막습니다":"통기관은 사이폰 작용과 배압 때문에 트랩의 봉수가 깨지는 일을 막습니다.","사질토에도 적용할 수 있지만, 여러 개를 박은 지지력을 단순히 개수 배로 보면 안 됩니다":"마찰말뚝은 사질토에도 쓰지만 여러 개를 박은 지지력을 개수 배로 단순 계산하면 안 됩니다.","산과 알칼리에 약하지 않습니다":"에폭시가 산과 알칼리에 약하다는 말은 맞지 않습니다.","산업전시장·수족관·자동차경기장·공연장은 문화 및 집회시설로 확인합니다":"산업전시장, 수족관, 자동차경기장, 공연장은 모두 문화 및 집회시설 용도로 분류합니다.","상부 기수드럼의 증기를 사용합니다":"위쪽 기수드럼에는 물과 증기가 분리되어 있어 거기 모인 증기를 꺼내 씁니다.","상부에 100~110cm 정도로 배치합니다":"거푸집 철선 조임은 위쪽에서 100~110cm 안팎으로 배치합니다.","상향공급이 일반적이고, 전력공급이 중단되면 급수가 불가능합니다":"펌프직송방식은 위로 올려 보내는 상향공급이 보통이며 전력이 끊기면 급수할 수 없습니다.","상황이 정해지면 장치가 정해집니다":"어떤 상황인지 정해지면 그에 맞는 안전장치가 하나로 정해집니다.","새로 출간된 신간 서적 안내에도 반개가식을 채용합니다":"신간이 새로 나왔다는 소식을 알리는 신간 안내에도 반개가식을 씁니다.","샘플러를 30cm 관입시키는 데 필요한 타격횟수입니다":"N값은 샘플러를 30cm 박는 데 필요한 타격횟수를 말합니다.","생산에 필요한 공정과 기계류를 제품의 흐름에 따라 배치합니다":"제품중심 레이아웃은 제품이 흐르는 순서대로 필요한 공정과 기계를 늘어놓는 배치입니다.","생활 변화에 자유롭게 대응하기는 어렵고 벽식구조의 공간 융통성도 크지 않습니다":"생활이 바뀔 때 자유롭게 대응하기 어렵고 벽식구조도 공간 융통성이 크지 않아 장점으로 꼽을 수 없습니다.","생활편의시설은 집중 배치하고 주동선은 최단거리":"생활편의시설은 한곳에 모아 두고 주동선은 가장 짧은 거리로 잇습니다.","샤워기 5개, 접속배관경 20mm, 동시사용률 70%이면 주배관경은 32mm입니다":"샤워기 5개를 동시사용률 70%로 보면 접속배관이 20mm여도 주배관은 32mm가 됩니다.","서고와 열람실을 분리하며 규모가 큰 도서관의 독립된 서고에 많이 채용됩니다":"폐가식은 서고와 열람실을 따로 두는 방식으로 큰 도서관의 독립 서고에 많습니다.","서로 교차하지 않는 것이 좋다":"점원 동선과 고객 동선은 서로 교차하지 않는 것이 좋습니다.","서비스 부분이 각 층에 균등하고 외관이 정돈됨":"코어를 쓰면 서비스 공간이 층마다 같은 자리에 반복되어 균형이 잡히고 겉모습도 가지런합니다.","서울 남대문은 주심포가 아니라 다포입니다":"서울 남대문은 공포가 기둥 사이에도 놓인 다포식 건물입니다.","서울 동대문·창덕궁 돈화문·전등사 대웅전도 다포입니다":"서울 동대문과 창덕궁 돈화문, 전등사 대웅전도 같은 다포 계열 건물에 속합니다.","석구조·블록구조와 같은 조적식이며 내화·내구적이지만 풍압력과 지진력에 약해 고층·대규모 건물에는 적합하지 않습니다":"벽돌구조는 석구조나 블록구조와 같은 조적식이어서 불과 세월에 강하지만 바람과 지진에 약해 고층·대규모에는 맞지 않습니다.","선도에서 구하는 값이 아니다":"열용량과 기류는 습공기선도에서 구하는 값이 아닙니다.","선팽창계수가 거의 같고 응력은 표면 부착력으로 전달된다":"철근과 콘크리트는 선팽창계수가 거의 같고 응력은 표면 부착력으로 전달됩니다.","선행작업이 여러 개면 다음 작업의 EST는 선행 EFT 중 최대값을 택해야 모두 끝난 뒤 시작할 수 있습니다":"선행작업이 여럿이면 그중 가장 늦게 끝나는 EFT를 EST로 삼아야 모든 선행이 끝난 뒤에 시작할 수 있습니다.","설계부터 공사관리까지의 지도·조언·관리 업무를 맡는다":"CM은 설계부터 공사관리까지 지도, 조언, 관리 업무를 맡습니다.","설비 덕트나 배관을 사무실 공간으로 연결하는 데 제약이 있습니다":"외코어형은 설비 덕트와 배관을 사무실 공간으로 끌어오는 데 제약이 따릅니다.","세대당 건설비·유지비 절감, 생활 협동체 구성, 공동시설 설치가 이점입니다":"공동주택은 세대당 건설비와 유지비를 줄이고 생활 협동체와 공동시설을 둘 수 있는 점이 이점입니다.","세대 안에 계단을 두므로 소규모 주택에는 비경제적이고 면적상 불리합니다":"메조넷은 집 안에 계단이 들어가 면적을 더 쓰므로 작은 주택에는 경제적이지 않습니다.","세대 양쪽에 개구부를 낼 수 있어 일조와 통풍도 좋습니다. 다만 승강기 1대당 이용률은 복도형보다 적습니다":"홀형은 세대 양쪽에 창을 낼 수 있어 일조·통풍이 좋으나 승강기 한 대가 맡는 세대 수는 복도형보다 적습니다.","세정밸브부터 고가수조 저수위면까지의 높이는 둘을 더합니다":"세정밸브에서 고가수조 저수위면까지의 높이는 필요 압력 높이와 마찰손실을 더한 값입니다.","세제곱이 아니라 최종식에서 제곱입니다":"높이는 최종식에서 세제곱이 아니라 제곱으로 들어갑니다.","섹션으로 분할되므로 반입·조립·증설이 쉽습니다":"주철제는 섹션별로 나누어 들여와 현장에서 맞추므로 반입과 증설이 쉽습니다.","소방차가 쉽게 접근하는 노출된 곳에 두며 구경 65mm이다":"송수구는 소방차가 쉽게 다가가는 노출된 곳에 두며 구경은 65mm입니다.","소성변형을 허용하는 내진설계가 가능":"SN 강재는 소성변형을 허용하는 내진설계에 쓸 수 있습니다.","소요동력을 묻고 여유율이 주어지면 축동력을 구합니다":"소요동력을 구하는 문제에 여유율이 나오면 축동력을 먼저 계산합니다.","소요량 또는 소비량×단위당 가격입니다":"경비는 소요량 또는 소비량에 단위당 가격을 곱해 구합니다.","소음 경감을 고려해야 합니다":"개방식에서는 소음 경감을 고려해야 합니다.","송풍기부하와 환기부하 등을 말합니다":"장치부하에는 송풍기부하와 환기부하 등이 들어갑니다.","송풍량 조절 기준은 실내 현열부하입니다":"변풍량방식은 방의 현열부하, 곧 온도 변화에 드는 열량을 보고 송풍량을 정합니다.","쇠흙손으로 바르고 나무흙손으로 눌러 고른 뒤 쇠흙손으로 끝냅니다":"미장은 쇠흙손으로 바른 뒤 나무흙손으로 눌러 고르고 마지막에 쇠흙손으로 마무리합니다.","수관보일러는 연관식보다 설치면적이 넓고 초기 투자비가 적지 않습니다":"연관식과 견주면 수관보일러가 더 넓은 설치면적을 차지하고 초기 투자비도 더 든다는 뜻입니다.","수도 본관의 영향으로 급수압력 변화가 심하지 않고, 상향급수 배관을 주로 쓰지도 않습니다":"고가수조방식은 수도 본관의 영향을 덜 받아 급수압력이 크게 변하지 않고 상향급수 배관을 주로 쓰지도 않습니다.","수신안테나·증폭기·컨버터(주파수변환기)·혼합기이다":"TV공청설비는 수신안테나, 증폭기, 컨버터(주파수변환기), 혼합기로 구성됩니다.","수압이 적을 때 적용하며 시공시기 조정이 가능합니다":"내방수는 수압이 적을 때 쓰며 시공 시기를 조정할 수 있습니다.","수위계를 수조 내측에 설치하거나 수조를 다른 설비와 겸용하여 설치하지 않습니다":"수위계를 수조 안쪽에 달거나 수조를 다른 설비와 같이 쓰는 것은 하지 않습니다.","수증기를 더하거나 빼는 과정이 아니므로 절대습도는 그대로라고 잡습니다":"수증기를 보태거나 빼지 않으므로 절대습도가 변하지 않는다고 봅니다.","수증기의 엔탈피에서 건공기의 엔탈피를 뺀 값이 아니며, 냉각·가습할 때 항상 감소한다고도 할 수 없습니다":"엔탈피를 수증기 엔탈피에서 건공기 엔탈피를 뺀 값이라 하면 틀리고 냉각·가습 때 늘 줄어드는 것도 아닙니다.","수직동선이 양쪽에 놓여 2방향 피난에 이상적이고 방재상 유리합니다":"양단코어형은 수직동선이 양끝에 있어 두 방향으로 피난할 수 있어 방재에 유리합니다.","수직·수평철근 간격은 벽두께의 3배 이하, 400mm 이하이다":"벽체 수직·수평철근 간격은 벽두께의 3배와 400mm 중 어느 쪽도 넘지 않아야 합니다.","수직·수평철근을 벽면에 평행하게 양면 배치한다":"벽이 두꺼우면 수직철근과 수평철근을 벽면과 나란히 양쪽 면에 한 겹씩 넣습니다.","수직철근비는 0.12% 이상, 수평철근비는 0.20% 이상이다":"내력벽 철근비는 수직철근비가 0.12% 이상, 수평철근비가 0.20% 이상입니다.","수질오염 가능성이 적고, 위생성과 유지·관리 측면에서 가장 바람직합니다":"수도직결방식은 물이 오염될 가능성이 적어 위생과 관리 면에서 가장 낫습니다.","수평거리에 3을 곱합니다. 그림의 경우 최고 높이는 36m입니다":"최고 높이는 도로 반대쪽 경계선까지의 수평거리에 3을 곱해 구하며 그림의 경우 36m입니다.","수평하중에 대한 접합부의 연성능력은 낮지 않습니다":"철골구조는 수평하중이 올 때 접합부가 늘어나는 연성이 부족하지 않습니다.","숙박시설·운수시설은 불가입니다":"숙박시설과 운수시설은 이 지역에서 허용되지 않는 용도입니다.","숙박시설은 설치 대상이 아님":"숙박시설은 옥상광장 설치 대상이 아닙니다.","순간처짐 검토에는 전단면·균열단면·유효단면의 단면2차모멘트를 보고, 단면극2차모멘트는 필요하지 않습니다":"철근콘크리트 보의 순간처짐은 전단면, 균열단면, 유효단면의 단면2차모멘트를 보며 단면극2차모멘트는 필요하지 않습니다.","순서는 상수도 → 저수조 → 펌프 → 고가수조 → 위생기구입니다":"공급 순서는 상수도, 저수조, 펌프, 고가수조, 위생기구입니다.","순서별 통과·공간절약·동선 단절":"연속순로의 특징어는 순서별 통과, 공간절약, 동선 단절입니다.","숫자나 위치만으로 신고 대상이 되지는 않습니다":"면적 숫자나 위치만 가지고는 용도변경 신고 대상이 되지 않습니다.","스프레이건과 칠면 거리는 30cm, 공기압은 2~4kg/cm2가 표준이다":"뿜칠은 스프레이건과 칠면 거리를 30cm, 공기압을 2~4kg/cm2로 하는 것이 표준입니다.","습공기를 냉각할 때 수증기가 작은 물방울이나 이슬방울로 응축되기 시작하는 온도입니다":"습공기를 식힐 때 수증기가 작은 물방울이나 이슬로 맺히기 시작하는 온도가 노점온도입니다.","습구온도는 건구온도보다 높을 수 없습니다":"건구온도와 습구온도가 같으면 습구온도가 건구온도보다 높을 수 없다는 점을 이용합니다.","습구온도·엔탈피·노점온도 등이다":"습공기선도에 나오는 요소에는 습구온도, 엔탈피, 노점온도가 있습니다.","습기가 많은 은폐 장소에도 적당하지 않습니다":"금속 몰드는 습기가 많은 은폐 장소에도 알맞지 않습니다.","승강장은 각 층 내부와 연결하고, 출입구는 승강로 출입구를 제외하고 60+방화문 또는 60분 방화문으로 설치합니다":"승강장 출입구는 승강로 출입구를 뺀 부분에 60+방화문 또는 60분 방화문을 설치합니다.","승객의 층별 대기시간은 평균 운전간격 이하가 되어야 합니다":"승객이 층에서 기다리는 시간은 평균 운전간격을 넘지 않게 해야 합니다.","시가화 유보기간은 5년 이상 20년 이내":"시가화조정구역은 시가화를 미루는 유보기간을 두며, 그 기간은 법령상 5년 이상 20년 이내 범위에서 정합니다.","시각적 개방감과 네 입면의 강조, 랜드마크 역할이 주된 특징이지만 세대별 거주 조건이나 채광·통풍이 모두 같지는 않습니다":"탑상형은 개방감, 네 입면 강조, 랜드마크 역할이 특징이나 세대별 조건과 채광·통풍은 고르지 않습니다.","시각 차단이 없어 경영자가 전체를 통제하기 쉽습니다":"칸막이가 없어 시선이 트이므로 경영자가 전체를 한눈에 통제하기 쉽습니다.","시각 차단이 없어 독립성이 떨어지고 소음이 큽니다":"개방식은 서로 시선을 가릴 것이 없어 독립성이 약하고 소리가 큽니다.","시간 단위를 바꾸지 않으면 답이 나오지 않습니다":"시간 단위를 초 단위로 바꾸지 않으면 값을 구할 수 없습니다.","시계·귀금속·의약품 상점에서 쓴다":"대면판매형식은 시계, 귀금속, 의약품 상점에서 씁니다.","시공방법·동선계획·개략공정계획을 표시합니다. 각부 구조계획은 넣지 않습니다":"사전승인 설계설명서에는 시공방법, 동선계획, 개략공정계획을 나타내고 각부 구조계획은 넣지 않습니다.","시공이 간편하고 바탕을 따로 만들 필요가 없습니다":"안방수는 시공이 쉽고 바깥방수처럼 바탕을 따로 만들 일이 없습니다.","시공이 쉬워 공기가 절약되고 불량개소 수정과 품질관리도 쉽습니다":"마찰접합은 시공이 쉬워 공기를 줄이고 불량 부분을 고치거나 품질을 관리하기도 쉽습니다.","시공 정밀도가 기능공의 기능도에 따라 크게 좌우되지는 않습니다":"갱폼은 시공 정밀도가 작업자 솜씨에 크게 좌우되지 않습니다.","시그널 콘트롤식과 배전방식은 간선 배선방식이 아니다":"간선 배선방식에는 시그널 콘트롤식이나 배전방식이라는 이름이 없습니다.","시기가 자유로운 것은 아닙니다":"바깥방수는 시공할 수 있는 시기가 제한적입니다.","시방이 없으면 영식 또는 화란식":"벽돌쌓기는 시방에 정함이 없으면 영식 또는 화란식으로 합니다.","시설도 장래성을 고려해야 합니다":"장치공업의 설비도 훗날의 변화를 내다보고 계획해야 합니다.","시설면적 200㎡당 1대입니다":"숙박시설은 시설면적 200㎡당 한 대가 기준입니다.","시설면적으로 계산합니다. 80㎡당 1대와 150㎡당 1대는 둘 다 기준이 아닙니다":"위락시설은 시설면적으로 계산하며 80㎡당 한 대와 150㎡당 한 대는 둘 다 기준이 아닙니다.","시설비와 유지관리비가 많이 들며, 대규모 급수 수요에 쉽게 대응하지 못하고 고층 건물에 주로 쓰지도 않습니다":"압력수조방식은 시설비와 유지관리비가 부담이고 큰 급수 수요에 쉽게 맞추지 못하며 고층에 주로 쓰지도 않습니다.","시장·군수·구청장이 도시화의 가능성이 크다고 인정하여 지정·공고하는 지역도 포함됩니다":"도시화 가능성이 크다고 시장·군수·구청장이 인정해 지정·공고한 지역도 대상 지역에 듭니다.","시장·군수·구청장이 지정할 수 있습니다":"건축지도원은 시장·군수·구청장이 지정할 수 있는 사람입니다.","신고만으로 허가를 받은 것으로 봅니다. 기준은 100m2와 85m2입니다":"허가 대상이라도 작은 규모면 신고만으로 허가를 받은 것으로 치며 그 경계가 면적 기준입니다.","신축 흡수 이음을 두고 주요 구조부를 관통하지 않는다":"도시가스 배관은 신축을 흡수하는 이음을 두고 주요 구조부를 관통하지 않습니다.","실내 배관으로 누수 우려가 있다":"전수방식은 실내에 배관이 있어 누수 우려가 있습니다.","실내부하가 줄면 송풍량도 줄일 수 있어 정풍량방식보다 에너지 절감효과가 큽니다":"부하가 줄 때 송풍량도 같이 줄이므로 늘 같은 양을 보내는 정풍량방식보다 에너지가 덜 듭니다.","실내수영장 500m2와 연구소 3,000m2도 제출 대상입니다. 병원 1,500m2는 아닙니다":"에너지절약계획서는 실내수영장 500m2와 연구소 3,000m2도 내며 병원 1,500m2는 내지 않습니다.","실내에 방열기를 설치하지 않으므로":"복사난방은 열이 바닥·벽·천장 면에서 나오므로 따로 놓는 방열기가 필요 없습니다.","실내온도 변화에 대한 응답이 빠르고, 부하특성이 다른 여러 실이나 존에도 적용할 수 있습니다":"냉풍과 온풍이 모두 준비되어 있어 온도 변화에 빨리 반응하고 부하가 다른 존에도 맞춥니다.","실내외 온도차에 의한 공기 밀도차가 원동력이다":"중력환기는 실내외 온도차로 생기는 공기 밀도차가 원동력입니다.","실제 보에서는 균형보다 철근을 적게 둔 과소철근보로 설계하여 압축콘크리트의 취성파괴를 막습니다":"과소철근보는 균형보다 철근을 적게 넣어 압축콘크리트가 갑자기 부서지는 취성파괴를 피하게 한 보입니다.","실제 작업이 아니라 작업의 상호관계만 나타내는 화살선입니다":"Dummy는 일을 하는 작업이 아니라 작업끼리의 선후 관계만 나타내는 화살선입니다.","심근·협심증 환자의 집중치료 간호단위입니다":"C.C.U는 심근경색이나 협심증 환자를 집중적으로 돌보는 간호단위입니다.","심부지름 최소 200mm 이상":"나선철근으로 감은 압축부재는 심부지름이 최소 200mm 이상이어야 합니다.","심한 휘도차와 짙은 그림자가 생깁니다":"직접조명형은 밝기 차이가 심하고 그림자가 짙게 생깁니다.","아스팔트방수층에서는 치켜올림을 고려해 밑창콘크리트를 60㎝ 이상 넓게 하고 방수층을 접어 올릴 수 있게 합니다":"아스팔트방수층은 접어 올릴 것을 생각해 밑창콘크리트를 60㎝ 이상 넓게 깔고 방수층을 치켜올릴 수 있게 합니다.","아스팔트·시트·도막방수가 들어가고 실링방수는 들어가지 않습니다":"멤브레인 방수에는 아스팔트, 시트, 도막방수가 해당하고 실링방수는 해당하지 않습니다.","아치 뒤의 조명·눈·비 연출용 발판이 아닙니다":"플로어 트랩은 조명, 눈, 비 같은 연출을 아치 뒤에서 하는 발판이 아닙니다.","아키트레이브와 파일론은 바실리카 구성이 아니다":"아키트레이브와 파일론은 바실리카에 쓰이는 구성 용어가 아닙니다.","아파트·종교시설·노유자시설은 가능합니다":"이 지역에서는 아파트, 종교시설, 노유자시설을 짓는 것이 허용됩니다.","안마시술소는 조례로도 허용되지 않습니다":"안마시술소는 조례로도 허용되지 않는 시설이라는 설명입니다.","안전성은 계수하중, 처짐·균열 같은 사용성은 사용하중으로 검토한다":"구조 안전은 키운 하중으로, 처짐과 균열 같은 사용 성능은 실제 하중으로 점검합니다.","알칼리골재반응 억제용이 아님":"내황산염시멘트는 알칼리골재반응을 억제하려는 용도가 아닙니다.","압밀침하와 주변 대지·도로의 균열 위험이 있습니다":"지하수를 빼면 땅이 눌려 가라앉는 압밀침하가 생겨 주변 대지와 도로에 금이 갈 위험이 있습니다.","압축기는 구성요소가 아니고, 증발기로 용액을 농축하지도 않습니다":"흡수식은 압축기 대신 흡수기와 발생기로 작동하므로 압축기는 구성요소가 아닙니다.","압축기의 임펠러가 회전할 때 생기는 원심력으로 냉매가스를 압축합니다":"임펠러가 돌 때 바깥으로 쏠리는 원심력으로 냉매가스를 눌러 압력을 높입니다.","압축력에는 강하지만 횡력에는 약하고 모르타르 강도도 중요합니다":"조적식은 누르는 힘에는 강하지만 옆에서 미는 힘에 약하며 모르타르의 강도가 큰 변수입니다.","압축력은 0.85·fck·b·a":"단근 직사각형보의 압축력은 0.85·fck·b·a입니다.","압축재는 볼트구멍 단면결손을 고려하지 않고, 인장재는 폭두께비를 고려하지 않음":"압축재는 볼트구멍으로 줄어든 단면을 따지지 않고 인장재는 폭두께비를 따지지 않습니다.","압축콘크리트가 한계변형률에 도달하는 순간 인장철근도 항복하는 상태가 균형상태입니다":"균형상태란 압축콘크리트가 한계변형률에 이르는 때 인장철근도 같이 항복하는 상태입니다.","압축콘크리트의 취성파괴를 막기 위해서이다":"과소철근 보로 설계하는 이유는 압축콘크리트가 갑자기 부서지는 취성파괴를 막으려는 것입니다.","액화석유가스로 공기보다 무겁고":"LPG는 액화석유가스이며 공기보다 무겁습니다.","액화하면 체적이 약 1/250이 된다":"LPG는 액화하면 체적이 약 1/250로 줄어듭니다.","앱스·아일·네이브로 구성된다":"바실리카 교회는 앱스, 아일, 네이브로 구성됩니다.","야간과 직사광선을 피하고, 도막 손상 우려가 있을 때도 칠하지 않습니다":"밤이나 직사광선 아래에서는 칠하지 않으며 도막이 상할 우려가 있을 때도 칠하지 않습니다.","얇은 시트, 내화학성 파이프, 건축용 성형폼과 연결합니다":"폴리에틸렌은 얇은 시트, 내화학성 파이프, 건축용 성형폼과 짝지어집니다.","양면은 5.6×484×2=5420.8mm²이므로 약 5421mm²입니다":"이번에는 유효길이 484mm로 5.6×484×2=5420.8mm²이므로 약 5421mm²입니다.","양수량 10m³/min, 전양정 10m, 효율 80%이면 20.4kW입니다":"조건에 맞게 계산하면 축동력은 20.4kW입니다.","양수량 2m³/min, 전양정 50m, 효율 60%, 밀도 1,000kg/m³이면 축동력은 27.22kW입니다":"조건에 맞게 축동력을 계산하면 27.22kW입니다.","양옆에 난간을 설치하며 기준은 1.2m가 아니다":"높이 1m를 넘는 계단은 양옆에 난간을 설치하며 기준이 1.2m인 것은 아닙니다.","양쪽 끝과 위쪽 끝은 외벽면과 지붕면에서 0.5m 이상 튀어나옵니다":"방화벽은 양쪽 끝과 위쪽 끝이 외벽면과 지붕면보다 0.5m 이상 튀어나와야 합니다.","어느 축을 기준으로 하느냐가 먼저입니다":"관성 모멘트 성질의 값은 기준으로 삼는 축부터 정해야 정해집니다.","어린이회관과 야외음악당은 관광휴게시설입니다":"법 분류에서 어린이회관과 야외음악당이 속하는 곳은 관광휴게시설입니다.","업무범위에 따른 계약에 해당하지 않음":"공동도급은 업무범위에 따른 계약 방식에 들지 않습니다.","엔탈피·비체적·습구온도는 증가합니다":"가열하면 엔탈피, 비체적, 습구온도는 증가합니다.","엔탈피·상대습도·절대습도를 구할 수 있다":"건구온도와 습구온도를 알면 선도에서 엔탈피, 상대습도, 절대습도를 읽을 수 있습니다.","엘리베이터 홀은 출입구문에 바짝 붙이지 않으며, 화장실은 외래자가 알기 쉬워야 합니다":"엘리베이터 홀을 출입구 문 코앞에 두지 않고 화장실은 처음 온 사람도 찾기 쉽게 둡니다.","여기에 70%를 곱하면 최대수요전력은 189kW입니다":"설비용량에 수용률 70%를 곱하면 최대수요전력 189kW입니다.","여유율은 효율과 섞지 말고 마지막에 처리합니다":"여유율은 효율과 따로 두고 계산 맨 끝에 반영합니다.","역압에 의한 분출은 배수수직관 하단부에 통기관을 설치해 방지합니다":"배압으로 뿜어 나오는 것은 배수수직관 아래쪽에 통기관을 달아 막습니다.","연간 소비동력과 운전비는 더 커지지 않습니다":"변풍량방식은 연간 소비동력과 운전비가 정풍량방식보다 늘어나지 않는다는 내용입니다.","연관식보다 사용압력이 높고 부하변동 추종성이 높습니다":"수관보일러는 높은 압력까지 쓸 수 있고 부하가 변해도 잘 따라가는 보일러입니다.","연구소, 유스호스텔, 노인복지시설도 포함됩니다":"배연설비 설치 용도에 연구소, 유스호스텔, 노인복지시설도 들어 있습니다.","연도는 내화구조이면서 공동연도입니다":"연도에는 내화구조와 공동연도라는 두 조건이 함께 붙습니다.","연면적 1,000m² 이상이면 방화구조로 하거나 불연재료로 해야 하며, 같은 답이 세 번 반복되었습니다":"연면적 1,000m² 이상 목조건축물은 방화구조로 하거나 불연재료로 해야 한다는 규정입니다.","연면적 12,000㎡이면 12,000×70%=8,400㎡입니다":"연면적이 12,000㎡이면 70%인 8,400㎡ 이상을 주차장으로 써야 한다는 계산입니다.","연면적 5,000m2 이상인 업무시설·숙박시설은 확보 대상이다":"연면적 5,000m2 이상인 업무시설과 숙박시설은 공개공지를 확보해야 합니다.","연면적 합계 100m2 이하입니다":"신고갈음의 신축 등에서 연면적 합계가 100m2 이하이면 적용 대상입니다.","연속 받침부 중심간 경간 차이는 긴 경간의 1/3 이하입니다":"연속한 받침부 중심 사이 경간 차이는 긴 경간의 1/3을 넘지 않아야 합니다.","연약점토 함수비를 줄이는 데 샌드드레인을 쓸 수 있다":"샌드드레인은 모래 기둥으로 물을 빼 연약점토의 함수비를 낮추는 공법입니다.","연약한 토사 지반의 지반증폭계수가 가장 큽니다":"무른 흙 지반일수록 지진 때 흔들림이 크게 증폭되어 지반증폭계수가 가장 큽니다.","열경화성이어서 폴리스티렌과 구분됩니다":"알키드와 실리콘은 열경화성이라 열가소성인 폴리스티렌과 구분됩니다.","열람석으로 가기 전에 관원의 검열을 받습니다":"안전개가식은 열람석으로 가기 전에 관원 앞에서 검열을 받는 점이 다릅니다.","열람실에서 감시가 필요하지는 않습니다":"폐가식은 열람실에서 이용자를 따로 감시할 필요가 없습니다.","열람자가 서가에서 책을 직접 꺼내 고르고, 검열 없이 열람합니다":"자유개가식은 이용자가 서가에서 직접 책을 꺼내 고르며 검열을 받지 않습니다.","열람자는 서가에 면하여 책의 체제나 표지 정도만 직접 봅니다":"반개가식은 서가 앞에서 책의 겉모양과 표지 정도만 직접 살펴볼 수 있습니다.","열매온도가 높아 방열기 방열면적이 작아집니다":"증기는 온도가 높은 열매라 방열기의 방열면적을 작게 해도 된다는 내용입니다.","열매체가 증기 또는 냉·온수여서 운송동력이 공기보다 적게 든다":"전수방식은 열매체가 증기나 냉·온수여서 운송동력이 공기보다 적게 듭니다.","열에너지로 냉동하거나 냉매가스를 압축하는 장치가 아니다":"열에너지로 냉동하는 것은 흡수식 냉동기고 냉매가스를 누르는 것은 압축기이며 냉각탑은 둘 다 아닙니다.","열용량이 커서 예열시간이 길고, 보일러 정지 뒤에도 여열로 난방이 어느 정도 지속됩니다":"물은 열용량이 커서 데우는 데 오래 걸리지만 한번 데워지면 보일러를 꺼도 한동안 식지 않습니다.","열용량이 크고 예열시간이 깁니다":"복사난방은 데울 구조체의 열용량이 커서 예열에 시간이 오래 걸립니다.","열전도가 크고 온도변화에 따른 신축도 크므로 바탕재와의 연결이 쉽지는 않습니다":"금속판 지붕은 열전도와 신축이 커서 바탕재와 잇기 쉽지 않습니다.","염소이온량 0.30kg/m3 이하입니다":"보통 콘크리트에 들어 있는 염소이온은 0.30kg/m3를 넘으면 안 됩니다.","영업시설군→근린생활시설군, 근린생활시설군→주거업무시설군은 신고입니다":"영업에서 근린생활로, 근린생활에서 주거업무로 옮기는 것처럼 아래 방향 변경은 신고만 하면 됩니다.","오버헤드가 작고 기계실 위치가 자유롭다":"유압식 엘리베이터는 오버헤드가 작고 기계실 위치가 자유롭습니다.","옥내 바닥면적은 1대당 6㎡ 이상이며, 피난층 승강장 출입구에서 도로 또는 공지까지는 30m 이하입니다":"승강장 넓이는 승강기 한 대마다 6㎡ 이상이고 피난층에서 도로까지는 30m 이내입니다.","온도상승에 따른 물의 체적팽창과 압력을 흡수합니다":"팽창탱크는 물이 데워져 부피가 늘어날 때 늘어난 물과 압력을 받아 주는 탱크입니다.","온도차는 급탕온도에서 급수온도를 뺍니다":"온도차는 급수온도를 급탕온도에서 뺀 값입니다.","온수난방보다 예열시간이 짧습니다":"난방을 켠 뒤 따뜻해지기까지 걸리는 시간이 증기난방은 온수난방보다 짧다는 비교입니다.","온수난방은 증기난방보다 소요 방열면적과 배관경이 작지 않아 설비비가 적지 않습니다":"온수난방은 방열면적과 배관이 증기난방보다 커서 설비비가 더 든다는 비교입니다.","온수난방의 복관식 배관에서 역환수 방식을 쓰는 가장 주된 이유는 온수 순환의 평균화입니다":"역환수 방식은 각 방열기까지 배관 길이를 같게 맞춰 온수가 고르게 돌게 하는 방식입니다.","온수의 순환방식은 중력식과 강제식으로 구분합니다":"중력식은 물의 밀도 차로, 강제식은 펌프로 온수를 돌린다는 구분입니다.","왕복동식보다 진동이 적지만, 흡수식과 비교하면 소음과 진동이 심합니다":"터보는 왕복동식보다 진동이 적지만 흡수식보다는 시끄럽고 진동이 큽니다.","외국공관과 오피스텔을 뺍니다. 남은 업무시설은 150㎡당 1대입니다":"업무시설은 외국공관과 오피스텔을 뺀 나머지를 150㎡당 한 대로 계산합니다.","외기량이 부족해 실내공기가 오염되기 쉽습니다":"팬코일 유닛은 외기를 충분히 끌어들이는 구조가 아니라서 실내 공기가 탁해지기 쉽습니다.","외기에 닿는 면을 줄이는 방향으로 판단합니다":"에너지를 아끼려면 건물이 바깥 공기와 맞닿는 면을 줄이는 쪽이 맞는 답입니다.","외래부와 병동부 사이에 두되, 다른 부문의 통과교통이 없는 장소에 배치합니다":"수술부는 외래부와 병동부 사이에 놓되 다른 부문 사람이 지나다니지 않는 곳에 둡니다.","외래부와 병동부의 중간에 둡니다. 구급동선도 중앙진료부에 연결합니다":"중앙진료부는 외래부와 병동부 사이에 놓고 구급 동선도 여기에 이어 줍니다.","외래환자와 입원환자가 모두 이용합니다":"부속진료부는 외래 환자와 입원 환자가 함께 이용하는 진료 부분입니다.","외벽 중심선으로 둘러싸인 부분의 수평투영면적이다":"건축면적은 외벽 중심선으로 둘러싸인 부분을 위에서 본 수평투영면적으로 잽니다.","외부적 응력에 대한 전선 보호의 신뢰성도 높으며, 400V 미만의 노출되고 습기가 많은 장소에서도 쓸 수 있습니다":"금속관은 외부 응력에서 전선을 믿을 만하게 보호하고 400V 미만의 습기 많은 노출 장소에서도 쓸 수 있습니다.","욕실·화장실·부엌의 배관은 집중하고, 부엌은 유틸리티룸과 식당에 직접 연결합니다":"욕실, 화장실, 부엌 배관은 한곳에 모으고 부엌은 유틸리티룸과 식당에 직접 잇습니다.","용도변경은 출발 용도와 도착 용도의 시설군을 먼저 찾습니다":"용도변경을 풀 때는 바꾸기 전 용도와 바꾼 후 용도가 각각 어느 시설군인지부터 찾습니다.","용도 외에 함께 설치할 수 있는지와 지역 안에서 건축할 수 있는지를 따집니다":"용도 배치 기준은 함께 설치할 수 있는지와 지역 안에서 지을 수 있는지를 따로 봅니다.","용도 이름보다 시설군 위치를 먼저 표시합니다":"용도 이름이 아니라 그 용도가 속한 시설군이 어디인지를 먼저 적어 방향을 판단합니다.","용도지역·용도지구의 지정 또는 변경은 도시·군관리계획에 포함됩니다":"용도지역·용도지구를 지정하거나 바꾸는 일은 도시·군관리계획에 속합니다.","용수량 많은 깊은기초 구축용이나 터파기 공법의 일종은 아니다":"언더피닝은 용수량이 많은 깊은기초를 만드는 용도가 아니며 터파기 공법의 일종도 아닙니다.","용접구조용 압연강재(KS D 3515)이다":"SM은 용접구조용 압연강재(KS D 3515)를 가리킵니다.","우리나라에서는 입시학원이나 사설 외국어학원에서 사용됩니다":"달톤형은 우리나라에서 입시학원이나 외국어 사설학원에서 볼 수 있습니다.","운동장, 납골시설·봉안시설, 수질오염방지시설은 광역시설에 속합니다":"광역시설의 예로 운동장, 납골·봉안시설, 수질오염방지시설을 듭니다.","운수시설·창고시설·장례식장·묘지관련시설·자원순환관련시설은 속합니다":"운수시설, 창고시설, 장례식장, 묘지관련시설, 자원순환관련시설은 산업 등의 시설군에 속합니다.","운전정지 중 동결 위험이 있고":"온수난방은 운전을 멈춘 동안 물이 어는 위험이 있습니다.","운전 중 생겨 소음을 일으키기 쉽습니다":"스팀 해머는 증기관 속 응축수가 증기에 밀려 관을 치면서 쿵쿵 소리를 내는 현상입니다.","운전 중 장치 압력과 온수온도를 유지하고, 팽창수 배출을 막아 열손실을 방지합니다":"팽창탱크는 압력과 온도를 일정하게 두고 넘치는 물이 밖으로 나가 열을 잃는 것도 막습니다.","운하·방수설비·방풍설비·사방설비·공동구는 공공시설 쪽이고, 폐차장·쓰레기 처리장은 아닙니다":"공공시설로 보는 것은 운하와 각종 방재설비, 공동구이며 폐차장·쓰레기 처리장은 제외입니다.","원합리주의와 ‘장식은 죄악이다.’":"아돌프 로스는 원합리주의와 장식은 죄악이다라는 말로 대표됩니다.","위생성이 가장 좋지도 않고 수압 변화가 심하지도 않습니다":"고가수조방식이 위생성이 가장 좋다거나 수압 변화가 심하다고 하면 틀립니다.","위원장·부위원장 각 1인 포함 25인 이상 30인 이내이다":"중앙도시계획위원회는 위원장과 부위원장 각 1인을 포함해 25인 이상 30인 이내로 구성합니다.","위원장은 부시장 또는 부지사이고 부위원장은 호선한다":"시·도 도시계획위원회의 위원장은 부시장이나 부지사이고 부위원장은 위원이 호선합니다.","위쪽 배광이 압도적이면 간접이나 반간접":"위쪽 배광이 압도적으로 많으면 간접이나 반간접 조명으로 분류합니다.","위치를 1개소로 한정하는 것이 효율적입니다":"엘리베이터 위치를 1개소로 한정하는 것이 운영면에서 효율적입니다.","윗층 배수가 수직관을 급속히 흐르며 하층 기구 유출관 쪽 공기를 감압시켜 봉수를 흡인하면 유도사이폰입니다":"윗층 배수가 수직관을 빠르게 흐르면 아래층 기구 쪽 공기가 감압되어 봉수가 빨려 나가는 것이 유도사이폰입니다.","유스호스텔은 숙박시설이 아니라 수련시설입니다":"유스호스텔은 숙박하는 곳 같지만 법 분류로는 수련시설입니다.","유효건물중량은 밑면전단력 산정인자이지만 지진응답계수 Cs를 구성하는 항목은 아닙니다":"유효건물중량은 밑면전단력을 구하는 인자지만 지진응답계수 Cs를 이루는 요소는 아닙니다.","유효길이를 단면2차반경으로 나눕니다":"세장비는 유효길이를 단면2차반경으로 나눈 값입니다.","유효너비 0.75m 이상, 유효높이 1.5m 이상입니다":"비상탈출구는 유효너비 0.75m 이상, 유효높이 1.5m 이상이어야 합니다.","유효너비는 0.9m 이상이고 피난 방향으로 열며, 0.85m나 피난 반대방향은 기준에 맞지 않습니다":"특별피난계단 출입구는 유효너비 0.9m 이상에 피난 방향으로 열어야 하며 0.85m나 반대 방향은 안 됩니다.","유효면적률을 높이고 설비 계통 거리가 최단":"코어를 두면 유효면적률이 높아지고 설비 계통 거리가 가장 짧아집니다.","유효면적은 유효길이와 유효목두께를 곱합니다":"모살용접의 유효면적은 유효길이에 유효목두께를 곱한 값입니다.","유효목두께는 모살사이즈 s의 0.7배입니다":"유효목두께는 모살사이즈에 상수 0.7을 곱해 정합니다.","유효율이 높은 계획이 가능하지만 외관은 획일적으로 되기 쉽습니다":"중심코어는 유효율을 높일 수 있지만 건물 모양이 획일적이기 쉽습니다.","유흥주점으로 쓰는 층의 거실 바닥면적 합계가 50m² 이상이면 직통계단을 2개소 이상 설치합니다":"유흥주점 층은 거실 합계 50m² 이상부터 직통계단을 이중으로 확보해야 합니다.","음수가 나오면 크기뿐 아니라 부호까지 구합니다":"음수가 나오면 크기뿐 아니라 부호까지 함께 답에 적습니다.","응력중심간 거리는 d-a/2입니다":"응력중심간 거리는 d에서 a의 절반을 뺀 d-a/2입니다.","의료시설과 숙박시설은 해당하지 않습니다":"의료시설과 숙박시설은 주차전용건축물에 함께 둘 수 있는 용도가 아닙니다.","의료시설·수련시설·노유자시설이 들어가고 종교시설은 들어가지 않습니다":"교육 및 복지시설군에는 의료시설, 수련시설, 노유자시설이 속하고 종교시설은 속하지 않습니다.","의료시설 중 요양병원을 건축할 수 있습니다":"일반상업지역에는 의료시설 중 요양병원을 지을 수 있습니다.","의사결정을 위한 프로젝트 정보관리시스템이다":"PMIS는 의사결정을 돕는 프로젝트 정보관리시스템입니다.","의사소통이 잘되나 공사 전체관리가 곤란":"전문공종별 분할도급은 업체와 의사소통이 잘되지만 공사 전체를 관리하기 어렵습니다.","의사전달과 실제 작업 흐름을 기준으로 작업 집단을 자유롭게 그루핑하여 불규칙한 평면을 만듭니다":"작업 집단을 의사전달과 실제 작업 흐름에 따라 자유롭게 묶어 불규칙한 평면을 만듭니다.","이 기준으로 나머지 상태값의 방향이 정해집니다":"절대습도가 그대로라는 기준으로 나머지 상태값이 어느 쪽으로 움직이는지 정해집니다.","이 네 항목에 들어가지 않습니다":"일반관리비와 이윤은 직접공사비의 네 항목에 들어가지 않습니다.","이들이 설치하는 노외주차장은 주차대수 50대마다 장애인 전용주차구획 1면을 둡니다":"장애인 전용주차구획은 주차대수 50대마다 한 면씩 더 확보해야 합니다.","이때의 As/(bd)가 균형철근비 ρb입니다":"이 상태의 철근비 As/(bd)를 균형철근비 ρb라고 부릅니다.","이 문항의 48m³를 일반 기준으로 확대하지 않습니다":"이 문항에서 나온 48m³를 일반 기준으로 삼으면 안 됩니다.","이 보 공식을 쓰지 않습니다. 400mm×400mm 단면에 D22 한 가닥이 387mm²이면 최소 5개입니다":"기둥은 보 공식으로 구하지 않으며 400mm×400mm에서 D22 한 가닥이 387mm²이면 최소 5개를 둡니다.","이 설명은 관리도가 아닙니다":"이 설명은 관리도가 아니라 산점도의 설명입니다.","이 순서로 구하면 2004년 2.26cm, 2018년 23.7mm, 2017년 39.2mm가 나옵니다":"이 순서로 계산하면 연도별 문제 답이 2.26cm, 23.7mm, 39.2mm로 맞아떨어집니다.","이 순서로 허가와 신고가 갈립니다":"이 배열 순서에서 위쪽으로 가는지 아래로 가는지에 따라 허가인지 신고인지가 갈립니다.","이어붓기는 전단력이 가장 적은 스팬 중앙부에서 수직으로 하며, 단부는 아니다":"보를 이어붓는 자리는 전단력이 가장 작은 스팬 중앙이며 이음 면은 수직이고 단부는 피합니다.","이 용도들이 6층 이상 건축물의 피난층이 아닌 거실이면 설치 대상입니다":"배연설비 용도에 드는 건축물이 6층 이상이면 피난층이 아닌 거실에 설치해야 합니다.","이용자 수는 아침 출근 시 5분간으로 산정하고, 방향은 출근 시 상승입니다":"출근 때 5분 동안 몰리는 이용자 수로 산정하며 방향은 위로 올라가는 상승입니다.","이윤＝공사원가×이윤율과 고용보험료＝재료비×고용보험요율은 맞지 않는 식입니다":"이윤을 공사원가에 이윤율을 곱하거나 고용보험료를 재료비에 요율을 곱한다는 식은 맞지 않습니다.","이중(복층) 유리로 단열성능을 높이고":"표면결로를 막으려면 이중(복층) 유리로 단열성능을 높입니다.","이형철근이 원형철근보다 부착강도가 크고 피복두께가 크면 부착강도가 크다":"이형철근은 표면 마디 덕에 원형철근보다 잘 붙고 피복이 두꺼울수록 부착이 강해집니다.","인동간격을 넓혀 저층부 일사 수열량을 늘리고, 남향 또는 남동향으로 배치하며, 기능에 지장이 없으면 층고와 반자 높이를 낮춥니다":"공동주택은 인동간격을 넓혀 저층부 일사를 늘리고 남향 또는 남동향으로 놓으며 가능하면 층고를 낮춥니다.","인장철근비가 ρb보다 작아지면 중립축은 압축측으로 이동합니다":"철근비가 ρb보다 줄면 중립축이 압축측으로 올라갑니다.","인장철근의 힘과 콘크리트 압축력이 같아야 합니다":"인장철근이 내는 힘과 콘크리트 압축력이 같아야 단면이 평형을 이룹니다.","인접 대지의 우물이 고갈될 우려도 있습니다":"물을 빼는 과정에서 인접 대지의 우물이 고갈될 우려도 있습니다.","인접지반과 공동매설물이 침하할 수 있습니다":"주변 땅이 내려앉으면 이웃 지반과 공동 매설물도 같이 가라앉을 수 있습니다.","인체·극간풍·외기 도입은 현열과 잠열을 모두 봅니다":"인체, 극간풍, 외기에서 들어오는 열은 현열과 잠열을 함께 따집니다.","인체·조명 같은 내부발생열이 난방부하를 줄이므로 일반적으로 계산하지 않습니다":"인체와 조명이 내는 내부 발생열은 난방부하를 줄여 주므로 보통 넣지 않고 계산합니다.","일량을 시간당 부하처럼 바로 계산하면 안 됩니다":"하루치 일량을 시간당 부하인 양 그대로 쓰면 틀립니다.","일반 건축물 피뢰침 보호각은 60° 이하이고 높이 20m 이상 건축물에 설치한다":"높이 20m 이상 건축물에는 피뢰침을 달고 일반 건축물의 보호각은 60° 이하로 둡니다.","일반관리비＝공사원가×일반관리비율은 맞습니다":"일반관리비는 공사원가에 일반관리비율을 곱해 구하는 식이 맞습니다.","일반교실과 특별교실을 함께 쓰는 방식입니다":"일반·특별교실형은 일반교실과 특별교실을 함께 쓰는 방식입니다.","일반교실 이용률은 가장 높지만 순수율은 낮습니다":"종합교실형은 일반교실을 가장 자주 쓰지만 한 과목 전용 비율인 순수율은 낮습니다.","일반교실·특별교실형(U＋V형) 운영이 일반적이다":"초등학교 고학년은 일반교실·특별교실형(U＋V형) 운영이 일반적입니다.","일반 단일덕트방식은 각 실이나 존의 부하변동에 즉시 대응하기 어렵고, 부하특성이 다른 여러 실에 적용하기 곤란합니다":"일반 단일덕트는 한 계통으로 보내므로 방마다 달라지는 부하를 즉시 따르기 어렵습니다.","일반적으로 고밀도의 고층형입니다":"시티 호텔과 커머셜 호텔은 일반적으로 고밀도의 고층형입니다.","일반주거·준주거·상업·준공업지역이다":"공개공지 확보 대상 지역은 일반주거, 준주거, 상업, 준공업지역입니다.","일반주거지역, 준주거지역, 준공업지역입니다":"공개공지를 두어야 하는 곳은 일반·준주거지역과 준공업지역입니다.","일산화탄소를 함유하지 않고 발열량이 도시가스·LNG보다 크다":"LPG는 일산화탄소가 없는 가스이고 같은 양을 태우면 도시가스·LNG보다 열을 많이 냅니다.","일정 온도 이상에서 작동하며 보일러실 등에 쓴다":"정온식 감지기는 일정 온도 이상에서 작동하며 보일러실 등에 씁니다.","일정 이상 속도에서 브레이크 등을 작동시키는 장치이므로 작동 조건이 다릅니다":"조속기는 속도가 일정 이상이 될 때 작동하므로 전동기 정지 때 쓰는 브레이크와 조건이 다릅니다.","일정한 교과가 끝나면 졸업하며, 규모와 시설이 다른 다양한 교실이 요구됩니다":"달톤형은 학생이 교과를 마치면 졸업하는 구조라 크기와 시설이 제각각인 교실이 필요합니다.","일정한 기하학적 패턴에 맞추는 방식이 아닙니다":"오피스 랜드스케이핑의 책상은 일정한 기하학적 패턴에 맞추는 방식이 아닙니다.","일정한 온도 상승률 이상에서 작동한다":"차동식 감지기는 일정한 온도 상승률 이상에서 작동합니다.","일주시간을 줄여 수송능력을 높입니다":"죠닝을 하면 일주시간이 줄어 수송능력이 높아집니다.","입원환자의 병상수를 기준으로 결정합니다":"병원의 시설 규모는 입원 환자를 눕힐 병상 수로 정합니다.","입자가 분리되지 않게 하고, 보관 장소는 물빠짐이 좋고 햇볕을 덜 받는 곳으로 잡습니다":"경량골재는 입자가 분리되지 않게 쌓고 물빠짐이 좋고 햇볕을 덜 받는 곳에 보관합니다.","입찰·계약·원가관리와 현장 조직·공정관리 업무도 CM 업무이다":"CM 업무에는 입찰·계약·원가관리와 현장 조직·공정관리가 들어갑니다.","자격과 업무범위는 국토교통부령으로 정하는 것이 아닙니다":"건축지도원의 자격과 업무범위는 국토교통부령이 아니라 다른 규정으로 정한다는 뜻입니다.","자금부담이 줄고 위험이 분산":"공동도급은 자금 부담이 줄고 위험이 분산되는 장점이 있습니다.","자기질·석기질이 쓰이며, 흡수성이 큰 것은 적합하지 않습니다":"외장타일은 자기질과 석기질을 쓰며 흡수성이 큰 것은 적합하지 않습니다.","자동차 관련 시설군 → 산업 등의 시설군 → 전기통신시설군 → 문화 및 집회시설군 → 영업시설군 → 교육 및 복지시설군 → 근린생활시설군 → 주거업무시설군 순으로 놓습니다":"시설군은 자동차 관련부터 주거업무까지 정해진 여덟 단계로 늘어놓아 위치를 비교합니다.","자동차관련시설이나 문화 및 집회시설을 함께 두는 경우":"주차장 외에 자동차관련시설이나 문화 및 집회시설을 함께 두는 건축물도 있다는 조건입니다.","자동차용 승강기로 운반된 자동차가 주차구획까지 자주식으로 들어가는 노외주차장이 전제입니다":"이 규정은 승강기로 차를 올린 뒤 주차구획까지 스스로 운전해 가는 자주식 노외주차장이 대상입니다.","자연채광만으로 끝나는 형식도 아니며, 기본적인 자연채광에 인공조명이 필요합니다":"개방식은 자연채광만으로 끝나지 않고 기본 자연채광에 인공조명을 더해야 합니다.","자재조달과 시공도 작성은 CM 주요업무가 아니다":"자재조달과 시공도 작성은 CM이 맡는 주요업무 목록에 들어 있지 않습니다.","자주식과 기계식은 서로 구분되는 주차장 종류이다":"자주식 주차장과 기계식 주차장은 서로 겹치지 않는 별개의 종류입니다.","자주식 형태에 속하지 않는다":"기계식은 자주식 주차장의 형태에 속하지 않습니다.","작고 프라이버시·일조·통풍이 좋습니다":"홀형은 통행부가 작고 프라이버시, 일조, 통풍이 좋습니다.","작업과 작업을 결합하는 점이며 프로젝트의 개시점이나 종료점이 됩니다":"Event는 작업들이 서로 만나는 점이며 프로젝트가 시작하거나 끝나는 지점도 됩니다.","작업단위별 그룹 배치와 연결의 용이성이 특징입니다":"오피스 랜드스케이핑은 작업단위별 그룹 배치와 연결의 용이성이 특징입니다.","작업 자체이며, 작업을 수행하는 데 필요한 시간은 아닙니다":"Activity는 작업 자체이며 작업에 필요한 시간이 아닙니다.","작은 부재를 매번 조립·분해하지 않고 벽체 거푸집을 대형화·단순화해 한 번에 설치하고 해체하는 방식입니다":"갱폼은 벽체 거푸집을 크게 한 덩어리로 만들어 한 번에 세우고 떼므로 작은 부재를 계속 조립하지 않습니다.","작은 부지에서도 효율적이고 대지 이용률이 높습니다":"중앙홀 형식은 좁은 부지에서도 효율이 좋아 대지를 알뜰히 씁니다.","작은 지름이 20cm이면 내화구조가 아니다":"철근콘크리트조 기둥은 작은 지름이 20cm이면 내화구조로 보지 않습니다.","잔골재 입도의 영향을 크게 받고, 굵은골재 최대치수나 단위시멘트량이 커지면 감소합니다":"공기량은 잔골재 입도에 크게 좌우되고 굵은골재 최대치수나 단위시멘트량이 커지면 줄어듭니다.","잔류유를 저온으로 장시간 증류하여 만들고, 응집력이 크며 온도 변화가 적고 연화점이 높은 것입니다":"잔류유를 낮은 온도로 오래 증류해 만든 아스팔트는 응집력이 크고 온도 변화가 적으며 연화점이 높습니다.","장기간 대기에 노출되면 산화하고 염류나 가스에 부식되기 쉽습니다":"금속판 지붕을 오래 바깥 공기에 두면 산화하고 염류나 가스에 부식되기 쉽습니다.","장기간 사용하지 않은 곳은 압력보다 증발이 원인입니다":"감압으로 봉수가 줄었다기보다 장기간 쓰지 않은 곳은 증발이 원인입니다.","장기간 체재에 적합하지만, 각 객실에 주방 설비를 갖추지는 않습니다":"레지덴셜 호텔은 오래 머물기에 맞지만 객실마다 주방을 갖추지는 않습니다.","장래 공장규모의 변화에 대응할 융통성이 있어야 합니다":"공장 규모가 앞으로 바뀔 수 있으니 레이아웃에 변화를 받아들일 여유를 둬야 합니다.","장례식장·마약진료소·치과병원·한방병원은 의료시설입니다":"장례식장, 마약진료소, 치과병원, 한방병원은 용도 분류상 모두 의료시설에 듭니다.","장변경간과 단변경간의 비는 2 이하":"직접설계법은 장변경간과 단변경간의 비가 2 이하일 때 적용합니다.","장변보다 단변방향에 많이 넣는다":"슬래브 철근은 장변 방향보다 단변 방향에 더 많이 넣습니다.","장스팬에 적합하고 철근콘크리트조보다 넓은 전용면적을 얻을 수 있으며 정밀한 시공을 요구합니다":"철골구조는 장스팬에 적합하고 철근콘크리트조보다 전용면적을 넓게 얻지만 정밀한 시공이 필요합니다.","장애인 전용구획을 1면 이상 둔다":"주차 규모가 크면 장애인이 쓰는 전용구획을 한 면 이상 따로 마련합니다.","재료단가·노무단가·복합단가·합성단가이다":"형태별 단가에는 재료단가, 노무단가, 복합단가, 합성단가가 있습니다.","재료 두께·공기층 열저항·재료 열전도율을 보며 실내복사열은 고려하지 않습니다":"열관류율은 재료의 두께, 공기층 열저항, 열전도율을 보며 실내복사열은 따지지 않습니다.","재료비·외주비·콘크리트 공사비로 보내지 않습니다":"공사용수비를 재료비, 외주비, 콘크리트 공사비로 보내지 않습니다.","재생기는 압축식의 구성요소가 아니다":"압축식 냉동기에는 재생기가 없고 재생기는 흡수식 냉동기에 있는 부품입니다.","재적위원 과반수 출석으로 개의하고 출석위원 과반수 찬성으로 의결한다":"위원회 회의는 재적위원 과반수가 모여야 열리고 출석위원 과반수가 찬성해야 의결됩니다.","재질이 약해 고압용으로 쓰기 곤란하고, 비교적 작은 건물의 난방용입니다":"주철제 보일러는 재질이 약해 높은 압력에 견디지 못하므로 비교적 작은 건물 난방에 씁니다.","저압보일러를 써도 되는 경우가 많고 난방용 보일러와 겸용할 수 있으며, 직접가열식보다 보일러 내면의 스케일 염려가 적습니다":"간접가열식은 저압보일러로 되는 때가 많고 난방보일러와 겸용하며 직접가열식보다 보일러 내면 스케일이 덜 생깁니다.","저온·다습하고 환기가 충분하지 못한 장소도 작업을 금지합니다":"저온이고 습하며 환기가 충분하지 않은 곳에서도 도장 작업을 금지합니다.","저온발생기와 고온발생기로 구성됩니다":"이중효용은 발생기를 저온과 고온 두 단으로 나누어 구성한 흡수식 방식입니다.","적절한 대수분할과 압력제어로 에너지를 절약할 수 있지만, 자동제어 설비비가 적지 않고 유지관리가 간단하지도 않습니다":"펌프직송은 펌프 대수를 나누고 압력을 제어해 에너지를 아끼지만 자동제어 설비비가 들고 유지관리도 간단하지 않습니다.","전기음향·감시제어·주차관제설비도 약전(소세력)에 속한다":"소세력이라고도 부르는 약전 설비에는 전기음향, 감시제어, 주차관제설비가 듭니다.","전단강도·점착력은 베인테스트로 측정합니다":"연한 점토나 연약점토의 전단강도와 점착력은 베인테스트로 잽니다.","전단력 100kgf이면 평균은 10kgf/cm², 최대는 15kgf/cm²입니다":"전단력 100kgf를 10cm²로 나눈 평균은 10kgf/cm²이고 단면 계수를 곱한 최대는 15kgf/cm²입니다.","전단력 V를 전단에 저항하는 면적 A로 나누고, N/mm²가 MPa가 되도록 단위를 먼저 맞춥니다":"N/mm²가 MPa로 나오도록 단위를 먼저 맞춘 뒤 전단력 V를 저항 면적 A로 나눕니다.","전단력과 인장력이 함께 작용하면":"전단력과 인장력이 함께 작용하는 경우를 따로 봅니다.","전단력과 휨모멘트 모두 지점반력을 넣어야 맞습니다":"전단력과 휨모멘트를 구할 때 모두 지점반력을 넣어야 맞는 값이 나옵니다.","전단력도에서 두 단면 사이의 부호 있는 면적은 그 사이 휨모멘트의 변화량입니다":"전단력도에서 두 지점 사이에 부호를 붙여 잰 넓이가 그 구간에서 휨모멘트가 변한 양입니다.","전단력을 찾은 뒤 문제의 단면 그림에 맞는 응력 계산까지 합니다":"전단력 위치를 찾은 뒤엔 문제의 단면 모양에 맞는 응력식까지 이어서 계산합니다.","전단력의 절대값이 가장 큰 단면을 찾습니다":"최대 전단응력은 전단력의 절대값이 가장 큰 단면에서 찾습니다.","전단력이 바뀌므로, 그 점 전후의 기울기 차이로 힘의 절대값을 찾습니다":"집중력이 걸린 점에서는 전단력이 바뀌므로 그 점 앞뒤 기울기 차이로 힘의 절대값을 찾습니다.","전동기가 회전을 정지하면 스프링의 힘으로 브레이크 드럼을 눌러 엘리베이터를 정지시키는 장치입니다":"전동기가 멈추면 스프링이 브레이크 드럼을 눌러 엘리베이터를 잡아 세우는 장치입니다.","전동기 정지는 전자 브레이크":"전동기가 멈출 때 카를 붙들어 두는 장치는 전자 브레이크라는 짝짓기입니다.","전동기 펌프 가압송수장치의 펌프는 전용으로 하는 것이 원칙이다":"소화전 펌프는 다른 설비와 나눠 쓰지 않고 소화전만을 위한 전용으로 둡니다.","전등·조명설비는 약전이 아니다":"전등과 조명설비는 큰 전력을 쓰는 강전 쪽이라 약전 설비로 보지 않습니다.","전력 차단 시 급수가 불가능하며 정교한 제어장치와 내구성 있는 제품이 필요합니다":"펌프직송방식은 전력이 끊기면 급수가 불가능하고 정교한 제어장치와 내구성 있는 제품이 필요합니다.","전반적 타당성 재검토·정비 기준은 5년입니다":"도시·군기본계획은 전반적 타당성을 5년마다 재검토해 정비합니다.","전선 굵기는 허용전류로 정한다":"전선 굵기는 흐를 수 있는 전류, 곧 허용전류를 기준으로 정합니다.","전시실이 연속적으로 동선을 만들기 때문에 많은 실을 순서대로 통과합니다":"연속순로는 전시실이 이어져 동선을 만들기 때문에 많은 실을 순서대로 통과합니다.","전시장과 동·식물원을 제외한 경우에는 옥내 관람석 또는 집회실 300㎡가 기준입니다":"전시장과 동·식물원을 뺀 문화 및 집회시설은 옥내 관람석이나 집회실 300㎡가 기준입니다.","전열교환기로 배열을 회수하고 존별 온도제어를 한다":"전열교환기로 배열을 회수하고 존별로 온도를 제어하면 공조 에너지를 줄입니다.","전열부하와 일사에 의한 부하 등을 말합니다":"냉방 실부하에는 전열부하와 일사부하 등이 들어갑니다.","전용으로 하며 다른 목적의 배관을 두지 않고":"상수용 저수조는 전용으로 하며 다른 목적의 배관을 두지 않습니다.","전용주거·전용공업·일반공업지역은 대상이 아니다":"전용주거, 전용공업, 일반공업지역은 공개공지 확보 대상 지역이 아닙니다.","전체 광속을 F로 놓으면 E=F×U×M/A이고, 20개와 3300lm을 넣습니다":"평균조도는 E=F×U×M/A이며 전체 광속 F에 20개와 3300lm을 넣어 구합니다.","전체적으로 균일한 조도를 얻을 수 있다":"전반조명은 방 전체에 균일한 조도를 얻을 수 있는 방식입니다.","전체 정원 합계의 50% 정도를 수용하도록 봅니다":"엘리베이터 홀은 전체 정원 합계의 50% 정도가 서 있을 크기로 잡습니다.","전 학급을 2분단으로 나눕니다":"플래툰형은 학급 전체를 두 분단으로 갈라 교대로 운영합니다.","전화·인터폰·TV공청설비가 속한다":"통신설비에는 전화, 인터폰, TV공청설비가 속합니다.","절단모양이 자유롭고 설비가 간단하나 절단면이 거칠고 3mm 정도 변질된다":"가스절단은 모양을 마음대로 낼 수 있고 장비가 단순하지만 절단면이 거칠어지고 3mm 정도 성질이 변합니다.","절대습도의 변화 없이 건구온도만 올리는 경우입니다":"습공기 가열은 수증기 양은 그대로 두고 건구온도만 올리는 변화입니다.","절대 최대를 묻거나 두 값이 같다고 하면 부호가 아니라 크기를 비교합니다":"절대 최대나 두 값이 같다는 조건에서는 부호를 빼고 크기끼리 비교합니다.","절약하고 효율적으로 이용하며 사무능률 향상을 도모합니다":"공간을 아끼며 효율적으로 쓰게 하여 사무 능률을 높이려는 방식입니다.","절점을 떼어 보면 외부 절점모멘트가 없는 경우 연결 부재 끝모멘트들이 서로 평형을 이룹니다":"절점을 오려 보면 바깥 절점모멘트가 없을 때 이어진 부재 끝모멘트들이 서로 균형을 이룹니다.","점 이름으로 판단하지 말고 그림의 지지·연결 표시로 판단합니다":"점 이름이 아니라 그림에 그려진 지지와 연결 표시를 보고 판단합니다.","점조도가 교란되며 받는 영향은 예민비로 나타낸다":"흙이 교란될 때 점조도가 받는 영향은 예민비로 나타냅니다.","점토지반에서도 표준관입시험이 불가능하지는 않습니다":"점토지반이라도 표준관입시험을 할 수 없는 것은 아닙니다.","점토지반에서 함수비가 크면 접착력이 증가하는 것은 아니다":"점토지반의 함수비가 커진다고 흙입자 사이 접착력이 늘어나는 것은 아닙니다.","접속 배수관의 1/2 이상입니다":"각개통기관 관경은 접속 배수관의 1/2 이상입니다.","접착제와 프린트 배선판입니다":"에폭시는 접착제와 프린트 배선판에 쓰입니다.","접합면의 마찰로 힘을 전달합니다":"고력볼트 마찰접합은 접합면의 마찰로 힘을 전달합니다.","접합부의 강성과 강도가 크고, 수직방향 변형이 거의 없으며, 피로강도와 볼트의 단위 강도가 높습니다":"마찰접합은 강성과 강도가 높고 수직 변형이 거의 없으며 피로에 강합니다.","정기·수시점검의 항목별 점검은 하지 않습니다":"정기·수시점검에서 항목별로 점검하는 일은 민원실이 하지 않습니다.","정비구역·관광특구·기반시설부담구역 등에서 지정":"정비구역, 관광특구, 기반시설부담구역 등 개발이 필요한 곳에 지구단위계획구역을 지정합니다.","정상상태에서 감열체가 방수구를 막고 있다가 일정 온도에서 파괴·용해 또는 이탈하여 열립니다":"폐쇄형 헤드는 평소에는 감열체가 방수구를 막고 있다가 일정 온도에서 터지거나 녹거나 떨어지면서 열립니다.","정원 기준입니다. 정원 20인당 1대는 기준이 아닙니다":"옥외수영장은 정원이 기준이며 정원 20인당 한 대는 기준이 아닙니다.","정의와는 목적 문구가 다릅니다":"입지규제최소구역의 정의와 지구단위계획의 목적 문구는 서로 다릅니다.","정전 시 급수가 곤란하거나 불가능하고, 급수압력이 항상 일정하지도 않습니다":"압력수조방식은 정전되면 급수하기 어렵고 급수압력도 늘 일정하지는 않습니다.","정지·구체·마무리 등 과정별로 나눠 줌":"공정별 분할도급은 정지, 구체, 마무리 같은 과정별로 나눠 업체에 맡깁니다.","제1종 근린생활시설, 제2종 근린생활시설, 의료시설 어느 쪽으로도 단정하지 않으며, 연도와 개정 적용 여부에 따라 달라집니다":"동물병원의 용도는 연도와 개정 적용 여부에 따라 달라지므로 어느 하나로 단정하지 않습니다.","제1종 근린생활시설과 문화 및 집회시설 중 전시장도 가능합니다":"이 지역에는 근린생활시설과 문화 및 집회시설 중 전시장을 지을 수 있습니다.","제1종 근린생활시설 연결이 아닙니다":"일반음식점이 제1종 근린생활시설에 속한다고 연결하면 틀립니다.","제1종 일반주거지역에는 아파트를 지을 수 없습니다":"아파트는 제1종 일반주거지역에 지을 수 있는 용도가 아닙니다.","제1종 전용주거지역·제1종 일반주거지역·자연녹지지역은 불가입니다":"제1종 전용주거지역, 제1종 일반주거지역, 자연녹지지역은 아파트를 지을 수 없습니다.","제2종 전용주거지역·제2종 일반주거지역·제3종 일반주거지역·준주거지역입니다":"아파트를 지을 수 있는 곳은 제2종 전용주거, 제2종·제3종 일반주거, 준주거지역입니다.","제시된 시설 중 근린주구 이론의 기초가 아닌 것입니다":"파출소는 보기로 주어진 시설 가운데 근린주구 이론이 기초로 삼지 않는 것입니다.","제연설비, 연결송수관설비, 연결살수설비, 비상콘센트설비가 들어간다":"연결송수관, 연결살수, 제연, 비상콘센트 설비는 소화 활동을 돕는 소화활동설비로 분류합니다.","제품 또는 조립부품이 고정된 장소에 있고 사람과 기계가 이동하며 작업합니다":"고정식 레이아웃은 제품이나 부품은 자리에 두고 사람과 기계가 움직이며 일합니다.","조경면적(2007년), 건축선(2018년)입니다":"조경면적(2007년)과 건축선(2018년)은 지구단위계획으로 완화할 수 없는 항목입니다.","조기강도가 커서 한중콘크리트에 씀":"조강 포틀랜드시멘트는 조기강도가 커서 한중콘크리트에 씁니다.","조명률 0.5와 보수율 0.76도 곱합니다. 면적 50m²로 나누면 501.6lx(약 500lx)입니다":"조명률 0.5, 보수율 0.76을 곱하고 50m²로 나누면 약 500lx(501.6lx)입니다.","조명률이 0.6에서 0.7로 올라가면 개선 전과 개선 후의 수량을 따로 구해 뺍니다":"조명률이 0.6에서 0.7로 오르면 개선 전과 후 필요 수량을 각각 구해 차이를 냅니다.","조선소처럼 제품이 크고 수량이 적을 때 적용됩니다":"조선소처럼 제품이 크고 만드는 수가 적을 때 고정식 레이아웃을 씁니다.","종방향 철근지름의 16배, 띠철근 지름의 48배, 단면 최소 치수 이하이다":"띠철근 간격은 종방향 철근지름의 16배, 띠철근 지름의 48배, 단면 최소 치수 세 값을 모두 넘지 않게 합니다.","좋다는 사실을 소규모 임대 적합성과 같은 말로 연결하지 않습니다":"공간 효율이 좋다는 장점과 소규모 임대에 적합하다는 말은 별개입니다.","좌굴하중은 E와 I에 비례하고 길이의 제곱에 반비례하며, 세장비는 유효좌굴길이·단면적·I로 구하므로 E는 필요하지 않습니다":"양단 단순지지 기둥의 좌굴하중은 E와 I에 비례하고 길이 제곱에 반비례하며 세장비 계산에는 E가 필요하지 않습니다.","주거 70%, 상업 90%, 공업 70% 이하이다":"건폐율 최대한도는 주거 70%, 상업 90%, 공업 70% 이하입니다.","주거기능을 위주로 일부 상업기능과 업무기능을 보완하면 준주거지역입니다":"주거기능이 중심이고 일부 상업·업무기능을 보완하는 지역이 준주거지역입니다.","주거단위의 단면을 같은 층에 맞추지 않고 반 층씩 엇나게 구성합니다":"스킵플로어형은 한 세대의 단면을 반 층씩 엇갈리게 쌓는 방식입니다.","주거시설·아파트·종교시설은 기반시설이 아닙니다":"주거시설, 아파트, 종교시설은 법에서 말하는 기반시설에 들지 않습니다.","주근의 위치를 유지하고 좌굴을 방지하며 수평력에 전단보강을 한다":"띠철근은 주근의 위치를 유지하고 좌굴을 막으며 수평력에 대한 전단보강 구실을 합니다.","주근의 중심이 아니라 철근 표면에서 콘크리트 표면까지의 최단거리로 봅니다":"피복두께는 철근 중심이 아니라 철근 표면에서 콘크리트 표면까지 가장 가까운 거리로 잽니다.","주내력벽 구조체로서 내진벽 역할을 하고 설비시설을 집중시킵니다":"코어는 구조체가 되는 주내력벽으로서 지진에 견디는 내진벽 구실을 하며 설비시설을 한곳에 모읍니다.","주도로와 연결해 통과도로로 만들지 않습니다":"보조 도로인 이차 도로를 주도로와 이어 통과 도로로 만들면 안 됩니다.","주로 목재로 뼈대를 조립한 가구식 구조입니다":"목구조는 목재로 뼈대를 짜 맞춘 가구식 구조가 주를 이룹니다.","주민에게 서비스를 제공하는 1~2개소 이상의 상점가를 주요 도로의 결절점에 배치합니다":"주민 서비스를 맡는 상점가는 1~2개소 이상으로 하고 주요 도로가 만나는 결절점에 놓습니다.","주민의 일상생활 요구를 충족하는 소공원과 위락공간의 체계입니다":"오픈 스페이스는 주민의 일상생활 요구를 채우는 소공원과 위락공간의 체계입니다.","주민이 상점과 공공시설을 걸어서 이용할 수 있도록 약 400m로 설정합니다":"근린주구 크기는 걸어서 상점과 공공시설을 이용할 수 있게 약 400m 거리로 설정합니다.","주벽 각부의 효과를 평균한 값이다":"평균복사온도는 주변 벽면 각 부분의 복사 효과를 평균한 값입니다.","주어진 ry=27.6mm와 Cy=24.6mm를 조립축 기준으로 옮겨 rY=40.1mm를 구합니다":"조립축 기준으로 옮긴 결과 조립재의 반경은 rY=40.1mm입니다.","주요 구성요소는 압축기·응축기·증발기이다":"압축식 냉동기는 압축기, 응축기, 증발기가 주요 구성요소입니다.","주요구조부가 내화구조 또는 불연재료인 16층 이상 공동주택은 최대 40m입니다":"16층 이상 공동주택은 주요구조부가 내화구조나 불연재료일 때 보행거리가 최대 40m입니다.","주요구조부가 내화구조 또는 불연재료인 건축물의 내화구획은 연면적 1,000m² 초과이고, 대규모 건축물 방화벽의 공통 빈칸도 1,000m²였습니다":"내화구획과 대규모 건축물의 방화벽은 연면적 1,000m²라는 같은 숫자를 경계로 삼습니다.","주요구조부가 내화구조이고 15층이며 공동주택이 아니면 최대 50m입니다":"주요구조부가 내화구조인 15층 비공동주택은 계단까지 걸어서 최대 50m입니다.","주요구조부를 내화구조로 하고, 두 용도를 이웃하지 않게 배치하며, 내화구조의 바닥과 벽으로 차단합니다. 두 출입구의 보행거리는 30m 이상입니다":"공동주택과 위락시설 복합건축물은 두 용도를 내화구조 바닥·벽으로 가르고 두 출입구를 보행거리 30m 이상 띄웁니다.","주위 흙과의 마찰력으로 지지됩니다":"마찰말뚝은 말뚝 둘레 흙과의 마찰력으로 지지됩니다.","주차대수 30대마다 승강기 1대를 설치합니다":"자동차용 승강기는 주차대수 30대마다 한 대씩 설치합니다.","주차대수가 20대를 초과하는 매 20대마다 1대분 확보":"정류장은 주차대수 20대를 넘는 매 20대마다 한 대분을 확보합니다.","주차바닥면부터 2.3m 이상입니다":"경사로의 높이는 주차바닥면부터 2.3m 이상 확보해야 합니다.","주차장 규모·건축물 층수·용도별 면적":"건축계획서에는 주차장 규모, 건축물 층수, 용도별 면적을 표시합니다.","주차장 부분은 최소 70%가 기준입니다":"주차전용건축물은 주차장 부분이 연면적의 최소 70% 이상이어야 합니다.","주차장 외에 함께 둘 수 있는 용도는 자동차관련시설, 문화 및 집회시설, 제1종·제2종 근린생활시설, 운동시설, 종교시설, 업무시설입니다":"주차장 외에 자동차관련시설, 문화 및 집회시설, 근린생활시설, 운동시설, 종교시설, 업무시설을 함께 둘 수 있습니다.","주차장의 설치·정비 및 관리, 광역시설의 배치·규모·설치, 광역계획권의 공간 구조와 기능 분담은 기본계획의 내용이 아닙니다":"주차장 설치·정비·관리, 광역시설 배치, 광역계획권 공간 구조는 기본계획 내용이 아닙니다.","주차전용건축물 규정과 관계없는 항목입니다":"대지안의 공지는 주차전용건축물 규정과 관계없는 항목이라는 구분입니다.","주철근 최소 개수도 6개가 아님":"직사각형 띠철근 기둥에서 주철근 최소 개수를 6개로 보는 것은 틀립니다.","주택 내부 공간에 변화를 주고 다양한 평면을 구성할 수 있습니다":"메조넷은 한 집 안에 높낮이 변화를 줄 수 있어 평면을 여러 가지로 짤 수 있습니다.","주파수를 바꿔 속도를 제어한다":"인버터는 전원 주파수를 바꿔 유도전동기 속도를 제어합니다.","주행시간·도어개폐시간·승객출입시간이다":"엘리베이터 일주시간은 주행시간, 도어개폐시간, 승객출입시간으로 이루어집니다.","줄눈 너비 표준은 20mm가 아님":"타일 줄눈 너비 표준을 20mm로 보는 것은 틀립니다.","중고층주택 중심이면 제3종일반주거지역입니다":"중고층주택 중심의 주거환경을 위한 지역은 제3종일반주거지역입니다.","중력으로 필요한 곳에 급수합니다":"고가수조방식은 중력으로 필요한 곳에 급수합니다.","중력환기량은 개구부 면적이 클수록 증가하고 온도차가 클수록 증가한다":"중력환기량은 개구부 면적이 클수록, 온도차가 클수록 늘어납니다.","중립축에서 떨어진 A점의 전단응력은 τ=VQ/(It)로 구합니다":"중립축에서 떨어진 A점의 전단응력은 VQ를 It로 나눈 값입니다.","중립축에서 상방향 100mm 지점의 전단응력은 세 차례 모두 0.69MPa였습니다":"세 번 나온 문제 모두 중립축에서 위로 100mm 떨어진 점의 값이 0.69MPa였습니다.","중심부에 큰 홀을 두고 그 주위에 전시실을 배치하여 각 실에 자유롭게 출입하는 형식입니다":"중앙홀 형식은 한가운데 큰 홀을 두고 둘레의 전시실에 자유롭게 드나들게 합니다.","중앙부 8.75×10⁴N·m":"같은 방식으로 중앙부 정모멘트는 8.75×10⁴N·m입니다.","중앙부가 아니라 상·하단부에 더 많이 넣는다":"기둥 띠철근은 중앙부보다 상·하단부에 더 촘촘히 넣습니다.","중앙부를 가장 밝게 하거나 측면창 직접광을 쓰는 방식은 아니다":"정측광 방식 미술관은 중앙부를 제일 밝게 하는 것도, 옆 창의 직접광을 쓰는 것도 아닙니다.","중앙부보다 단부에 더 많이 넣는다":"단순보의 늑근은 중앙부보다 단부에 더 많이 넣습니다.","중앙부 하부에 많이 넣고 중요한 보는 복근보로 한다":"보 주근은 중앙부 아래쪽에 많이 넣고 중요한 보는 복근보로 합니다.","중앙홀이 크면 동선 혼란은 없지만 장래 확장은 어렵습니다":"중앙홀을 크게 잡으면 동선이 엉키지 않지만 훗날 늘리기는 힘듭니다.","중앙 홀 형식이나 순서대로 통과하는 구성이 아니다":"갤러리 및 코리도형은 중앙 홀 형식이나 차례로 통과하는 구성이 아닙니다.","중요시설·유해물질 저장 구조물이며 15층 이상 아파트·오피스텔이 해당한다":"내진등급 특은 중요시설이나 유해물질 저장 구조물을 가리키며 15층 이상 아파트·오피스텔도 여기 듭니다.","중층주택 중심이면 제2종일반주거지역입니다":"중층주택 중심의 주거환경을 위한 지역은 제2종일반주거지역입니다.","즉각처짐과 장기처짐으로 나뉘며 장기처짐은 크리프·건조수축으로 생긴다":"처짐은 바로 나타나는 즉각처짐과 시간이 지나 커지는 장기처짐으로 나뉘며 장기처짐은 크리프·건조수축에서 생깁니다.","증가할수록 감소하는 것은 연성입니다":"콘크리트 압축강도가 커질수록 줄어드는 성질은 연성입니다.","증기난방 계통에서 쓰는 장치이다":"증기트랩은 증기난방 계통에서 쓰는 장치입니다.","증기난방보다 부하 변동에 따른 온도조절이 쉽다":"증기난방과 비교하면 온수난방이 부하가 변할 때 온도를 맞추기 쉽습니다.","증기난방은 온수난방보다 열의 운반능력이 큽니다":"증기는 응축할 때 내놓는 잠열까지 쓰므로 온수보다 더 많은 열을 실어 나릅니다.","증기의 유량 제어가 어려워 실온 조절이 곤란합니다":"증기는 유량을 세밀하게 나누어 조절하기 어려워 방 온도를 맞추기 힘듭니다.","증발기, 흡수기, 재생기인 발생기, 응축기입니다":"흡수식 냉동기는 증발기, 흡수기, 재생기(발생기), 응축기 네 부분으로 이뤄집니다.","증축할 여지를 남기고 인공조명을 쓴다":"도서관 서고는 증축할 여지를 남기고 인공조명을 씁니다.","지구단위계획은 교통처리계획, 건축물의 용도 제한, 건폐율 또는 용적률을 포함합니다":"지구단위계획이 정하는 내용은 교통처리, 건축물 용도 제한, 건폐율·용적률 같은 항목입니다.","지구 전체에 분산하지 않습니다":"공공시설용지는 지구 전체에 분산하지 않습니다.","지나치게 크면 먼저 건축적인 수법으로 해결하며, 공조장치로만 처리하지 않습니다":"열손실이 너무 크면 공조장치만 키우지 않고 먼저 건축적인 방법으로 줄입니다.","지내력이 증가하고 지반의 안전성이 향상됩니다":"지하수를 빼면 땅이 지탱하는 힘이 커지고 지반이 더 안전해집니다.","지반의 저항력과 말뚝의 복합응력에 대한 안전성을 검토합니다":"말뚝기초는 충격력, 반복력, 횡력, 인발력에 대해 지반 저항력과 말뚝 복합응력의 안전성을 검토합니다.","지반 허용지지력을 구하는 것이 목적이며 재하판은 45cm각이고 2시간 0.1mm 이하 침하 시 정지한다":"평판재하시험은 지반 허용지지력을 구하며 재하판은 45cm각이고 2시간 동안 0.1mm 이하로 침하하면 정지로 봅니다.","지붕공사에 주로 사용하는 방수 재료는 아스팔트 콤파운드입니다":"지붕공사에 많이 쓰는 방수 재료로는 아스팔트 콤파운드를 듭니다.","지붕공사에 주로 쓰는 아스팔트 종류도 블로운 아스팔트입니다":"블로운 아스팔트도 지붕공사에 주로 쓰는 아스팔트입니다.","지붕면에서 수직 1m 이상이 원칙이고, 상단에서 수평 1m 이내에 다른 건축물이 있으면 그 처마보다 1m 이상 높게 합니다":"굴뚝은 지붕면에서 수직으로 1m 이상 올려야 하고 1m 이내에 다른 건물이 있으면 그 처마보다 1m 이상 높입니다.","지붕하중을 등분포로 전달하기 합리적이며 궁궐이나 사찰의 주요 정전에 쓰였습니다":"다포식은 기둥 사이에도 공포가 있어 지붕 무게를 고르게 전달해 궁궐과 사찰의 주요 건물에 쓰였습니다.","지역사회 이용, 학교운영방식 변화, 광범위한 교과내용 변화에 대응하는 것입니다":"학교 건축의 융통성이란 지역사회 이용, 운영방식 변화, 폭넓은 교과내용 변화에 맞춰 바뀔 수 있는 성질입니다.","지점 부근의 음의 모멘트와 중앙부의 양의 모멘트가 함께 후보가 됩니다":"내민보에서는 지점 부근의 음의 모멘트와 중앙부의 양의 모멘트가 절대 최대의 후보입니다.","지점에서의 전단력 변화는 지점반력과 연결해 읽습니다":"지점에서 전단력이 달라지는 크기는 지점반력과 연결해 읽습니다.","지점 처짐각의 크기는 ML/(2EI)입니다":"양 지점 모멘트 M이 순수 휨을 만들면 지점 처짐각의 크기는 ML/(2EI)입니다.","지지층에 확실히 도달시키고, 저부 단면을 확대한 경우 측면경사가 수직면과 이루는 각은 30° 이하입니다":"말뚝 선단부는 지지층에 확실히 닿게 하고 저부 단면을 키운 경우 측면경사가 수직면과 이루는 각은 30° 이하입니다.","지진응답계수와 거리가 멉니다":"가스트영향계수는 바람 하중 용어라서 지진응답계수와 거리가 멉니다.","지평식은 기계식 세분에 속하지 않는다":"지평식은 기계식 주차장의 세분 종류에 들지 않습니다.","지표면 1m 이하 부분은 제외하고 차양·부연은 제외되지 않는다":"건축면적에서 지표면 1m 이하 부분은 빼고 차양과 부연은 빼지 않습니다.","지하식·건축물식·공작물식으로 나뉜다":"기계식 주차장은 지하식, 건축물식, 공작물식으로 나뉩니다.","지하주차장처럼 지하층에만 운행하는 경우에 적용할 수 있다":"유압식 엘리베이터는 지하주차장처럼 지하층에만 다니는 경우에 쓸 수 있습니다.","지하층과 피난층 사이의 개방공간 기준은 3000㎡입니다":"지하층과 피난층 사이 개방공간의 기준값은 3000㎡라는 수치로 정해져 있습니다.","지하층 바닥면적이 300㎡ 이상이면 식수 공급용 급수전을 1개소 이상 둡니다":"지하층이 300㎡ 이상이면 사람이 마실 물을 받을 급수전을 하나 이상 갖춰야 합니다.","지하층 바닥에서 비상탈출구 아랫부분까지 높이가 1.2m 이상이면":"비상탈출구 아랫부분이 바닥에서 1.2m 이상 높게 달리면 사다리를 둬야 한다는 조건입니다.","직사각형 단면의 단면2차모멘트는 춤 h의 세제곱에 비례합니다":"직사각형 단면의 I는 춤 h를 세제곱한 값에 비례합니다.","직선부분 종단구배 17% 초과 금지, 직선형 1차선 너비 3.3m 이상입니다":"경사로 직선부분 종단구배는 17%를 넘으면 안 되고 직선형 한 차선 너비는 3.3m 이상입니다.","직접조명형은 작업면에 고조도를 얻을 수 있습니다":"직접조명형은 작업면에 높은 조도를 줍니다.","직접 출입·독립 폐쇄·복도 전시":"갤러리 및 코리더의 특징어는 직접 출입, 독립 폐쇄, 복도 전시입니다.","직접 콘크리트에 매설할 수 있는 공사는 금속관 공사입니다":"콘크리트에 직접 묻을 수 있는 배선 공사는 금속관 공사입니다.","진료검사에 시간이 걸리므로 소진료실을 다수 설치합니다":"내과는 진료와 검사에 시간이 걸려 작은 진료실을 여러 개 마련합니다.","질감·밀도·조경 변화를 주고 광장·유보로를 둠":"보행로에는 질감, 밀도, 조경에 변화를 주고 광장과 유보로를 둡니다.","집중하중은 기울기를 바꿉니다":"집중하중은 휨모멘트도의 기울기를 바꿉니다.","집회실 또는 관람석 및 집회실의 바닥면적 합계 200㎡가 기준입니다":"장례식장은 집회실 면적 합계가 200㎡인지로 대상 여부를 정합니다.","차동식을 많이 쓰며 연기감지기도 가능하다":"일반사무실에는 차동식 감지기를 많이 쓰며 연기감지기도 쓸 수 있습니다.","차동식·정온식을 합친 것이 아니다":"광전식은 차동식과 정온식을 합친 감지기가 아닙니다.","창문·출입구·기타 개구부를 제외하고 건축물의 다른 부분과 내화구조의 벽으로 구획합니다":"계단실은 창문·출입구·개구부를 뺀 나머지를 다른 부분과 내화구조 벽으로 구획합니다.","창문·출입구·기타 개구부를 제외한 부분은 다른 부분과 내화구조의 바닥과 벽으로 구획합니다":"승강장은 개구부를 뺀 나머지 부분을 내화구조 바닥과 벽으로 다른 부분과 구획합니다.","채광에 지장이 없는 범위에서 깊게 하여 외측면을 줄이면 에너지 절약에 유리합니다":"외측면이 줄도록 단위평면을 깊게 하되 채광에 지장이 없는 한도까지만 합니다.","채광·통풍과 프라이버시에는 유리하지만, 화재 때 대피에는 불리할 수 있습니다":"통로 없는 층은 채광·통풍·프라이버시가 좋은 반면 불이 났을 때 대피가 불리할 수 있습니다.","책을 자유롭게 선택하고 직접 뽑는 데까지는 자유개가식과 같습니다":"안전개가식도 이용자가 책을 마음대로 고르고 직접 빼는 점은 자유개가식과 같습니다.","책의 내용 파악과 선택이 자유롭고 대출 수속도 간편합니다":"자유개가식은 책 내용을 파악하고 선택하기 자유로우며 대출 수속도 간편합니다.","천장면 이용 건축화 조명이다":"코브, 코퍼, 광천장 조명은 천장면을 이용하는 건축화 조명입니다.","천장이 높은 실에서도 난방감을 얻을 수 있고":"열이 사람과 물체에 직접 닿는 복사 방식이라 높은 천장에서도 아래쪽이 따뜻해집니다.","철골 골조 주위에 철근을 배근하고 거푸집을 짜 콘크리트를 타설한 구조이며, 내진성이 뛰어나고 철골조보다 내화적입니다":"SRC는 철골 골조 둘레에 철근을 배치하고 거푸집을 짜 콘크리트를 부은 구조로 내진성이 뛰어나고 철골조보다 불에 강합니다.","철골철근콘크리트구조는 해당하지 않음":"도시계획시설 예정지 가설건축물은 철골철근콘크리트구조로 허가받을 수 없습니다.","철골트러스는 직선 부재로만 구성되지만 비정형 건축물의 구조체에 도입하기 어렵지 않습니다":"철골트러스는 곧은 부재만으로 짜지만 비정형 건축물 구조체에 쓰기 어렵지 않습니다.","철근배근 위치·에폭시 도막·경량콘크리트 계수가 있다":"보정계수에는 철근배근 위치, 에폭시 도막, 경량콘크리트 계수가 있습니다.","철근을 배치합니다. 정·부철근 간격의 기준은 600mm 이하가 아닙니다":"단순받침부에도 철근을 배치하며 정·부철근 간격의 기준은 600mm 이하가 아닙니다.","철근의 부식과 화해를 막는 것도 이유입니다":"철근이 녹슬거나 화재로 상하는 것을 막는 것도 피복두께의 이유입니다.","철근 인장력이 크기 때문이 아니다":"과소철근 보 설계는 철근 인장력이 크기 때문에 하는 것이 아닙니다.","철근 지름을 확인합니다. D16 이하는 40mm, D25인 철근은 50mm입니다":"철근 지름을 먼저 보고 D16 이하는 40mm, D25는 50mm로 구분합니다.","철근콘크리트조 기둥의 작은 지름 20cm 이상은 부적합합니다":"철근콘크리트조 기둥은 작은 지름이 20cm 이상이라는 수치로는 내화 기준에 부적합합니다.","철근콘크리트조 보·지붕, 두께 10cm 바닥은 내화구조이다":"보와 지붕을 철근콘크리트조로 하거나 바닥 두께를 10cm로 하면 내화구조로 인정됩니다.","철근 항복변형률을 fy/Es로 구합니다":"항복변형률은 fy를 Es로 나누어 얻습니다.","첨두 아치와 펜덴티브 돔은 특징이 아니다":"첨두 아치와 펜덴티브 돔은 로마네스크 건축의 특징이 아닙니다.","첫 작업의 EST는 프로젝트 개시시간과 같고, EFT는 EST에 소요일수를 더합니다":"첫 작업의 EST는 프로젝트가 시작되는 때와 같고 EFT는 EST에 소요일수를 보탠 값입니다.","청소용 배수밸브 또는 배수관을 둡니다":"수조 밑부분에는 청소용 배수밸브 또는 배수관을 둡니다.","초고층·대규모 빌딩은 건물 전체를 몇 개의 서비스 그룹으로 나누는 죠닝을 검토합니다":"건물을 몇 개 서비스 그룹으로 나누어 운행하는 죠닝은 초고층·대규모 빌딩에서 검토합니다.","초등학교 고학년과 우리나라 중학교에서 일반적으로 사용됩니다":"일반·특별교실형은 초등학교 고학년과 우리나라 중학교에서 일반적으로 씁니다.","초벌 뒤 바로 고름질하거나 바닥에 물이 고인 채 모르타르를 바르면 안 됩니다":"초벌을 바른 직후 고름질하거나 물이 고인 바닥에 모르타르를 바르는 것은 허용되지 않습니다.","초벌바름보다 부배합으로 하지 않습니다":"정벌바름은 초벌바름보다 시멘트를 많이 넣은 부배합으로 하지 않습니다.","총길이 L에서 유효길이를 구한 뒤":"총길이 L에서 유효길이를 먼저 얻습니다.","총면적 한도는 주차장 총시설면적의 20%입니다":"노외주차장 부대시설의 총면적 한도는 주차장 총시설면적의 20%입니다.","총 부하설비용량에서 최대수요전력이 차지하는 비율입니다":"수용률이란 설비용량의 합계 중 최대수요전력이 차지하는 몫입니다.","최대값은 여기에 단면 형상에 맞는 계수를 곱해 구합니다":"평균값에 단면 모양별 계수를 곱하면 최대값이 됩니다.","최대길이 기준도 1km가 아님":"쿨데삭 도로의 최대길이 기준을 1km로 보는 것은 틀립니다.","최대모멘트는 먼저 전단력의 부호가 바뀌는 지점이나 V=0이 되는 위치를 찾습니다":"최대모멘트는 전단력이 0이 되어 부호를 바꾸는 위치에서 생기므로 그 위치부터 찾습니다.","최대 방수구역의 헤드 수를 먼저 봅니다":"개방형 헤드는 최대 방수구역에 몇 개의 헤드가 있는지부터 봅니다.","최대수요전력에서 평균전력이 차지하는 비율입니다":"부하율은 최대수요전력 가운데 평균전력이 차지하는 비율입니다.","최대수요전력은 총 부하설비용량에 수용률을 곱합니다":"총 부하설비용량에 수용률을 곱하면 최대수요전력이 됩니다.","최대전단응력도 같은 식으로 구하면 0.3MPa입니다":"같은 식을 적용하면 최대전단응력도는 0.3MPa가 됩니다.","최대 전단응력은 그 전단력과 주어진 단면의 형상·치수를 함께 사용해 구합니다":"그 전단력에 주어진 단면의 형상과 치수를 함께 써서 최대 전단응력을 구합니다.","최대지름 3.2cm 이상 3.8cm 이하이고":"난간·벽 손잡이는 최대지름이 3.2cm 이상 3.8cm 이하여야 합니다.","최대 처짐 PL³/(48EI), 지점 처짐각 PL²/(16EI)입니다":"중앙 집중하중 P를 받는 단순보의 최대 처짐은 PL³/(48EI), 지점 처짐각은 PL²/(16EI)입니다.","최대 처짐은 5wL⁴/(384EI)입니다":"등분포하중 w를 받는 단순보의 최대 처짐은 5wL⁴/(384EI)입니다.","최대 처짐은 L³에 비례합니다":"집중하중을 받는 보의 최대 처짐은 경간 L³에 비례합니다.","최대 처짐은 L⁴에 비례합니다":"등분포하중을 받는 보의 최대 처짐은 경간 L⁴에 비례합니다.","최대철근비를 균형철근비의 75%로 잡으므로 ρb=0.0293이면 0.0220입니다":"구기준은 균형철근비의 75%를 최대철근비로 보아 ρb=0.0293이면 0.0220이 나옵니다.","최대 크기가 작을수록 시멘트 사용량이 적은 것은 아닙니다":"모래의 최대 크기가 작다고 시멘트 사용량이 적어지는 것은 아닙니다.","최대 휨응력은 플랜지 바깥면에 생기고, 판보의 웨브 좌굴 방지에는 스티프너를 씁니다":"판보에서 최대 휨응력은 플랜지 바깥 면에 걸리고 웨브 좌굴은 스티프너로 막습니다.","최소 30분에 1회 온도를 측정하고, 접착력 저하 방지를 위해 200℃ 이하가 되지 않도록 하며, 용융솥은 시공장소 가까이에 둡니다":"용융 아스팔트는 30분에 한 번 이상 온도를 재고 접착력이 떨어지지 않도록 200℃ 아래로 내려가지 않게 하며 솥을 가까이 둡니다.","최소면적은 100m2가 아니다":"공업지역과 상업지역의 대지 분할 최소면적을 100m2로 보는 것은 틀립니다.","최소 유효너비도 0.9m 이상입니다":"바깥쪽 피난계단의 최소 유효너비도 0.9m 이상입니다.","최소철근비는 1.4/fy이며 fy의 단위는 MPa입니다":"보의 최소철근비 식은 1.4/fy이고 이때 fy는 MPa 단위입니다.","최소 치수 200mm, 최소 단면적 60,000mm2, 주근 4개 이상이다":"직사각형 기둥은 최소 치수가 200mm 이상, 최소 단면적이 60,000mm2 이상이며 주근을 4개 이상 넣어야 합니다.","최소 치수는 300mm가 아님":"띠철근 압축부재의 최소 치수를 300mm로 정한 것은 규정이 아닙니다.","축동력 20.4kW에 여유율 10%를 적용하면 약 22.5kW입니다":"20.4kW인 축동력에 여유율 10%를 얹으면 소요동력은 약 22.5kW입니다.","축이 바뀌면 I가 바뀌고 반경도 바뀝니다":"기준 축이 달라지면 I 값이 변하므로 반경도 함께 변합니다.","출력 30% 이하에서는 서징 현상으로 운전이 곤란합니다":"서징은 부하가 낮을 때 냉매 흐름이 맥동하는 불안정 현상이라 출력이 일정 비율 아래면 운전이 어렵습니다.","출발은 평균전단응력 τ평균=V/A입니다":"평균전단응력 τ평균=V/A에서 출발합니다.","출입구까지 벽으로 막는 것이 아니라, 문이 닫히면 보일러가스가 거실로 들어가지 않는 구조로 합니다":"출입구까지 벽으로 막는 것이 아니라 문을 닫으면 보일러가스가 거실로 새어들지 않게 만듭니다.","출입구와는 3m 이상 떨어뜨립니다":"비상탈출구는 출입구와 3m 이상 간격을 둡니다.","춤을 2배로 하면 처짐은 1/8이 됩니다":"춤을 2배로 키우면 처짐은 1/8로 줄어듭니다.","충분한 교사 수와 적당한 시설이 없으면 실시하기 어렵습니다":"플래툰형은 교사가 넉넉하고 시설이 맞아야 하므로 조건이 안 되면 하기 어렵습니다.","층고 3m, 각 층 1,000㎡인 15층 오피스텔을 매층 150㎡마다 방화구획하면 설치가 필요없습니다":"층고 3m에 15층 오피스텔도 매층 150㎡마다 방화구획하면 비상용승강기가 필요 없습니다.","층별 면적만 나오면 6층부터 최상층까지 몇 층인지 세어 곱하십시오":"층별 면적만 주어지면 6층부터 최상층까지 층 수를 세어 층별 면적에 곱해 합합니다.","칠하기 전에 오염과 부착물을 제거하고, 송진을 처리하며, 옹이땜을 합니다":"목부 바탕 만들기는 칠하기 전에 오염과 부착물을 없애고 송진을 처리하며 옹이땜을 하는 일입니다.","침의 관입저항으로 견고성을 보는 값은 침입도입니다":"아스팔트의 견고성은 침이 얼마나 파고드는지로 재며 그 값이 침입도입니다.","침입도가 크고 연화점이 높은 것을 사용합니다":"지붕방수에는 침입도가 크고 연화점이 높은 아스팔트를 고릅니다.","침입도 지수가 적은 것이 좋지는 않습니다":"한랭지에서 침입도 지수가 작은 아스팔트가 좋다는 말은 맞지 않습니다.","카가 최상층이나 최하층의 정상 운행위치를 넘어갔는지를 먼저 구분합니다":"카가 정상 운행위치를 벗어났는지 아닌지를 먼저 가르는 것이 첫 단계입니다.","캔틸레버에서 휨모멘트는 자유단 0에서 고정단 쪽으로 커집니다":"캔틸레버는 자유단에서 휨모멘트가 0이고 고정단 쪽으로 올수록 값이 늘어납니다.","커머셜·터미널·아파트먼트·레지덴셜 호텔이 속합니다":"시티 호텔에는 커머셜, 터미널, 아파트먼트, 레지덴셜 호텔이 속합니다.","커뮤니케이션의 융통성이 있고 작업 흐름의 연결이 쉽습니다":"오피스 랜드스케이핑은 칸막이가 적어 의사소통이 유연하고 작업 흐름도 쉽게 이어집니다.","코어가 사무실 공간과 간섭하는 정도가 작습니다":"외코어형은 코어가 사무실 공간을 침범하는 정도가 작습니다.","코어를 업무공간에서 따로 분리한 형식입니다":"독립코어형은 코어를 업무공간에서 떼어 놓은 형식입니다.","코어 이외의 피난시설이 더 필요해집니다":"편심코어에서 바닥면적이 커지면 코어 이외의 피난시설이 더 필요해집니다.","콘크리트 바닥 속에 설치하며, 커튼 월 설치나 선풍기·전화기·전열기 이용에 편리합니다":"플로어 덕트는 콘크리트 바닥 속에 묻어 커튼 월 설치나 선풍기·전화기·전열기 사용에 편리합니다.","콘크리트 압축강도 50kgf/cm2 이상이 확인될 때까지 존치합니다":"기초, 보옆, 기둥, 벽에 댄 판재는 콘크리트 압축강도가 50kgf/cm2 이상으로 확인된 뒤에 떼어 냅니다.","콘크리트 압축력 0.85fck·b·a와 철근 인장력 As·fy를 같게 두고 As를 바로 구합니다":"압축력 0.85fck·b·a와 인장력 As·fy가 같다고 놓으면 필요한 As가 바로 나옵니다.","콘크리트 압축력은 깊이 a의 한가운데에 작용하므로":"콘크리트 압축력은 깊이 a의 가운데 지점에 걸린다고 봅니다.","콘크리트의 동결융해 방지는 최소피복두께를 규정하는 이유가 아닙니다":"콘크리트 동결융해를 막는 것은 최소피복두께를 두는 이유에 들지 않습니다.","콘크리트 표면에서 주철근 표면까지가 아니다":"기둥 철근의 피복두께는 콘크리트 표면에서 주철근 표면까지를 말하는 것이 아닙니다.","크롬산아연을 안료로 한 도료로 알루미늄 녹막이 초벌칠에 쓴다":"징크로메이트 도료는 크롬산아연을 안료로 하며 알루미늄 녹막이 초벌칠에 씁니다.","크리프 계수·하중계수·콘크리트 강도 계수는 보정계수가 아니다":"크리프 계수, 하중계수, 콘크리트 강도 계수는 정착길이를 보정하는 값에 들지 않습니다.","큰 적재량으로 승강행정이 짧은 경우에도 적용할 수 있다":"유압식 엘리베이터는 적재량이 커도 승강행정이 짧은 경우에 쓸 수 있습니다.","큰 홀·부지 효율·확장 곤란":"중앙홀의 특징어는 큰 홀, 부지 효율, 확장 곤란입니다.","클럽 하우스와 비치 호텔은 시티 호텔이 아닙니다":"클럽 하우스와 비치 호텔은 도시형인 시티 호텔에 들지 않습니다.","타일 뒤 틈은 빗물 침입과 백화의 원인이 되고, 타일용 접착제는 초기 접착성이 높은 것이 좋습니다":"타일 뒤에 틈이 있으면 빗물이 스며들고 백화가 생기며 접착제는 처음부터 잘 붙는 것을 씁니다.","탄소량 0.5% 이하에 니켈·망간·크롬 등을 넣은 강이다":"구조용 특수강은 탄소량 0.5% 이하에 니켈, 망간, 크롬 등을 넣은 강입니다.","탈출구에서 복도나 직통계단까지 가는 피난통로도 유효너비 0.75m 이상으로 잡습니다":"탈출구 앞 통로의 폭도 탈출구와 같은 0.75m 이상이어야 합니다.","탱크 기초, 지수벽, 차폐콘크리트, 수중콘크리트와 구조물 보수에 쓰입니다":"프리팩트 콘크리트는 탱크 기초, 지수벽, 차폐콘크리트, 수중콘크리트, 구조물 보수에 알맞습니다.","탱크레스 부스터는 공기조화방식이 아닙니다":"탱크레스 부스터는 급수를 올려 보내는 장치라서 공기조화방식에 들지 않습니다.","턴키·CM·프로젝트관리 방식":"업무범위에 따른 계약 방식에는 턴키, CM, 프로젝트관리 방식이 있습니다.","토지의 이용 및 개발, 토지의 용도별 수요 및 공급, 공원·녹지를 한 세트로 잡습니다":"도시·군기본계획은 토지 이용·개발, 용도별 수요 및 공급, 공원·녹지를 한 묶음으로 다룹니다.","토지이용현황과 전반적인 주차수요를 참작한다":"노외주차장 계획 때 토지이용현황과 전반적인 주차수요를 헤아립니다.","토지이용 효율, 주거환경의 질 향상, 어린이공원 등 공공공간 확보도 장점입니다":"어린이공원 같은 공공공간을 확보하고 토지를 효율적으로 쓰며 주거환경의 질을 높이는 것도 공동주택의 장점입니다.","토출압력을 감지해 회전수를 제어하므로 압력변동이 비교적 적습니다":"변속방식은 토출압력을 감지해 회전수를 바꾸므로 압력이 크게 출렁이지 않습니다.","통로 없는 층으로 구분합니다. 여러 가지 평면을 짤 수 있습니다. 통로가 없는 층은 통풍과 채광을 확보하기 쉽습니다. 소규모 주택에 적용하면 경제적이지는 않습니다":"메조넷은 통로 없는 층으로 구분하며 평면을 다양하게 짤 수 있고 통풍·채광이 쉽지만 소규모 주택에는 경제적이지 않습니다.","통로와 공용면적이 적고 유효면적이 높으며, 같은 주거동에 서로 다른 모양의 세대를 배치할 수 있습니다":"스킵플로어형은 공용면적이 적어 유효면적이 높고 한 동에 모양이 다른 세대를 섞어 놓을 수 있습니다.","통합되며 소규모 아동 열람에 편리하지만, 서가 정리가 안 되면 혼란스럽습니다":"자유개가식은 서고와 열람실이 통합되어 소규모 아동 열람에 편리하지만 서가 정리가 안 되면 혼란스럽습니다.","통행량이 많은 고속도로는 근린주구단위를 분리하고, 주구 내부로 들어오는 자동차 통과진입은 최소화합니다":"통행량이 많은 고속도로는 근린주구단위를 나누는 경계로 삼고 주구 내부로 통과하는 진입은 최소화합니다.","통행부 면적이 작아 건물 이용도가 높고 프라이버시도 양호합니다":"홀형은 복도 같은 통행부가 작아 건물을 효율적으로 쓰고 프라이버시도 양호합니다.","투수성이 나쁜 점토질 지반에는 적합하지 않습니다":"물이 잘 통하지 않는 점토질 지반에는 이 배수공법이 맞지 않습니다.","투수성이 비교적 낮은 사질토층이나 사질실트층까지도 강제배수가 가능합니다":"투수성이 비교적 낮은 사질토층이나 사질실트층의 물까지도 억지로 빼낼 수 있습니다.","트란셉트와 나르텍스도 바실리카의 각부 명칭이다":"트란셉트와 나르텍스는 바실리카 평면의 한 부분을 가리키는 이름입니다.","특별교실을 쓰므로 학생의 이동이 있습니다":"일반·특별교실형은 특별교실을 쓰므로 학생의 이동이 있습니다.","특별한 경우를 제외하고 6개 이상 둡니다":"현장타설콘크리트말뚝의 주근은 특별한 경우가 아니면 6개 이상 둡니다.","특정용도제한지구·보존지구·개발진흥지구·고도지구·위락지구·미관지구·시설보호지구도 있었습니다":"개정되기 전 법에는 특정용도제한지구부터 시설보호지구까지 일곱 가지 지구가 더 있었습니다.","파괴 때 소성거동으로 잡으며 탄성거동으로 보지 않습니다":"항복선 이론은 파괴 직전을 소성거동으로 가정하고 탄성거동으로 보지 않습니다.","파빌리온 타입보다 블록 타입이 유리합니다":"도심의 병원은 널찍하게 펼친 파빌리온 타입보다 한 덩어리로 모은 블록 타입이 유리합니다.","판매시설, 창고시설, 문화 및 집회시설 중 전시장은 대상입니다":"면적이 같아도 판매·창고시설과 전시장은 내화구조를 갖춰야 하는 쪽입니다.","판매시설→문화 및 집회시설, 주거업무시설군→근린생활시설군, 교육 및 복지시설군→문화 및 집회시설군은 허가 사례입니다":"판매시설에서 문화 및 집회시설로 옮기는 등 반대 방향 변경은 허가를 받아야 합니다.","판매시설·업무시설 2,000m2":"판매시설과 업무시설은 2,000m2여도 설비기술사 협력 대상이 아닙니다.","판정은 건축물 연면적 중 주차장으로 쓰는 부분의 비율로 합니다":"주차전용건축물인지는 전체 연면적 가운데 주차장 몫이 얼마인지로 가립니다.","팬코일 유니트는 물을 쓰는 전수방식입니다":"팬코일 유니트는 물이 열을 나르는 전수방식으로 분류합니다.","펌프 구경은 양수량 Q=유속×단면적 관계로 구합니다":"펌프 구경은 Q=유속×단면적에서 단면적을 구해 정합니다.","펌프로 냉·온수를 이송하므로 송풍기로 공기를 이송하는 것보다 이송동력이 적게 듭니다":"물은 공기보다 같은 열을 싣는 부피가 작아서 펌프로 보내는 쪽이 송풍기보다 동력이 적게 듭니다.","펌프에 기대지 않으므로 정전으로 인한 단수 염려도 없습니다":"수도직결방식은 펌프에 기대지 않아 정전으로 인한 단수 염려도 없습니다.","펌프직송방식보다 수질오염 가능성이 크다는 특징으로 구분합니다":"고가수조방식은 펌프직송방식에 비해 수질오염 가능성이 크다는 점이 특징입니다.","펌프 회전수에 비례하므로 회전수를 20% 올리면 양수량도 20% 증가합니다":"양수량은 회전수와 비례하므로 회전수가 20% 오르면 양수량도 20% 늘어납니다.","페놀·요소·멜라민은 열경화성이므로 이 네 가지와 구분합니다":"페놀, 요소, 멜라민은 열경화성이므로 열가소성 수지 네 가지와 구분합니다.","페놀은 접착성과 전기 절연성, 요소는 무색과 자유로운 착색, 실리콘은 내열성과 발포보온재로 연결합니다":"수지별 특징은 페놀이 접착성·전기 절연성, 요소가 무색·자유로운 착색, 실리콘이 내열성·발포보온재와 이어집니다.","펜덴티브 돔·도저렛이 특징이다":"비잔틴 건축은 펜덴티브 돔과 도저렛이 특징입니다.","평면충격에 약해 좌굴되는 배관이 아니다":"아연도강관은 평면충격에 약해 좌굴되는 배관이라는 말은 맞지 않습니다.","평형식에서 a만 남기면 a = As·fy ÷ (0.85·fck·b)입니다":"평형식을 a에 대해 풀면 a = As·fy ÷ (0.85·fck·b)가 됩니다.","평형식의 As를 넣으면 철근비 = 0.85·fck·a/(fy·d)로 바로 정리됩니다":"평형식에 철근량을 넣어 정리하면 철근비는 0.85·fck·a를 fy·d로 나눈 값입니다.","폴리프로필렌, 염화비닐, 폴리에틸렌, 폴리스티렌입니다":"열가소성 수지에는 폴리프로필렌, 염화비닐, 폴리에틸렌, 폴리스티렌이 있습니다.","폴리프로필렌과 달리 열경화성입니다":"폴리에스테르와 에폭시는 폴리프로필렌과 달리 열경화성입니다.","표면온도가 노점온도보다 높으면":"표면온도가 노점온도보다 높으면 표면에 결로가 생기지 않습니다.","풍력환기량은 풍속이 높을수록 증가하고 유량계수에 비례한다":"풍력환기량은 풍속이 높을수록, 유량계수가 클수록 늘어납니다.","프라이머의 건조상태를 확인한 뒤 시트를 깔며, 옥상에서는 특수부위 보강붙이기를 평탄부 시트깔기 뒤로 미루지 않습니다":"옥상 시트방수는 프라이머가 말랐는지 본 뒤 시트를 깔고 특수부위 보강붙이기를 평탄부 시트깔기보다 뒤로 미루지 않습니다.","프라이버시가 좋고 건물 이용도가 높습니다":"프라이버시가 좋고 건물을 효율적으로 쓰는 형식은 계단실형입니다.","프라이버시도 나쁘고 시끄럽습니다. 세대별 조망도 다릅니다":"집중형은 프라이버시가 나쁘고 시끄러우며 세대별 조망도 다릅니다.","프라이버시와 거주성이 가장 양호한 형식입니다":"프라이버시와 거주성이 가장 좋은 평면형식은 계단실형입니다.","프라이버시와 독립성이 좋고, 양면 개구로 일조·채광·통풍·전망을 확보하기 좋습니다":"메조넷은 독립성과 프라이버시가 좋고 양쪽에 창을 내 햇빛, 채광, 통풍, 전망을 얻기 좋습니다.","프로시니엄 높이의 약 3배로 봅니다":"사이클로라마 높이는 프로시니엄 높이의 약 3배로 봅니다.","프리텐션·포스트텐션 방식은 SRC 설명과 관계없습니다":"프리텐션과 포스트텐션 방식은 SRC를 설명할 때 나오지 않습니다.","플랜지 두께를 제외해 전단면적을 산정하라고 하면 Aw=(H-2tf)tw로 잡습니다":"플랜지 두께를 빼야 하는 조건이면 전단면적 Aw에 (H-2tf)tw를 씁니다.","플러시 밸브나 수전류의 급격한 개폐":"플러시 밸브나 수전류가 급격히 열리고 닫히면 수격작용이 생깁니다.","피난안전구역 높이는 2.1m 이상이고 내부마감은 불연재료이며, 내부에서 통하는 계단은 특별피난계단 구조입니다":"피난안전구역은 높이 2.1m 이상에 내부마감 불연재료이고 연결 계단은 특별피난계단 구조여야 합니다.","피막과 광택, 접착성, 기밀성, 안정성이 있고 내열성·내화성은 작습니다":"합성수지는 피막, 광택, 접착성, 기밀성, 안정성이 장점이고 열과 불에는 약합니다.","피복 확보용 고임재와 간격재를 적절히 배치하고, 조립 뒤 오래 지났다면 타설 전에 다시 검사하고 청소합니다":"철근 피복을 지키려고 고임재와 간격재를 알맞게 놓고 조립한 지 오래됐으면 타설 전에 다시 검사하고 청소합니다.","필요하면 독립적으로 폐쇄할 수 있다":"미술관 전시실은 필요하면 독립적으로 닫을 수 있어야 합니다.","필요한 본관 압력은 이 세 가지를 더해 구합니다":"필요한 본관 압력은 이렇게 세 값을 합쳐 얻습니다.","필요한 총너비를 각 출구의 유효너비로 나눕니다":"필요한 총너비를 각 출구의 유효너비로 나누면 필요한 출구 수가 나옵니다.","하나의 전용회로에 비상콘센트 10개 이하":"하나의 전용회로에 달 수 있는 비상콘센트는 10개 이하입니다.","하나의 주거단위가 복층을 쓰는 형식입니다":"메조넷형은 한 세대가 위아래 두 층을 함께 쓰는 형식입니다.","하나의 초등학교가 필요한 인구를 한 단위로 잡고, 물리적 크기는 인구밀도에 따라 정합니다":"근린주구 인구는 초등학교 하나가 필요한 인구를 한 단위로 잡고 물리적 크기는 인구밀도로 정합니다.","하나의 헤드 선단에서 1kg/cm² 이상 12kg/cm² 이하의 방수압력이 되게 하는 크기입니다":"정격토출압력은 헤드 하나의 끝에서 1kg/cm² 이상 12kg/cm² 이하의 방수압력이 나오게 하는 크기를 뜻합니다.","하루 높이 1.2m(최대 1.5m)":"벽돌은 하루에 1.2m 높이로 쌓고 많아도 1.5m를 넘지 않습니다.","하부 물드럼과 상부 기수드럼을 다수의 관으로 연결하고, 그 관들을 연소실 주위에 배치합니다":"수관보일러는 아래 물드럼과 위 기수드럼을 여러 관으로 이어 연소실 둘레에 둔 구조입니다.","하중들의 고정단에 대한 모멘트를 모두 합쳐 평형시키면":"고정단 기준으로 하중 하나하나의 모멘트를 더해 균형 방정식을 세웁니다.","하중 방향과 선택지의 부호 방향을 맞춥니다":"하중이 가해지는 방향과 선택지에 적힌 부호 방향을 서로 맞춰 읽습니다.","하중은 판 전체에 등분포되어야 합니다. 특정 지점의 집중하중이 있으면 적용할 수 없습니다":"하중은 판 전체에 고르게 퍼져 있어야 하며 한 지점의 집중하중이 있으면 이 방법을 쓸 수 없습니다.","학교시설·공용시설·항만시설 보호입니다":"시설보호지구는 학교시설, 공용시설, 항만시설을 보호하는 지구로 세분됩니다.","학교시설·항만·공용시설·항공기 안전운항을 보호한다":"시설보호지구는 학교시설, 항만, 공용시설, 항공기 안전운항을 보호합니다.","학교시설·항만시설·공용시설 보호지구이다":"시설보호지구는 학교시설, 항만시설, 공용시설 보호지구로 세분됩니다.","학교의 교실, 도서관, 대학교는 모두 설치 대상이 아닙니다":"학교의 교실, 도서관, 대학교는 교육 용도 중에서 배연설비 설치 대상에서 빠집니다.","학급과 학년을 없애고 학생이 능력에 맞춰 교과를 선택합니다":"달톤형은 학급과 학년을 두지 않고 학생이 능력에 맞는 교과를 골라 배우는 방식입니다.","학생 이동이 심하므로 동선계획이 중요하고, 소지품을 둘 곳도 별도로 필요합니다":"교과교실형은 학생이 많이 움직여 동선 계획이 중요하고 소지품을 보관할 곳도 따로 필요합니다.","학생이 이용하기 쉬운 곳에 두고 지역주민 이용도 고려한다":"학교 실내체육관은 학생이 이용하기 쉬운 곳에 두고 지역주민 이용도 고려합니다.","한계 이상의 학생 수 증가는 융통성으로 해결할 대상이 아닙니다":"정해진 한계를 넘는 학생 증가는 융통성으로 풀 문제가 아닙니다.","한 기구트랩마다 통기관을 두므로 가장 안정적이고 자기사이폰 작용 방지에도 효과가 있습니다":"각개통기는 기구트랩마다 통기관을 둬서 가장 안정적이고 자기사이폰 작용도 막는 효과가 있습니다.","한 대당 10.0m²가 최소입니다":"주차구획은 한 대당 10.0m²가 최소 면적입니다.","한 면의 유효면적을 구한 뒤 양면이면 2를 곱합니다":"한 면의 유효면적을 구해 놓고 양면 용접이면 2배 합니다.","한 방향만 지지하면 그 방향의 길이만 줄여 계산하고, 다른 방향도 따로 계산한 뒤 더 큰 세장비를 택합니다":"가새로 한 방향만 붙잡으면 그 방향 길이만 줄여 계산하고 다른 방향과 비교해 큰 세장비를 씁니다.","한 번에 두껍게 만들지 않습니다. 얇게 몇 회로 나누어 도장합니다":"도막은 한꺼번에 두껍게 만들지 않고 얇게 여러 번 나눠 칠합니다.","한 분단이 일반교실을 쓸 때 다른 분단은 특별교실을 쓰며, 교과 담임제와 학급 담임제를 병용할 수 있습니다":"플래툰형은 한 분단이 일반교실에 있을 때 다른 분단이 특별교실에 있도록 짜며 교과 담임제와 학급 담임제를 함께 쓸 수 있습니다.","한 실을 폐쇄하면 다음 실로 갈 수 없어 대규모 미술관에는 바람직하지 않습니다":"연속순로는 한 전시실을 닫으면 그다음 실로 못 가므로 규모가 큰 미술관에는 알맞지 않습니다.","한 점에 작용하는 집중모멘트는 그 점에서 휨모멘트도를 불연속으로 바꿉니다":"한 점에 모멘트가 걸리면 그 점에서 휨모멘트도가 끊어져 불연속이 됩니다.","한 주거단위가 동일층 안에서 끝납니다":"플랫형은 한 주거단위가 동일층 안에서 끝나는 형식입니다.","한 축의 단면2차모멘트가 아니라 같은 점을 지나는 두 직교축 값의 합입니다":"단면극2차모멘트는 한 축의 값이 아니라 같은 점을 지나는 두 직교축 값을 더한 것입니다.","함께 나와도 상황으로 장치를 가립니다":"권상기, 완충기, 가이드 레일, 카운터 웨이트는 상황에 따라 맡는 일이 달라 구별해야 합니다.","함께 시설면적 150㎡당 1대입니다":"종교시설, 판매시설, 운수시설은 함께 시설면적 150㎡당 한 대로 계산합니다.","합성고무와 열가소성수지로 한 겹 방수하는 것은 시트방수이며, 돌 건식공법은 긴결철물이나 앵커철물·합성수지 접착제로 정착합니다":"합성고무나 열가소성수지를 한 겹 대는 방수가 시트방수이며 돌 건식공법은 앵커철물이나 접착제로 고정합니다.","합판 또는 널재의 대형패널을 구조내력부재로 씁니다":"목재패널구조는 합판이나 널재의 대형패널을 구조내력부재로 씁니다.","항복선을 지나는 철근은 완전히 항복합니다. 탄성변형은 소성변형에 비해 무시합니다":"항복선과 만나는 철근은 완전히 항복했다고 보고 탄성변형은 소성변형에 견줘 무시합니다.","해결은 유리하지 않고 경제적이지도 않습니다":"설비와 구조의 문제 해결은 메조넷에 유리하지 않고 경제적이지도 않습니다.","해당 용도 바닥면적 합계 200m² 이상이 기준입니다":"위락시설과 종교시설은 해당 용도 바닥면적 합계 200m² 이상이 직통계단 두 곳의 기준입니다.","해당 축의 단면2차모멘트를 단면적으로 나눈 뒤 제곱근을 취합니다":"단면2차반경 r은 그 축의 I를 A로 나눈 값의 제곱근입니다.","해변 호텔은 터미널 호텔이 아닙니다":"바닷가에 있는 해변 호텔은 교통 거점형인 터미널 호텔과 다릅니다.","해체 가능한 압축강도가 최저 120kgf/cm2입니다":"받침기둥을 해체하려면 콘크리트 압축강도가 최소 120kgf/cm2에 이르러야 합니다.","행정청이 설치하지 않은 광장도 공공시설이지만 저수지는 아닙니다":"광장은 행정청이 설치하지 않았어도 공공시설이지만 저수지는 공공시설이 아닙니다.","허가 건축물과 신고 건축물 모두 합니다. 공사 착수 전에 신고하세요":"허가받은 건축물과 신고한 건축물 모두 공사를 시작하기 전에 착공신고를 해야 합니다.","허가권자가 신청일부터 7일 이내 사용승인 검사":"허가권자는 사용승인 신청일부터 7일 이내에 검사를 해야 합니다.","허가 대상 건축물은 처마높이 9m 이상, 지진구역 안, 기둥 사이 거리 10m 이상입니다":"구조안전 확인서류는 처마높이 9m 이상, 지진구역 안, 기둥 사이 거리 10m 이상인 허가 대상 건축물에 냅니다.","허용전단력은 ‘기본 허용전단력×(1-작용인장력÷설계볼트장력)’으로 줄입니다":"인장력이 함께 걸리면 허용전단력은 기본 허용전단력에 (1-작용인장력÷설계볼트장력)을 곱해 줄입니다.","허용전류·전압강하·기계적 강도로 정한다":"간선 전선 굵기는 허용전류, 전압강하, 기계적 강도로 정합니다.","허용층간변위는 0.015hsx":"허용층간변위는 층높이 hsx의 0.015배로 제한됩니다.","헝겊 등이 봉수를 빨아내는 흡인식 사이폰 작용은 모세관현상입니다":"헝겊 같은 것이 봉수를 빨아내는 흡인 사이폰 작용을 모세관현상이라 합니다.","현장 가공·절단이 되지 않고":"강화유리는 현장에서 가공하거나 자를 수 없습니다.","현장 거푸집공사를 줄이며 정밀도가 높고 강도가 큰 콘크리트 부재를 사용할 수 있습니다":"조립식은 현장 거푸집공사를 줄이고 정밀도가 높고 강한 콘크리트 부재를 쓸 수 있습니다.","현재 경계선에서 소요너비의 절반을 물리는 방식이 아닙니다":"좁은 도로에서 경계선을 소요너비의 절반만큼 물리는 방식은 후퇴 기준이 아닙니다.","현존하는 가장 오래된 목조건축":"봉정사 극락전은 현존하는 가장 오래된 목조건축으로 꼽힙니다.","협업관리·정보 공유와 축적을 지원하며 공정 진척도를 구체적으로 측정할 수 있다":"PMIS는 협업 관리와 정보 공유·축적을 도우며 공정 진척도를 구체적으로 재는 데 쓸 수 있습니다.","형태는 지하식·지평식·건축물식이다":"자주식 주차장의 형태는 지하식, 지평식, 건축물식입니다.","호텔 40,000㎡는 200대입니다. 18홀 골프장은 180대이므로 합계는 380대입니다":"호텔은 40,000㎡로 200대, 골프장 18홀은 180대를 구해 더하면 380대가 나옵니다.","홀의 1인당 점유면적은 0.5~0.8m²로 계산합니다":"엘리베이터 홀은 1인당 0.5~0.8m²로 면적을 계산합니다.","화재 진압·인명구조용 소화활동설비":"비상콘센트는 화재 진압과 인명구조에 쓰는 소화활동설비입니다.","환경조절이 쉽다는 표현은 개실 시스템 쪽입니다":"환경조절이 쉽다는 설명은 개실 시스템 쪽에 해당합니다.","환경친화, 지형순응, 가변적 구조체이며 규격화·동일화된 단위평면은 해당하지 않습니다":"지속가능한 설계는 환경친화, 지형순응, 변경 가능한 구조체를 따르며 똑같이 규격화된 단위평면은 어긋납니다.","환기를 하고 배수·공기 흐름을 원활히 한다":"통기관은 배수관 안을 환기하고 배수와 공기의 흐름을 원활하게 합니다.","환기설비는 거실 바닥면적 합계 1,000m² 이상, 급수전 1개소 이상은 지하층 바닥면적 300m² 이상입니다":"지하층에서 환기설비는 1,000m² 이상 거실, 급수전은 300m² 이상 층에 붙는 설비입니다.","환기설비와 방화구획별 직통계단으로 연결합니다":"지하층 큰 면적 기준에서는 환기설비를 갖추고 방화구획마다 직통계단을 연결합니다.","환자 보호자의 간호가 불가능해지는 것은 병상수 과다와 관계가 먼 항목입니다":"보호자가 간호하지 못하게 되는 일은 병상 수가 너무 많아서 생기는 문제와 관련이 적습니다.","환자 이용이 편리하도록 2층 이하":"병원 외래진료부는 환자가 편하게 오도록 2층 이하에 둡니다.","회전자 저항을 바꾸는 비례추이 방식도 있다":"비례추이는 회전자 저항을 바꾸어 속도를 제어하는 방식입니다.","회전할 수 있으므로 그 점의 휨모멘트가 0입니다":"내부힌지는 회전할 수 있어 그 점의 휨모멘트가 0입니다.","후면에 창을 두기 어려우므로 세대 깊이는 너무 깊지 않게 하며, 각 세대 깊이를 7.5m 이상으로 해야 하는 것은 아닙니다":"뒤쪽에 창을 내기 어렵기 때문에 세대 깊이를 크게 하지 않으며 7.5m 이상이라는 기준은 없습니다.","휨모멘트는 두 단계 높은 3차가 됩니다":"휨모멘트는 하중보다 두 차수 높은 3차 곡선이 됩니다.","휨모멘트도가 주어지고 수평하중 P를 구하는 경우도 있습니다":"휨모멘트도가 먼저 주어지고 거꾸로 수평하중 P의 크기를 묻는 형태도 나옵니다.","휨모멘트도는 직선이 아니라 곡선입니다":"이 하중에서는 휨모멘트도가 직선이 아니라 곡선입니다.","휨모멘트도도 직선 조각으로 이어집니다":"분포하중이 없는 구간의 휨모멘트도는 직선 조각들로 이어집니다.","휨모멘트도의 높이가 아니라 변화량을 봅니다":"휨모멘트도에서는 높이 자체보다 변화량을 봅니다.","휨모멘트도 자체가 끊어지는 것이 아니라 직선의 기울기가 바뀝니다":"집중하중이 작용하는 점에서 휨모멘트도가 끊어지지 않고 직선의 기울기가 바뀝니다.","휨모멘트선은 2차곡선이 아닙니다":"직선적으로 변하는 등변분포하중의 휨모멘트선은 2차곡선이 아닙니다.","휨모멘트의 극대와 극소가 생깁니다":"그 위치에서 휨모멘트가 극대나 극소가 됩니다.","휨철근에 직각으로 둡니다. 1방향 슬래브의 수축·온도철근은 정철근·부철근과 평행하지 않습니다":"1방향 슬래브의 수축·온도철근은 휨철근에 직각으로 두며 정철근·부철근과 평행하지 않습니다.","휴양 콘도미니엄·가족호텔·여인숙이 해당한다":"숙박시설에는 휴양 콘도미니엄, 가족호텔, 여인숙이 해당합니다.","흙막이에 작용하는 토압이 줄어 흙막이 공사가 간단해집니다":"지하수위가 낮아지면 흙막이가 받는 흙의 압력이 줄어 흙막이 공사가 간단해집니다.","흙에 닿는 면에 거푸집을 대지 않고 시공하는 경우도 75mm입니다":"흙 쪽에 거푸집 없이 시공하는 옹벽 면도 최소피복두께가 75mm입니다.","흙에 접하여 콘크리트를 친 뒤 영구히 흙에 묻히는 현장치기 콘크리트는 75mm입니다":"영구히 흙 속에 묻히는 현장치기 콘크리트는 흙에 접해 쳤을 때 최소피복두께를 75mm로 둡니다.","흙에 접한다는 것만으로는 40mm가 아니며, 영구 매립과 거푸집 없음까지 확인합니다":"흙에 접한다고 모두 40mm가 아니고 영구 매립과 거푸집 없음 조건까지 함께 따집니다.","흙파기 밑면의 토질 약화를 예방합니다":"물을 빼면 흙파기 밑면의 토질이 약해지는 것을 예방합니다.","흡입베인 제어 또는 회전수 제어가 이용됩니다":"흡입베인은 압축기로 들어가는 냉매가스량을 조절하는 날개이며 회전수 조절과 함께 용량 조절에 씁니다.","흡입 실양정과 토출 실양정의 합이며, 흡수면부터 토출수면까지의 수직거리입니다":"실양정은 흡입 쪽과 토출 쪽 실양정을 합친 값이며 흡수면에서 토출수면까지의 높이차입니다.","희석제·용제로 쓰지 않습니다":"티탄백은 안료이므로 희석제나 용제로 쓰지 않습니다.","힌지에는 모멘트를 전달하지 않지만 힘은 전달되므로, 먼저 구한 힌지 힘을 반대쪽 조각에 크기는 같고 방향은 반대로 옮깁니다":"힌지는 힘은 건네고 모멘트는 건네지 못하므로 구한 힌지 힘을 반대쪽에 크기는 그대로 방향은 거꾸로 적용합니다.","힘과 모멘트는 휨모멘트도에 남기는 흔적이 다릅니다":"힘이 작용한 점과 모멘트가 작용한 점은 휨모멘트도에 나타나는 모습이 다릅니다.","힘의 평형과 모멘트의 평형으로 지점반력을 구합니다":"지점반력은 힘의 평형과 모멘트의 평형에서 얻습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
